window.__EVENTS__={"version":"events-2026.10.1","events":[{"id":"great-depression","title":"The 1929 crash and the Great Depression","years":"1929–1939","start":"1929-10","end":"1939","region":"United States and the gold-standard world","kind":"crisis","standfirst":"A stock market crash in October 1929 was followed by three years of collapsing output, prices and banks, and a decade of mass unemployment. The economic question is why a downturn that began like many others became the deepest slump of the industrial era.","question":"How did a stock market crash turn into a decade-long depression, and which policy choices made it deeper or ended it?","before":{"p":"The United States ended the 1920s as the world’s largest economy and a major creditor. Output had grown strongly through the decade, helped by electricity, cars and consumer durables bought on instalment credit. Consumer prices were broadly stable and even fell slightly in 1927 and 1928. Most major economies had returned to the gold standard, so each country’s money supply was tied to its gold reserves and interest rates were set with one eye on the exchange rate. Farm incomes were weak, and Germany’s ability to pay reparations depended heavily on borrowing from American lenders. From 1928 the Federal Reserve tightened policy, partly out of concern about credit flowing into stock market speculation.","facts":[{"t":"US consumer prices fell by 1.9% in 1927 and 1.2% in 1928, and were unchanged in 1929.","status":"fact"},{"t":"The S&P 500 composite’s monthly average rose from 17.53 in January 1928 to 31.3 in September 1929.","status":"fact"},{"t":"Britain returned to the gold standard in 1925 at its pre-war parity; most major economies had restored gold convertibility by the late 1920s.","status":"fact"},{"t":"Many share purchases were financed with broker loans (buying on margin), so falling prices could force investors to sell.","status":"fact"},{"t":"German reparations, Allied war debts and American lending formed a chain of international payments that depended on continued US capital outflows.","status":"interpretation"}]},"trigger":{"p":"Share prices peaked in early September 1929 and began to slide. On Thursday 24 October heavy selling overwhelmed the New York Stock Exchange; a pool of leading bankers bought shares to steady prices, but the support held only briefly. On 28 and 29 October prices fell steeply again, and margin calls forced further sales. Most economic historians treat the crash as the trigger rather than the full cause of the Depression: the slump deepened mainly through later banking panics, falling money and prices, and policy choices.","status":"fact"},"timeline":[{"d":"1928","t":"The Federal Reserve tightens","detail":"The Fed raised its discount rate in several steps during 1928, worried about credit fuelling stock speculation. Higher US rates also drew gold towards the United States, squeezing other gold-standard countries.","status":"fact"},{"d":"1929-10-24","t":"Black Thursday","detail":"Panic selling hit the New York Stock Exchange. Leading bankers organised purchases to support prices, which steadied the market for only a few days.","status":"fact"},{"d":"1929-10-29","t":"Black Tuesday deepens the crash","detail":"After a heavy fall on 28 October, another wave of selling followed on 29 October. The S&P 500 monthly average fell from 31.3 in September to 20.58 in November.","status":"fact"},{"d":"1930-06","t":"Smoot–Hawley tariff becomes law","detail":"President Hoover signed the Tariff Act of 1930, raising duties on many imports. Trading partners retaliated with their own barriers, and world trade shrank as the depression spread.","status":"fact"},{"d":"1930-12","t":"Bank of United States fails","detail":"The collapse of a large New York bank capped the first wave of US bank failures. Depositors withdrew cash, and banks hoarded reserves instead of lending.","status":"fact"},{"d":"1931-05","t":"Creditanstalt collapses in Vienna","detail":"The failure of Austria’s largest bank set off runs on banks and currencies across central Europe. In July 1931 the crisis reached Germany, where major banks closed temporarily.","status":"fact"},{"d":"1931-09","t":"Britain leaves gold","detail":"On 21 September 1931 Britain suspended gold convertibility and sterling depreciated. In October the Federal Reserve raised its discount rate sharply to stop gold leaving the United States.","status":"fact"},{"d":"1932","t":"The deepest year of the slump","detail":"US real GDP fell 12.9% and consumer prices fell 10.3%. The Reconstruction Finance Corporation began lending to banks and railways, while the Revenue Act of 1932 raised taxes.","status":"fact"},{"d":"1933-03","t":"Bank holiday and the New Deal","detail":"Franklin Roosevelt took office on 4 March amid a nationwide banking panic and closed the nation’s banks. The Emergency Banking Act let banks judged sound reopen, and deposits began to return.","status":"fact"},{"d":"1933-04","t":"The dollar leaves gold","detail":"Roosevelt restricted private gold holdings and exports, and the dollar was allowed to fall. The Gold Reserve Act of January 1934 fixed a higher official gold price, devaluing the dollar.","status":"fact"},{"d":"1937","t":"A recession within the Depression","detail":"The Fed doubled banks’ reserve requirements in 1936–37, the Treasury sterilised gold inflows and the budget deficit narrowed. Real GDP fell 3.3% in 1938 after four years of fast growth.","status":"fact"},{"d":"1941","t":"War demand absorbs spare capacity","detail":"Rearmament and war orders lifted spending sharply. US real GDP grew 17.7% in 1941, and unemployment fell from 9.9% in 1941 to 4.7% in 1942.","status":"fact"}],"actors":[{"who":"The Federal Reserve System","role":"The US central bank, then a loosely coordinated set of regional banks. It tightened in 1928–29 and did little to stop bank failures and the contraction of the money stock in 1930–33."},{"who":"Herbert Hoover","role":"President 1929–33. Urged firms to hold wages, signed the 1930 tariff, created the Reconstruction Finance Corporation and backed tax rises in 1932 to reduce the budget deficit."},{"who":"Franklin D. Roosevelt","role":"President from March 1933. Closed and reopened the banks, took the dollar off gold and launched the New Deal of relief, public works, regulation and social insurance."},{"who":"Depositors and commercial banks","role":"Fearing failures, depositors converted deposits into cash; banks kept larger reserves and cut lending. Their rational caution shrank the money stock and credit for the whole economy."},{"who":"Central banks abroad on gold","role":"Bound by gold-standard rules, they raised interest rates or restricted credit to protect reserves, spreading deflation; countries that left gold earlier generally began recovering sooner."},{"who":"John Maynard Keynes","role":"British economist whose General Theory (1936) argued that an economy could stay stuck with mass unemployment because aggregate demand was too weak, and that government spending could fill the gap."}],"changed":"Between 1929 and 1933 US nominal GDP fell from $104.6 billion to $57.2 billion, as both real output and prices collapsed. Thousands of banks failed, the money stock contracted and debts became heavier in real terms as prices fell. Private investment collapsed and unemployment rose to roughly a quarter of the labour force. World trade shrank behind tariffs and quotas. The state’s role grew: deposit insurance, securities regulation, social insurance and public works became lasting features of the US economy, and stabilising demand came to be seen as a task for government.","predict":{"q":"In 1931–32 US prices were falling fast and nominal interest rates were low by historical standards. What happened to the real cost of borrowing for a farmer or firm with debts fixed in dollars?","options":["It fell, because nominal interest rates were low","It rose, because falling prices increased real interest rates and the real value of debts","It stayed about the same, because nominal and real rates move together"],"answer":1,"explain":"Consumer prices fell 8.9% in 1931 and 10.3% in 1932. Because the real interest rate is roughly the nominal rate minus inflation, a low nominal rate still meant a high real rate. Debts fixed in dollars had to be repaid with dollars that bought more. Borrowers cut spending or defaulted, banks failed, and demand fell further: Irving Fisher’s debt-deflation mechanism."},"mechanism":["Crash and loss of wealth → households and firms cut spending on durables and investment → AD shifts left (a shift of the curve, not a movement along it)","Fall in investment → incomes fall → consumption falls → incomes fall again → the multiplier enlarges the initial fall in spending","Bank failures → depositors hoard cash and banks hoard reserves → money stock contracts → credit dries up → AD falls further","Falling prices with fixed nominal debts → real debt burdens and real interest rates rise → more defaults and bank failures (debt deflation)","Gold-standard rules → central banks raise rates or restrict credit to defend reserves → deflation passes from country to country","Tariffs and retaliation → exports fall → injections into the circular flow fall and world trade contracts","Sticky money wages and prices → output and employment, not only prices, absorb the fall in AD → a persistent deflationary gap","Leaving gold in 1933 → money stock grows and deflation expectations end → real interest rates fall → AD recovers from 1933"],"charts":[{"series":"sp500","from":"1928-01","to":"1933-12","title":"Share prices: the crash and the long slide","look":"The October 1929 fall was large, but the index kept falling until mid-1932. Most of the total loss came during the later banking crises, not in the crash itself.","marks":[{"at":"1929-10","label":"The crash"},{"at":"1931-09","label":"Britain leaves gold"},{"at":"1933-03","label":"Bank holiday"}]},{"series":"us-gdp-growth","from":"1930","to":"1941","title":"US real GDP growth through the decade","look":"Four years of contraction, sharpest in 1932, then rapid growth from 1934 interrupted by the 1938 relapse. Fast growth from a very low base can coexist with a large output gap.","marks":[{"at":"1932","label":"Deepest fall"},{"at":"1938","label":"1937–38 relapse"}]},{"series":"us-cpi-infl","from":"1925","to":"1941","title":"Four years of falling prices","look":"Consumer prices fell every year from 1930 to 1933, by as much as 10.3% in 1932, and rose once the dollar left gold. Deflation raised the real burden of debts.","marks":[{"at":"1933","label":"Dollar leaves gold"},{"at":"1938","label":"Relapse"}]}],"diagrams":[{"dg":"defgap","how":"Draw AD₁ meeting a Keynesian AS curve near full employment output. Shift AD to the left to AD₂ as consumption, investment and exports fall. Real output falls well below full employment output and the price level falls a little: a large deflationary gap."},{"dg":"multiplier","how":"Show an initial fall in investment spending, then successive smaller rounds of lost income and consumption. Label the total fall in national income as a multiple of the initial fall, and note that bank failures and deflation made later rounds larger."}],"policy":[{"who":"Federal Reserve","when":"1931-10","what":"Raised its discount rate sharply after Britain left gold, to protect the dollar’s gold parity. The move tightened credit while banks were failing and prices falling, and later economists widely criticise it.","status":"fact"},{"who":"Hoover administration and Congress","when":"1932","what":"Created the Reconstruction Finance Corporation to lend to banks, railways and other firms, but also passed the Revenue Act of 1932, raising taxes to reduce the deficit in the middle of the slump.","status":"fact"},{"who":"Roosevelt administration","when":"1933-03","what":"Declared a national bank holiday. The Emergency Banking Act let inspected banks reopen with official backing, and currency hoarded during the panic flowed back into the banking system.","status":"fact"},{"who":"Roosevelt administration","when":"1933-04","what":"Ended gold convertibility for private holders and let the dollar depreciate; the Gold Reserve Act (1934) raised the official gold price. Gold inflows then expanded the money stock and ended deflation.","status":"fact"},{"who":"Congress","when":"1933-06","what":"The Banking Act of 1933 (Glass–Steagall) created federal deposit insurance and separated commercial from investment banking. After insurance began in 1934, bank runs became rare.","status":"fact"},{"who":"Federal Reserve and Treasury","when":"1936","what":"The Fed doubled reserve requirements in steps during 1936–37 and the Treasury sterilised gold inflows, slowing money growth just as the budget deficit narrowed. A sharp recession followed in 1937–38.","status":"fact"}],"stakeholders":[{"who":"Unemployed workers","effect":"Lost income for years at a time, with little public relief before 1933. Long spells without work eroded skills and savings and left lasting damage to families."},{"who":"Farmers","effect":"Crop prices fell faster than costs and mortgage payments, which were fixed in dollars. Many lost their farms through foreclosure, and export markets shrank under foreign tariffs."},{"who":"Bank depositors","effect":"Before federal deposit insurance, depositors at failed banks could lose savings or wait years for partial repayment, which explains why fear spread so quickly between banks."},{"who":"Creditors and holders of cash","effect":"Those whose borrowers stayed solvent gained in real terms, because deflation raised the purchasing power of money and of fixed repayments."},{"who":"Trading partners","effect":"Exporters to the United States faced higher tariffs and collapsing demand, and countries dependent on American loans, such as Germany, lost their source of finance."}],"short":"In the short run the crash cut wealth and confidence, and spending on cars, houses and machinery fell sharply. Waves of bank failures in 1930, 1931 and early 1933 shrank the money stock and credit. Prices fell every year from 1930 to 1933, raising real debts. Real GDP fell 8.5% in 1930, 6.4% in 1931 and 12.9% in 1932. Unemployment rose to roughly a quarter of the labour force by 1933, and output stayed far below its 1929 level.","long":"The long-run legacy was institutional and intellectual. Deposit insurance, securities regulation, unemployment insurance and old-age pensions reshaped the US economy. Keynes’s General Theory made aggregate demand the centre of macroeconomics, and governments came to accept responsibility for employment. Monetarists later drew a different lesson: central banks must stop the money stock and the banking system collapsing. Both lessons shaped the response to 2008. The gold standard was discredited, and the post-war Bretton Woods system tried to combine stable exchange rates with national policy freedom.","transmission":"The Depression spread mainly through the gold standard, capital flows and trade. When US lending abroad dried up from 1928, borrowers such as Germany lost finance. Gold-standard countries losing reserves had to raise interest rates or deflate, transmitting the US contraction worldwide. Banking crises in Austria and Germany in 1931 fed back to London and New York. Tariffs, starting with Smoot–Hawley and followed by retaliation, cut world trade. Countries that left gold earlier, such as Britain in 1931, could ease policy and generally recovered sooner.","winners":[{"t":"Holders of cash and safe government bonds, whose purchasing power rose as prices fell.","status":"inference"},{"t":"Workers who kept their jobs at stable money wages, whose real wages rose as prices fell.","status":"inference"},{"t":"Creditors whose borrowers stayed solvent, repaid in dollars worth more than those they lent.","status":"inference"}],"losers":[{"t":"The unemployed, who reached roughly a quarter of the US labour force in 1933.","status":"fact"},{"t":"Farmers and indebted households facing falling incomes but fixed debt payments.","status":"fact"},{"t":"Shareholders: the S&P 500 monthly average fell from 31.3 in September 1929 to 4.77 in June 1932.","status":"fact"},{"t":"Depositors at the thousands of banks that failed before federal deposit insurance.","status":"fact"}],"unintended":[{"t":"Retaliation against the 1930 tariff hurt US farm exports, even though protecting farmers was one of the tariff’s aims.","status":"inference"},{"t":"The 1936–37 rise in reserve requirements, meant as a precaution against future inflation, coincided with a sharp relapse in 1937–38.","status":"interpretation"},{"t":"Deposit insurance ended most bank runs but, over the long run, weakened depositors’ incentive to monitor banks (moral hazard).","status":"inference"}],"interpretations":[{"view":"Monetarist (Friedman and Schwartz)","p":"The Depression was above all a contraction of money. The Fed allowed waves of bank failures to shrink the money stock by about a third between 1929 and 1933. A central bank willing to act as lender of last resort and supply reserves could have turned a severe recession into a far milder one.","status":"interpretation"},{"view":"Debt deflation and credit (Fisher; Bernanke)","p":"Falling prices raised real debt burdens, causing defaults and distress sales that pushed prices down further. Bernanke added that bank failures destroyed banks’ knowledge of their borrowers, so credit for households, farms and small firms dried up beyond what the fall in money alone would imply.","status":"interpretation"},{"view":"Gold standard (Eichengreen, Temin)","p":"The gold standard spread deflation across countries and stopped central banks from expanding. Countries recovered roughly in the order they left gold: Britain and the Scandinavian countries from 1931, the United States from 1933, and France and the remaining gold bloc only after 1935–36.","status":"interpretation"},{"view":"Why recovery was slow","p":"Keynesians argue New Deal deficits were too small to close the output gap. Others, such as Cole and Ohanian, argue that policies like the National Industrial Recovery Act raised wages and prices above market levels and slowed the return of jobs. The evidence remains contested.","status":"controversy"}],"explain":["The AD–AS model shows how a large leftward shift of AD, with sticky wages, produces falling output, rising unemployment and a falling price level together.","The Keynesian multiplier explains why a collapse in investment led to a much larger fall in national income.","The relation real rate ≈ nominal rate − inflation shows why low nominal interest rates were still tight money when prices were falling 9–10% a year."],"miss":["The basic AD–AS model treats banks lightly; it says little about bank runs, credit rationing and why the money stock collapsed.","Single-country models miss how the gold standard tied countries together and transmitted deflation and high interest rates between them.","Models of self-correcting markets expected falling wages and prices to restore full employment; deflation instead deepened the slump by raising real debts.","They miss expectations and regime change: the 1933 break with gold appears to have worked partly by changing what people expected about future prices."],"differently":[{"t":"The Fed could have acted as lender of last resort in 1930–31, supplying reserves to solvent banks and offsetting the fall in the money stock. Friedman and Schwartz argue this would have made the downturn far milder.","status":"interpretation"},{"t":"The United States could have left gold earlier, as Britain did in 1931, freeing monetary policy. Critics reply that devaluation in 1931 risked a run on the dollar and a loss of confidence in US finance.","status":"controversy"},{"t":"Avoiding the 1932 tax rises and the 1936–37 tightening, and keeping larger deficits until recovery was secure, might have shortened the slump. Economists still dispute by how much, since the multiplier in the 1930s is hard to estimate.","status":"interpretation"}],"whatif":{"q":"Suppose the Federal Reserve had stopped the money stock from falling in 1930–33. What would most likely have happened?","options":["The 1929 crash would not have occurred","A severe recession would probably still have followed, but it would have been shorter and shallower","Nothing would have changed, because monetary policy has no effect in a slump"],"best":1,"explain":"The crash came before the monetary collapse, so the first option cannot follow. Friedman and Schwartz argue stable money would have avoided most of the damage, and the credit and gold-standard views broadly agree that monetary and banking collapse deepened the slump. But the counterfactual cannot be tested directly: weak demand, heavy debts and the constraints of the gold standard would still have weighed on recovery."},"compare":[{"id":"gfc-2008","similar":"Both began with a fall in asset prices and turned into banking crises that threatened credit and the money supply, while falling demand spread quickly across countries.","different":"In 2008 central banks cut rates to near zero, lent heavily and expanded their balance sheets, and deposit insurance limited runs; in 1930–33 the Fed let banks fail and money contract.","dominant":"1929–33: a demand collapse deepened by monetary contraction and gold-standard deflation. 2008–09: a credit shock largely contained by aggressive monetary and fiscal responses."},{"id":"oil-1973","similar":"Both produced deep US recessions with rising unemployment and falling real output, both spread quickly to other countries, and both changed how economists think about macroeconomic policy.","different":"The Depression was a demand shock with falling prices; 1973–74 was a supply shock with rising prices, so stimulus suited to the 1930s risked adding to inflation in the 1970s.","dominant":"1930s: a leftward AD shift with deflation. 1973–74: a leftward SRAS shift from higher oil costs, producing cost-push inflation alongside falling output."}],"ib":{"subs":["3.1","3.2","3.3","3.5","3.6","4.2","4.5"],"kc":["Change","Interdependence","Intervention","Economic well-being","Equity"],"note":"Supports analysis of a leftward AD shift and a deflationary gap, evaluation of monetary versus fiscal responses, and supplies historical evidence for essay answers on demand-side policy and protectionism."},"cambridge":{"topics":["aggregate demand and aggregate supply","the multiplier","unemployment","deflation","monetary policy","fiscal policy","protectionism","exchange rate systems"],"note":"A historical case for linking falling aggregate demand, the multiplier and the choice between monetary and fiscal responses."},"university":{"fields":["economic history","monetary economics","macroeconomics","international finance"],"note":"A university course would add money-multiplier analysis of the fall in the money stock, Fisher’s debt-deflation model, Bernanke’s credit-channel argument and cross-country evidence on the timing of exit from gold."},"civil":{"themes":["financial stability","monetary policy","fiscal policy","external sector","global economic history"],"note":"In British India the collapse in agricultural prices in the early 1930s hit indebted cultivators hard; the episode also anchors debates on deposit insurance and the lender-of-last-resort role of a central bank."},"economists":["keynes","friedman"],"causal":["unemployment","growth","stimulus","tariff"],"concepts":["Aggregate demand","Deflation","Deflationary gap","Keynesian multiplier","Keynesian AS curve","Fixed exchange rate","Devaluation","Monetary policy","Fiscal policy","Central bank","Real interest rate","Cyclical unemployment","Recession","Protectionism","Tariff"],"cases":["MAC-017"],"policies":["Smoot–Hawley Tariff Act (1930)","Reconstruction Finance Corporation (1932)","Revenue Act of 1932","Emergency Banking Act (1933)","Banking Act of 1933 (Glass–Steagall) and federal deposit insurance","Gold Reserve Act (1934)","Social Security Act (1935)","Reserve requirement increases (1936–37)"],"questions":[{"q":"Explain, using an AD–AS diagram, why US real output and the price level both fell between 1930 and 1933.","kind":"explain"},{"q":"Analyse how bank failures could reduce aggregate demand even when the central bank’s interest rates were low.","kind":"analyse"},{"q":"Evaluate the view that the gold standard, rather than the stock market crash, was the main cause of the Great Depression.","kind":"evaluate"},{"q":"Using US nominal GDP for 1929 and 1933, calculate the percentage change and explain why it is larger than the fall in real output over the same years.","kind":"data"},{"q":"Compare the policy responses to the Great Depression and to the 2008 financial crisis. Which differences best explain the different depth of the two downturns?","kind":"compare"}],"retrieval":[{"q":"On what date did Britain leave the gold standard?","a":"21 September 1931."},{"q":"What did the Emergency Banking Act of March 1933 allow?","a":"Banks that inspectors judged sound could reopen after the national bank holiday, which restored depositors’ confidence."},{"q":"What is debt deflation?","a":"A process in which falling prices raise the real burden of debts, causing defaults and distress sales that push prices down further."},{"q":"By how much did US real GDP fall in 1932?","a":"By 12.9%, the largest annual fall of the decade."},{"q":"What happened in 1937–38?","a":"A sharp relapse: after the Fed doubled reserve requirements and fiscal policy tightened, real GDP fell 3.3% in 1938."}],"reflection":"If falling wages and prices are supposed to restore full employment, why did four years of deflation seem to make the slump worse?","reading":[{"t":"Milton Friedman and Anna J. Schwartz, A Monetary History of the United States, 1867–1960, 1963","note":"The classic monetarist account; its chapter on 1929–33 sets out the case against the Federal Reserve."},{"t":"Barry Eichengreen, Golden Fetters: The Gold Standard and the Great Depression, 1919–1939, 1992","note":"Explains how the gold standard spread and prolonged the slump across countries."},{"t":"Charles P. Kindleberger, The World in Depression, 1929–1939, 1973","note":"Argues the slump deepened because no country was willing and able to stabilise the world economy."},{"t":"John Kenneth Galbraith, The Great Crash, 1929, 1955","note":"A readable narrative of the speculative boom and the crash itself."}],"numbers":[{"value":"about a third","claim":"The US money stock fell by about a third between 1929 and 1933.","basis":"Friedman and Schwartz (1963), A Monetary History of the United States; widely cited."},{"value":"roughly a quarter","claim":"US unemployment peaked at roughly a quarter of the labour force in 1933.","basis":"Standard historical estimates (Lebergott, published in US Historical Statistics) put 1933 unemployment at about 25%."},{"value":"doubled","claim":"The Fed doubled member banks’ reserve requirements in three steps between August 1936 and May 1937.","basis":"Federal Reserve history; Friedman and Schwartz (1963)."},{"value":"9–10% a year","claim":"Rate of price decline in 1931–32.","basis":"Derived from catalogue series us-cpi-infl: −8.9% (1931), −10.3% (1932)."},{"value":"1925","claim":"Year Britain returned to gold at pre-war parity.","basis":"Widely documented (Churchill as Chancellor)."}]},{"id":"bretton-woods-1971","title":"The end of Bretton Woods","years":"1971–1973","start":"1971-05","end":"1973-03","region":"United States and the world","kind":"policy","standfirst":"For a quarter of a century after 1944, most major currencies were pegged to the US dollar, and the dollar was tied to gold. Between 1971 and 1973 that arrangement came apart, and the main currencies moved to floating exchange rates that still largely govern the world economy.","question":"Why could a system of fixed exchange rates anchored on a gold-convertible dollar not survive the strains of the late 1960s, and what changed when it ended?","before":{"p":"The Bretton Woods agreement of 1944 built an adjustable-peg system. Each member fixed its currency to the US dollar within narrow bands, and the United States undertook to convert dollars held by foreign monetary authorities into gold at $35 an ounce. A parity could be changed to correct a “fundamental disequilibrium”, with the IMF involved. Capital controls were common, which left governments some room to run their own policies. Trade grew quickly, and Western Europe and Japan rebuilt. Yet the system relied on a growing supply of dollars, and as foreign dollar holdings outgrew US gold reserves, confidence in the $35 promise weakened.","facts":[{"t":"Delegates from 44 Allied nations met at Bretton Woods, New Hampshire, in July 1944; the conference created the IMF and the International Bank for Reconstruction and Development.","status":"fact"},{"t":"The main Western European currencies became convertible for current-account transactions at the end of 1958, and only then did the system operate as designed.","status":"fact"},{"t":"By the early 1960s, dollars held outside the United States exceeded the US gold stock, so the gold promise could not have been met if all holders had asked at once.","status":"fact"},{"t":"In 1960 the economist Robert Triffin argued that the system needed US payments deficits to supply reserves, yet those same deficits would erode confidence in the dollar’s gold value.","status":"fact"},{"t":"US consumer-price inflation rose from 1.6% in 1965 to 5.8% in 1970, during heavy spending on the Vietnam War and domestic programmes.","status":"fact"}]},"trigger":{"p":"In spring 1971 the pressure became acute. Money moved out of dollars and into Deutsche Marks in expectation of a revaluation, and in May West Germany let its currency float. Over the summer, outflows continued and the risk grew that foreign official holders would ask for gold. On 15 August 1971 President Nixon announced that the United States would stop converting dollars into gold for foreign authorities, together with a temporary wage and price freeze and a 10% surcharge on many imports.","status":"fact"},"timeline":[{"d":"1944-07","t":"Bretton Woods conference sets the rules","detail":"Allied delegates agree a system of fixed but adjustable parities against the dollar, with the dollar convertible into gold for official holders, and create the IMF to lend to countries in payments difficulty.","status":"fact"},{"d":"1958-12","t":"European currencies become convertible","detail":"Major Western European currencies become freely usable for current-account transactions. The system now works as intended, but dollars and capital begin to move across borders more easily.","status":"fact"},{"d":"1961","t":"London Gold Pool formed","detail":"The United States and several European central banks pool gold to hold the London market price near $35 an ounce, a sign that the official price needed active defence.","status":"fact"},{"d":"1967-11","t":"Sterling devalued","detail":"After years of pressure, the United Kingdom devalues the pound from $2.80 to $2.40. Attention turns to the dollar as the next currency that markets might test.","status":"fact"},{"d":"1968-03","t":"Two-tier gold market created","detail":"The Gold Pool is wound up. Official transactions stay at $35 an ounce while the private market price is allowed to float, separating the official promise from the market price.","status":"fact"},{"d":"1971-05","t":"Deutsche Mark allowed to float","detail":"Faced with heavy inflows of dollars, West Germany stops buying dollars at the fixed rate and lets the Deutsche Mark float upwards. The Netherlands takes a similar step.","status":"fact"},{"d":"1971-08-15","t":"Nixon closes the gold window","detail":"The United States suspends gold convertibility for foreign official holders, announces a 90-day wage and price freeze and a temporary 10% import surcharge, in effect forcing other countries to negotiate a realignment.","status":"fact"},{"d":"1971-12","t":"Smithsonian Agreement realigns currencies","detail":"The Group of Ten agree new central rates in Washington. The official gold price rises to $38 an ounce, several currencies are revalued against the dollar, bands widen, and the surcharge is removed.","status":"fact"},{"d":"1972-06","t":"Sterling floats","detail":"After renewed outflows, the United Kingdom stops defending its Smithsonian rate and lets the pound float, an early sign that the new parities would not hold.","status":"fact"},{"d":"1973-02","t":"Second dollar devaluation","detail":"Under fresh speculative pressure the United States raises the official gold price to $42.22 an ounce. Markets remain unconvinced, and flows into Deutsche Marks and yen resume within weeks.","status":"fact"},{"d":"1973-03","t":"Generalised floating begins","detail":"Major countries stop defending dollar parities. Several European Community currencies float jointly against the dollar, while the yen, pound and others float independently. The fixed-rate era among major currencies ends.","status":"fact"},{"d":"1976-01","t":"Jamaica agreement legalises floating","detail":"IMF members agree to amend the Fund’s Articles so that countries may choose their own exchange-rate arrangements, and the official role of gold is reduced. The amendment took effect in 1978.","status":"fact"}],"actors":[{"who":"President Richard Nixon","role":"Announced the suspension of gold convertibility in August 1971, combining it with domestic wage and price controls and an import surcharge to strengthen the US bargaining position."},{"who":"John Connally, US Treasury Secretary","role":"Led the tough US negotiating stance in 1971, pressing surplus countries to revalue their currencies and share more of the burden of adjustment."},{"who":"Paul Volcker, Treasury Under Secretary for Monetary Affairs","role":"Senior official who helped design the August 1971 measures and negotiated the realignments; he later became Federal Reserve chairman in 1979."},{"who":"West German and Japanese authorities","role":"Ran large surpluses and accumulated dollars to hold their pegs, importing monetary expansion, and resisted revaluations until market pressure made them unavoidable."},{"who":"Group of Ten finance ministers and central bankers","role":"Negotiated the Smithsonian realignment of December 1971, attempting to rebuild a fixed-rate system on new parities with wider bands."},{"who":"International Monetary Fund","role":"Guardian of the par-value rules; after the system broke down it oversaw the rewriting of its own Articles to allow members to choose floating."}],"changed":"Exchange rates among the major currencies were no longer pegged but set largely in markets, with central banks intervening when they chose. The last formal link between money and gold disappeared, so the price level came to depend on central-bank policy rather than a metallic anchor. Countries gained freedom to set interest rates for domestic aims, while firms and investors faced more exchange-rate risk, and markets for hedging that risk grew. The dollar stayed the main reserve and invoicing currency, which many had not expected when the gold link ended.","predict":{"q":"Once the gold window closed and the dollar was eventually allowed to float, what would you expect to happen to the number of Deutsche Marks and yen needed to buy one dollar between 1971 and 1973?","options":["Both fell: the dollar depreciated","Both rose: the dollar appreciated","Little change, because new pegs held"],"answer":0,"explain":"At its old parities the dollar was overvalued, as persistent US payments deficits and the build-up of dollars abroad suggested. Removing the peg let the excess supply of dollars push its price down. Annual averages fell from 3.48 to 2.67 Deutsche Marks per dollar, and from 348.05 to 271.4 yen per dollar, between 1971 and 1973."},"mechanism":["Persistent US balance-of-payments deficits → dollars accumulate in the reserves of foreign central banks","Foreign dollar holdings grow faster than the US gold stock → doubts that the $35 gold price can be honoured → incentive to convert dollars before others do","Faster US inflation in the late 1960s at fixed nominal parities → US real exchange rate appreciates → US goods lose price competitiveness → trade balance weakens","Expected dollar devaluation → speculative capital flows into Deutsche Marks and yen → surplus central banks buy dollars to hold the peg → their money supply expands (imported inflation)","Cost of defending the peg rises for both deficit and surplus countries → gold convertibility suspended → realignment at the Smithsonian, then generalised floating","Peg removed → the dollar’s price moves to where existing demand and supply of dollars meet: a movement to market equilibrium, not a shift of either curve","Dollar depreciation → dearer imports for US buyers → added upward pressure on US prices, alongside expansionary policy, before the 1973 oil shock"],"charts":[{"series":"fx-germany","from":"1971","to":"1980","title":"Deutsche Marks per US dollar, 1971–1980","look":"The Deutsche Mark price of a dollar falls in steps: after August 1971, after the Smithsonian realignment, and again once floating began in March 1973. A falling line means a weaker dollar.","marks":[{"at":"1971-08","label":"Gold window closed"},{"at":"1971-12","label":"Smithsonian Agreement"},{"at":"1973-03","label":"Generalised floating"}]},{"series":"fx-japan","from":"1971","to":"1980","title":"Yen per US dollar, 1971–1980","look":"The yen had been fixed at 360 per dollar since 1949. Notice how quickly the rate fell after 1971, and that floating did not mean steady movement: the yen weakened again in 1974–76 after the oil shock.","marks":[{"at":"1971-08","label":"Gold window closed"},{"at":"1971-12","label":"Smithsonian Agreement"},{"at":"1973-03","label":"Generalised floating"}]},{"series":"us-cpi-infl","from":"1960","to":"1980","title":"US consumer-price inflation, 1960–1980","look":"Inflation was rising well before 1971. The price freeze and controls held it to 3.3% in 1972, but it reached 6.2% in 1973 and 11.1% in 1974 as controls eased and oil prices jumped.","marks":[{"at":"1971","label":"Gold window closed"},{"at":"1973","label":"Floating begins"}]}],"diagrams":[{"dg":"fx","how":"Draw the market for US dollars priced in Deutsche Marks. Set the official parity above the equilibrium, creating an excess supply of dollars that the Bundesbank had to buy. Then remove the peg: the price falls to equilibrium, a movement along both curves rather than a shift."},{"dg":"bop","how":"Sketch the US balance of payments around 1970: a weakening current account and capital outflows, matched by a rise in dollars held by foreign central banks. Explain why financing deficits this way depended on foreigners’ willingness to keep holding dollars."}],"policy":[{"who":"West German authorities","when":"1971-05","what":"Stopped buying dollars at the fixed rate and let the Deutsche Mark float after heavy inflows, because defending the peg was swelling the domestic money supply and adding to inflation pressure.","status":"fact"},{"who":"US government","when":"1971-08","what":"Suspended dollar–gold convertibility for foreign official holders, imposed a 90-day wage and price freeze and a temporary 10% surcharge on many imports, aiming to force a realignment and contain inflation.","status":"fact"},{"who":"Group of Ten","when":"1971-12","what":"Smithsonian Agreement: raised the official gold price from $35 to $38 an ounce, revalued several major currencies against the dollar and widened permitted bands to 2.25% either side of central rates; the US dropped its surcharge.","status":"fact"},{"who":"European Community members","when":"1972-04","what":"Created the “snake”, keeping fluctuations among their own currencies within narrower margins than the Smithsonian bands, an early step in the European monetary cooperation that later led to the euro.","status":"fact"},{"who":"US government","when":"1973-02","what":"Devalued the dollar a second time, raising the official gold price to $42.22 an ounce; within weeks, renewed outflows led the major countries to stop defending dollar parities altogether.","status":"fact"},{"who":"IMF members","when":"1976-01","what":"Agreed at Kingston, Jamaica, to amend the IMF’s Articles so that members could choose their own exchange-rate arrangements, giving legal recognition to floating and reducing gold’s official role.","status":"fact"}],"stakeholders":[{"who":"US exporters and import-competing firms","effect":"Gained price competitiveness as the dollar depreciated against the Deutsche Mark and yen, and enjoyed brief protection from the 1971 import surcharge."},{"who":"German and Japanese exporters","effect":"Lost some price advantage as their currencies appreciated; Japanese firms had planned for decades around a rate of 360 yen per dollar."},{"who":"Central banks in surplus countries","effect":"Regained control of their money supply once they no longer had to buy dollars, but their existing dollar reserves fell in value measured in their own currencies."},{"who":"US households","effect":"Faced dearer imported goods as the dollar fell; the price freeze held measured inflation down for a time before it rose again in 1973–74."},{"who":"Firms and investors trading across borders","effect":"Faced more day-to-day exchange-rate risk, raising demand for forward contracts and other hedging tools, and making long-term contracts in foreign currencies harder to price."}],"short":"In the short run, the August 1971 measures shocked other governments and forced a negotiated realignment within four months. The dollar fell against the Deutsche Mark and yen, the US import surcharge disappeared once the Smithsonian rates were agreed, and the wage and price freeze held US inflation to 3.3% in 1972. But the new parities lacked credibility. Sterling floated within six months, a second dollar devaluation came in February 1973, and by March the major currencies were floating against the dollar.","long":"In the long run, floating exchange rates became the norm among the major economies, with central banks setting interest rates for domestic goals. Without a gold anchor, controlling inflation depended on the credibility of monetary policy, which helps explain the later spread of independent central banks and inflation targets. Exchange rates turned out to be more volatile than many supporters of floating had expected. The dollar kept its dominant international role, and Europe pursued its own route to currency stability that ended in monetary union.","transmission":"Because the dollar sat at the centre of the system, its troubles reached every country that pegged to it. Surplus countries had been importing US monetary expansion as they bought dollars to hold their pegs, and the rapid growth of official reserves in the early 1970s added to global liquidity. After 1973, changes in US interest rates and inflation passed abroad mainly through exchange rates and capital flows rather than official reserve purchases. Many smaller economies continued to peg to the dollar or another currency, so floating was general among major currencies only.","winners":[{"t":"US export and import-competing industries, which gained competitiveness from a weaker dollar.","status":"inference"},{"t":"Countries such as West Germany that wanted lower inflation than the United States, since floating let them stop importing US monetary expansion.","status":"inference"},{"t":"Banks and dealers in foreign exchange, as currency trading and hedging grew once rates floated.","status":"inference"}],"losers":[{"t":"Foreign central banks holding large dollar reserves, whose holdings lost value in terms of their own appreciating currencies.","status":"inference"},{"t":"Exporters in Japan and West Germany, whose prices rose in dollar terms after revaluation.","status":"inference"},{"t":"Firms relying on predictable exchange rates for long-term trade contracts, which now faced greater uncertainty.","status":"inference"}],"unintended":[{"t":"Removing the gold anchor took away an external brake on inflation; many economists link this to the high inflation of the 1970s, though oil shocks and domestic policy choices also mattered.","status":"controversy"},{"t":"Ending gold convertibility did not reduce the world’s reliance on the dollar; the dollar remained the main reserve currency under floating.","status":"fact"},{"t":"The wage and price controls, extended in later phases, distorted relative prices, and inflation re-emerged strongly once they were relaxed.","status":"interpretation"}],"interpretations":[{"view":"The Triffin dilemma","p":"Robert Triffin argued the system contained a built-in contradiction. A growing world economy needed more reserves, which mainly came from US payments deficits. But the more dollars piled up abroad relative to US gold, the less credible convertibility became. On this view, collapse was a structural problem rather than the fault of any one government.","status":"interpretation"},{"view":"US policy and the monetarist reading","p":"Milton Friedman and others had argued since the 1950s for floating rates. Monetarists emphasised that the United States ran monetary and fiscal policies too loose for its role as anchor, exporting inflation to partners. Surplus countries then faced a choice between importing that inflation or breaking their pegs.","status":"interpretation"},{"view":"The trilemma view","p":"Historians such as Barry Eichengreen stress the “impossible trinity”: a country cannot keep a fixed exchange rate, free capital movement and an independent monetary policy all at once. As capital controls became less effective in the 1960s, governments that prized domestic policy autonomy found the pegs harder to hold.","status":"interpretation"},{"view":"Asymmetric adjustment and power","p":"One view blames surplus countries for resisting revaluation; another blames the United States for acting unilaterally and treating the dollar’s value with neglect. How far the burden of adjustment should have fallen on deficit or surplus countries remains disputed, and the same argument recurs in later episodes.","status":"controversy"}],"explain":["The foreign exchange market model shows why an overvalued peg creates an excess supply of the currency that must be absorbed by reserve sales, or ended by devaluation.","Purchasing power parity suggests that persistently higher US inflation should lead to a weaker dollar over time, which is what happened once the peg was removed.","Balance of payments accounting shows how US deficits were financed by foreign official holdings of dollars, building claims on limited gold.","The impossible trinity explains why rising capital mobility made fixed rates harder to combine with independent national monetary policies."],"miss":["Simple models give little guide to timing: the system survived years of strain, then broke within weeks once expectations of devaluation became self-reinforcing.","They underplay politics and bargaining; the August measures were partly a negotiating tactic to force other countries to revalue.","Many advocates of floating expected smooth, gradual adjustment; in practice exchange rates turned out volatile and at times overshot their longer-run values.","They do not predict the dollar’s continued dominance, which rests on network effects, deep financial markets and habit rather than gold."],"differently":[{"t":"Earlier and more frequent parity changes, especially larger revaluations by West Germany and Japan in the 1960s, might have reduced the build-up of imbalances and the scale of speculative pressure that eventually broke the system.","status":"interpretation"},{"t":"Tighter US fiscal and monetary policy in the late 1960s could have slowed inflation and protected the dollar’s parity, though at the cost of slower growth and higher unemployment, which policymakers judged politically unacceptable.","status":"interpretation"},{"t":"A larger role for an international reserve asset, as in Keynes’s wartime proposal for an International Clearing Union (published in 1943) or the Special Drawing Rights created in 1969, might have eased reliance on the dollar. Whether this was politically achievable is disputed.","status":"controversy"}],"whatif":{"q":"Suppose that in 1971 the United States had raised interest rates sharply and cut spending to defend the $35 gold price instead of closing the gold window. What is the most likely result?","options":["The peg might have lasted longer, at the cost of a US recession and higher unemployment","The system would have become permanently secure","US inflation would have risen faster"],"best":0,"explain":"Tighter policy would have raised the return on dollar assets and slowed US inflation, reducing the incentive to convert. But it would also have reduced aggregate demand when unemployment was already 5.9% in 1971. It would not have solved the Triffin problem of reserve growth, so many historians doubt it could have saved the system for long. The answer is a judgement, not a certainty."},"compare":[{"id":"plaza-1985","similar":"Both episodes involved governments acting to change the value of an overvalued dollar and negotiating over who should bear the burden of adjustment between the United States, Germany and Japan.","different":"In 1985 currencies were already floating, and the change came through coordinated intervention and policy signals; in 1971 a formal peg and gold promise were abandoned.","dominant":"In 1971, a loss of confidence in a fixed parity dominated; in 1985, coordinated expectations management in a floating market dominated."},{"id":"asia-1997","similar":"Both show a currency peg breaking once markets doubted that the authorities could or would defend it, with speculative capital flows speeding the collapse and forcing a sudden change of regime.","different":"In 1997 the countries breaking pegs were emerging economies with foreign-currency debts; in 1971 the anchor country itself abandoned convertibility, and its debts were in its own currency.","dominant":"In 1971, the reserve-currency country’s policy choices dominated; in 1997, sudden capital flight and balance-sheet damage from foreign-currency debt dominated."},{"id":"stagflation-1970s","similar":"The end of the gold anchor and the inflation of the 1970s are closely linked in time, and both raised questions about what disciplines monetary policy.","different":"Bretton Woods ended through an exchange-rate and reserve problem among governments; stagflation combined supply shocks from oil with entrenched inflation expectations inside each economy, raising unemployment and inflation together.","dominant":"In 1971, external-balance and confidence problems in the anchor currency dominated; in the stagflation years, supply shocks interacting with wage and price expectations dominated."}],"ib":{"subs":["4.5","4.6","3.3","3.5"],"kc":["Change","Interdependence","Intervention"],"note":"The event gives a real setting for analysing fixed versus floating exchange rates with the foreign exchange market diagram, and for evaluating the trade-off between exchange-rate stability and domestic policy freedom in Paper 1 or Paper 2 responses."},"cambridge":{"topics":["exchange rate systems","balance of payments","international monetary system","inflation"],"note":"Useful for comparing fixed, managed and floating exchange rates and explaining how payments imbalances are financed."},"university":{"fields":["international finance","economic history","open-economy macroeconomics"],"note":"A university course would formalise the Triffin dilemma and the impossible trinity, and study speculative attacks on pegs and the “n−1” problem of who sets monetary policy in a fixed-rate system."},"civil":{"themes":["external sector","exchange rate management","monetary policy","international institutions"],"note":"India moved from pegs towards a market-determined rupee only after 1991–93; the Bretton Woods story helps explain why any peg needs adequate reserves and credible domestic policy."},"economists":["keynes","friedman"],"causal":["currency","inflation"],"concepts":["Fixed exchange rate","Floating exchange rate","Devaluation","Revaluation","Exchange rate","Balance of payments","Current account","Managed exchange rate","Central bank","Inflation"],"cases":["GLO-051","GLO-016","GLO-026"],"policies":["Suspension of gold convertibility","Wage and price controls","Import surcharge","Currency revaluation","Devaluation","Move to floating exchange rates"],"questions":[{"q":"Explain, using a foreign exchange market diagram, why West Germany had to buy dollars to maintain its peg in the late 1960s.","kind":"explain"},{"q":"Analyse how rising US inflation at fixed nominal parities affected the US current account.","kind":"analyse"},{"q":"Using the chart of Deutsche Marks per dollar, describe how the exchange rate changed between 1971 and 1973 and calculate the percentage change in the annual average.","kind":"data"},{"q":"Evaluate the view that the collapse of Bretton Woods was caused mainly by US macroeconomic policy rather than by flaws in the system’s design.","kind":"evaluate"},{"q":"Compare the breakdown of the dollar’s peg to gold in 1971 with the collapse of the Thai baht’s peg in 1997.","kind":"compare"}],"retrieval":[{"q":"At what price did the United States convert dollars into gold for foreign official holders under Bretton Woods?","a":"$35 an ounce."},{"q":"What did President Nixon announce on 15 August 1971?","a":"The suspension of dollar–gold convertibility for foreign official holders, a 90-day wage and price freeze, and a temporary 10% import surcharge."},{"q":"What was the Smithsonian Agreement?","a":"A December 1971 realignment by the Group of Ten that devalued the dollar against gold to $38 an ounce, revalued other currencies and widened bands to 2.25%."},{"q":"What is the Triffin dilemma?","a":"The conflict between the world’s need for more dollar reserves, supplied by US deficits, and the loss of confidence in dollar–gold convertibility that those deficits caused."},{"q":"When did the major currencies begin generalised floating against the dollar?","a":"March 1973."}],"reflection":"If you were a finance minister today, would you give up some control over interest rates in exchange for a stable exchange rate? What would your answer depend on?","reading":[{"t":"Barry Eichengreen, Globalizing Capital: A History of the International Monetary System, 1996","note":"A clear account of the gold standard, Bretton Woods and floating, organised around the trade-off between pegs, capital mobility and policy autonomy."},{"t":"Robert Triffin, Gold and the Dollar Crisis, 1960","note":"The original statement of the dilemma that bears his name, written a decade before the collapse."},{"t":"Paul Volcker and Toyoo Gyohten, Changing Fortunes, 1992","note":"An American and a Japanese official describe the end of Bretton Woods and later currency diplomacy from the inside."},{"t":"Barry Eichengreen, Exorbitant Privilege, 2011","note":"Explains why the dollar kept its international role after the gold link ended."}],"numbers":[{"value":"$35 an ounce","claim":"Official dollar price of gold under Bretton Woods","basis":"Bretton Woods par value of the dollar; widely documented"},{"value":"44","claim":"Number of Allied nations at the 1944 conference","basis":"Conference records; widely documented"},{"value":"$2.80 to $2.40","claim":"Sterling devaluation of November 1967","basis":"Widely documented official parity change"},{"value":"90 days; 10%","claim":"Length of the 1971 wage and price freeze; size of the import surcharge","basis":"Nixon’s announcement of 15 August 1971"},{"value":"$38 an ounce; 2.25%","claim":"Smithsonian official gold price and widened band","basis":"Smithsonian Agreement, December 1971"},{"value":"$42.22 an ounce","claim":"Official gold price after the February 1973 devaluation","basis":"US devaluation of February 1973; widely documented"},{"value":"360 yen per dollar","claim":"Yen parity from 1949 to 1971","basis":"Widely documented fixed rate"}]},{"id":"stagflation-1970s","title":"Stagflation and the Volcker disinflation","years":"1971–1983","start":"1971-08","end":"1983","region":"United States (with global effects)","kind":"shock","standfirst":"For a decade the United States suffered rising prices and rising unemployment at the same time, a combination many policymakers of the 1960s had treated as unlikely. Ending it required a central bank willing to accept a deep recession, and the episode reshaped how economists think about expectations and credibility.","question":"Why did inflation and unemployment rise together in the 1970s, and what did it cost to bring inflation back down?","before":{"p":"In the late 1960s the US economy ran close to full capacity. Spending on the Vietnam War and on new social programmes added to aggregate demand, and many policymakers read the Phillips curve as a stable menu: a little more inflation could buy a little less unemployment. US consumer-price inflation rose from 1.6% in 1965 to 5.5% in 1969, while unemployment fell to 3.5% in 1969. Under the Bretton Woods system the dollar was tied to gold, so US monetary conditions spread to other countries. A few economists warned that the apparent trade-off would not last once people came to expect higher inflation.","facts":[{"t":"US CPI inflation was 1.6% in 1965 and 5.5% in 1969; unemployment averaged 3.5% in 1969 (BLS data).","status":"fact"},{"t":"In his 1967 presidential address to the American Economic Association, published in 1968, Milton Friedman argued that there was no lasting trade-off between inflation and unemployment; Edmund Phelps made a similar argument.","status":"fact"},{"t":"Arthur Burns became chair of the Federal Reserve in 1970.","status":"fact"},{"t":"On 15 August 1971 President Nixon suspended the dollar’s convertibility into gold and imposed a 90-day freeze on wages and prices.","status":"fact"}]},"trigger":{"p":"There was no single trigger. Inflation was already elevated when the first oil shock arrived in late 1973: Arab members of OPEC imposed an embargo and oil prices roughly quadrupled within months. A second shock followed the Iranian revolution of 1979. A widely held reading is that these supply shocks landed on an economy where demand had been allowed to run hot and inflation expectations were drifting up, so each shock left inflation higher than before.","status":"interpretation"},"timeline":[{"d":"1971-08-15","t":"Gold window closed; wage-price freeze","detail":"Nixon suspends dollar–gold convertibility and freezes wages and prices for 90 days. Controls continue in phases until 1974; measured inflation falls for a while, then rebounds once controls loosen.","status":"fact"},{"d":"1973-10","t":"Oil embargo and price shock","detail":"Arab OPEC members cut supplies and impose an embargo on the United States during the Yom Kippur War. Oil prices roughly quadruple, raising costs for firms and households across the economy.","status":"fact"},{"d":"1974","t":"Double-digit inflation and recession","detail":"US inflation reaches 11.1% for the year while real GDP falls by 0.5%. Rising prices and falling output together give the word ‘stagflation’ its everyday meaning.","status":"fact"},{"d":"1974-10","t":"‘Whip Inflation Now’ campaign","detail":"President Ford launches a voluntary anti-inflation campaign urging households and firms to restrain spending and price rises. It relies on persuasion rather than on tighter money and has little measurable effect.","status":"fact"},{"d":"1975","t":"Unemployment peaks for the decade","detail":"Annual unemployment averages 8.5%, the highest since the Second World War at that point. The Fed eases, inflation falls to 5.7% in 1976 but does not return to 1960s levels.","status":"fact"},{"d":"1979","t":"Second oil shock","detail":"The Iranian revolution disrupts oil supply and prices more than double over 1979–80. US inflation rises to 11.3% in 1979, and expectations of continuing high inflation become entrenched.","status":"fact"},{"d":"1979-08","t":"Paul Volcker becomes Fed chair","detail":"President Carter appoints Paul Volcker, previously president of the Federal Reserve Bank of New York, to chair the Federal Reserve after G. William Miller moves to the Treasury.","status":"fact"},{"d":"1979-10-06","t":"Fed changes its operating procedure","detail":"The Fed announces it will target the quantity of bank reserves rather than the short-term interest rate, letting interest rates rise as far as needed to slow money growth.","status":"fact"},{"d":"1980-03","t":"Credit controls imposed, then lifted","detail":"The Carter administration invokes credit controls. Spending drops sharply, a short recession follows and the controls are removed within months; interest rates fall and then climb again.","status":"fact"},{"d":"1981-07","t":"Deep recession begins","detail":"With the federal funds rate close to 20% earlier in 1981, a second recession begins. Housing, manufacturing and farming, all sensitive to interest rates, are hit hardest.","status":"fact"},{"d":"1982","t":"Unemployment peaks; Fed eases","detail":"Annual unemployment averages 9.7% and the monthly rate reaches 10.8% late in the year. After Mexico’s debt crisis in August, the Fed relaxes policy in the second half of 1982.","status":"fact"},{"d":"1983","t":"Inflation down to 3.2%","detail":"Inflation falls to 3.2% while real GDP grows by 4.6%. President Reagan reappoints Volcker, and the recovery strengthens into 1984.","status":"fact"}],"actors":[{"who":"Federal Reserve under Arthur Burns (1970–78)","role":"Set monetary policy through two oil shocks; critics argue it eased too readily when unemployment rose and treated inflation as caused mainly by forces outside its control."},{"who":"Federal Reserve under Paul Volcker (1979–87)","role":"Shifted to controlling bank reserves in October 1979 and accepted very high interest rates and a deep recession to bring inflation down."},{"who":"OPEC and Gulf oil producers","role":"Raised oil prices sharply in 1973–74; supply disruption after the Iranian revolution produced a second rise in 1979–80, transferring income from oil importers to exporters."},{"who":"US presidents Nixon, Ford, Carter and Reagan","role":"Tried wage-price controls, voluntary restraint and credit controls; Carter appointed Volcker and Reagan reappointed him, giving political cover to tight money."},{"who":"Workers, unions and firms","role":"Built expected inflation into wage contracts and prices, often through cost-of-living clauses, which made inflation more persistent once it had risen."}],"changed":"The 1970s broke the belief that policymakers could choose a permanent point on a Phillips curve. Inflation and unemployment rose together, real wages stalled, and savers lost as interest rates trailed inflation. The Volcker disinflation then showed that a determined central bank could bring inflation down, but at the cost of the deepest recession since the 1930s. Afterwards, central banks increasingly treated low and stable inflation as their main task, and the role of expectations and credibility moved to the centre of macroeconomics.","predict":{"q":"Oil prices suddenly quadruple in an economy where inflation is already rising. Before looking at the mechanism, what would you expect to happen to output and the price level in the short run?","options":["The price level rises and real output falls","The price level rises and real output rises","The price level falls and real output falls"],"answer":0,"explain":"An oil price rise raises production costs for most firms, so short-run aggregate supply shifts to the left. With aggregate demand unchanged, the new equilibrium has a higher price level and lower real output. That combination of rising prices and falling output is stagflation; a demand shock would move both in the same direction instead."},"mechanism":["Oil price rise → firms’ costs of production rise → SRAS shifts left → price level rises and real output falls (cost-push inflation)","Inflation persists → workers and firms expect it to continue → higher wage claims and price setting → SRAS shifts left again, a wage–price spiral","Higher expected inflation → short-run Phillips curve shifts upwards → any given unemployment rate now comes with higher inflation","Policy eases when unemployment rises → AD shifts right → inflation is accommodated rather than squeezed out of the system","From October 1979 the Fed restricts reserve growth → interest rates rise sharply → borrowing, investment and consumption fall → AD shifts left → output falls and unemployment rises (movement along the short-run Phillips curve)","Tight policy is sustained through the 1981–82 recession → people come to believe the Fed will not reverse → expected inflation falls → short-run Phillips curve shifts down","High US real interest rates → capital flows into dollar assets → demand for dollars rises → the dollar appreciates in the early 1980s"],"charts":[{"series":"us-cpi-infl","from":"1965","to":"1990","title":"US consumer-price inflation, 1965–1990","look":"Two peaks, after each oil shock, sitting on a rising floor through the 1970s. Then a steep fall from 13.5% in 1980 to 3.2% in 1983 after the Fed tightened.","marks":[{"at":"1973-10","label":"Oil embargo"},{"at":"1979-08","label":"Volcker takes office"}]},{"series":"us-unemp","from":"1965","to":"1990","title":"US unemployment rate, 1965–1990","look":"Unemployment rises in both oil-shock recessions and peaks at 9.7% in 1982. Compare its timing with the inflation chart: the cost of disinflation shows up here.","marks":[{"at":"1975","label":"First peak"},{"at":"1982","label":"Disinflation recession"}]},{"series":"us10y","from":"1965","to":"1990","title":"US 10-year Treasury yield, 1965–1990","look":"Long-term yields rise with expected inflation, peak at 13.91% in 1981, and fall only slowly afterwards, suggesting markets took years to trust that inflation would stay low.","marks":[{"at":"1979-10","label":"New Fed procedure"}]}],"diagrams":[{"dg":"costpush","how":"Start from AD–AS equilibrium. Shift SRAS left to show the oil shock: the price level rises and real GDP falls below full-employment output. Then show a second leftward shift as wage claims catch up, and note that easing policy would shift AD right and raise prices further."},{"dg":"phillips","how":"Draw a vertical long-run Phillips curve at the natural rate. Show SRPC shifting up as expected inflation rises in the 1970s. Show 1980–82 as a movement down along a high SRPC to higher unemployment, then SRPC shifting down as expectations fall."}],"policy":[{"who":"Nixon administration","when":"1971-08","what":"Imposed a wage and price freeze, followed by phased controls until 1974. Controls held measured inflation down briefly but caused shortages in some markets, and prices jumped once they were relaxed.","status":"fact"},{"who":"Congress","when":"1978","what":"Passed the Full Employment and Balanced Growth Act (Humphrey–Hawkins), setting goals for both employment and price stability and requiring the Fed to report regularly to Congress on monetary policy.","status":"fact"},{"who":"Federal Reserve (Volcker)","when":"1979-10","what":"Switched to targeting non-borrowed bank reserves so that money growth, not the interest rate, became the operating focus. Short-term interest rates became much higher and more volatile.","status":"fact"},{"who":"Carter administration and Federal Reserve","when":"1980-03","what":"Introduced credit controls to restrain consumer borrowing. Spending fell abruptly and the economy contracted; the controls were withdrawn within months and are widely seen as a misstep.","status":"fact"},{"who":"Reagan administration and Congress","when":"1981-08","what":"Enacted the Economic Recovery Tax Act, cutting income tax rates. With higher defence spending, this widened budget deficits while monetary policy stayed tight, pushing up real interest rates.","status":"fact"},{"who":"Federal Reserve (Volcker)","when":"1982","what":"Eased policy in the second half of 1982 as the recession deepened and the Latin American debt crisis broke, and gave less weight to narrow money targets from late 1982.","status":"fact"}],"stakeholders":[{"who":"Savers and holders of fixed-income assets","effect":"Lost in real terms during the 1970s, as interest rates on many deposits and bonds stayed below inflation; gained after 1982 when inflation fell faster than yields."},{"who":"Households with fixed-rate mortgages","effect":"Gained during the 1970s, because inflation reduced the real value of their debt while repayments stayed fixed in money terms."},{"who":"Manufacturing and construction workers","effect":"Bore much of the cost of disinflation: interest-sensitive industries cut output and jobs sharply in 1981–82, and some job losses proved long-lasting."},{"who":"Farmers","effect":"Borrowed heavily against rising land values in the 1970s, then faced high interest rates and falling land prices in the early 1980s, leading to widespread farm debt problems."},{"who":"Developing-country borrowers","effect":"Had borrowed in dollars at floating rates; the rise in US interest rates and the strong dollar raised debt-service costs and contributed to the 1982 debt crisis."}],"short":"In the short run each oil shock raised costs and pushed the US economy towards higher inflation and lower output at the same time. Policy responses swung between stimulus when unemployment rose and restraint when inflation rose, which tended to keep inflation high. The Volcker tightening from 1979 then produced two recessions in quick succession, with unemployment averaging 9.7% in 1982, before inflation fell to 3.2% in 1983.","long":"Over the longer run the episode changed monetary policy. Central banks came to treat inflation expectations as something they must anchor, and many later moved towards greater independence and explicit inflation targets. US inflation stayed far lower in the 1980s and 1990s than in the 1970s. Long-term interest rates, however, fell only gradually, suggesting credibility took years to rebuild. Some of the industrial job losses of the early 1980s were not reversed in the same regions.","transmission":"Oil shocks hit all oil-importing economies, so stagflation was international: inflation was 24.2% in the United Kingdom in 1975 and 23.2% in Japan in 1974. The Volcker tightening then spread through financial markets. Higher US interest rates attracted capital, strengthening the dollar, and raised the cost of dollar debts. Several Latin American governments that had borrowed at floating rates found repayments unaffordable, and Mexico’s difficulties in August 1982 opened a regional debt crisis.","winners":[{"t":"Oil-exporting countries received a large transfer of income from oil importers after 1973 and again after 1979.","status":"fact"},{"t":"Borrowers with fixed-rate debt in the 1970s saw inflation erode the real burden of what they owed.","status":"inference"},{"t":"Investors who bought long-term bonds at the high yields of 1980–82 gained as inflation and yields later fell.","status":"inference"}],"losers":[{"t":"Savers whose deposit rates were capped by regulation earned negative real returns for much of the 1970s.","status":"fact"},{"t":"Workers in interest-sensitive industries lost jobs in large numbers during the 1981–82 recession.","status":"fact"},{"t":"Latin American governments with floating-rate dollar debts faced sharply higher repayments, contributing to the 1982 debt crisis.","status":"fact"}],"unintended":[{"t":"Interest-rate ceilings on deposits, combined with high inflation, pushed savers towards money market funds and weakened the savings and loan institutions that held long fixed-rate mortgages.","status":"fact"},{"t":"The high real interest rates of the early 1980s strengthened the dollar, hurting US exporters and building the pressure that led to the Plaza Accord of 1985.","status":"inference"},{"t":"Wage-price controls in the early 1970s caused shortages in some markets and may have delayed rather than reduced inflation.","status":"interpretation"}],"interpretations":[{"view":"Keynesian reading","p":"Stagflation reflected adverse supply shocks, chiefly oil and food prices, arriving in an economy where demand had already been allowed to run hot. On this view the shocks explain much of the timing of the inflation peaks, and the disinflation succeeded partly because those supply pressures eased after 1981.","status":"interpretation"},{"view":"Monetarist reading (Friedman)","p":"Persistent inflation was a monetary phenomenon: the Fed allowed money growth to stay too high for too long. Oil shocks could raise the price level once, but without monetary accommodation they would not have produced a decade of high inflation.","status":"interpretation"},{"view":"Expectations and credibility (Sargent and others)","p":"The cost of disinflation depends on whether people believe policy has changed. Some argue the Volcker Fed lowered inflation partly by changing expectations, though the depth of the 1981–82 recession suggests credibility was earned slowly rather than granted at once.","status":"controversy"},{"view":"Political-economy reading","p":"Under Burns, the Fed was exposed to political pressure, including from President Nixon before the 1972 election, and to a belief that inflation was largely non-monetary. How far political pressure, rather than mistaken economic analysis, explains the easy policy of the early 1970s is still debated by historians of the Fed.","status":"controversy"}],"explain":["The AD–AS model shows how a leftward shift of SRAS produces rising prices and falling output together, which matches the oil-shock years.","The expectations-augmented Phillips curve explains why higher inflation stopped buying lower unemployment once expectations adjusted.","Standard monetary transmission explains how very high interest rates reduced spending and pulled inflation down in 1981–83."],"miss":["Simple models treat expectations as adjusting smoothly; in practice credibility was rebuilt slowly, and long-term interest rates stayed high for years.","They usually ignore measurement problems: policymakers in the 1970s worked with estimates of spare capacity that later proved too optimistic.","They say little about who bears the cost of disinflation; job losses were concentrated in particular industries and regions."],"differently":[{"t":"Some economists argue that steadier tightening in the mid-1970s, before expectations became entrenched, could have lowered inflation at a smaller cost in lost output than the abrupt tightening of 1979–82.","status":"interpretation"},{"t":"Others argue that the Fed should have relied less on its real-time estimates of spare capacity, which later proved too optimistic, and responded more strongly and consistently to inflation itself.","status":"interpretation"},{"t":"Whether a more gradual disinflation after 1979 would have cost less is disputed: gradualism might have reduced the recession’s depth, or it might have failed to convince markets at all.","status":"controversy"}],"whatif":{"q":"Suppose the Fed had not tightened sharply after 1979 and had kept interest rates close to their late-1970s levels. What is the most likely outcome?","options":["Inflation would have stayed high or risen further, with expectations becoming harder to reverse","Inflation would have fallen just as quickly once oil prices stopped rising","Unemployment would have fallen permanently below the natural rate"],"best":0,"explain":"With expectations already high, easy policy would most likely have accommodated further price rises. Lower oil prices after 1981 would have helped, so inflation might have eased somewhat without tightening. But the natural-rate view suggests unemployment could not be held permanently below its natural level by tolerating inflation. Nobody can be sure how large the difference would have been."},"compare":[{"id":"oil-1973","similar":"Both involve a sharp rise in oil prices that shifted short-run aggregate supply to the left, raising prices and cutting output in the United States and other oil-importing economies.","different":"The oil shock is a single supply event; the stagflation story covers a whole decade, including policy choices, changing expectations and the costly disinflation that followed.","dominant":"In oil-1973 the supply shock dominates. In the 1970s stagflation, accommodation and rising inflation expectations dominate after the initial shocks."},{"id":"plaza-1985","similar":"Both are US-centred episodes in which Federal Reserve policy and US interest rates shaped the value of the dollar and, through it, the economies of major trading partners.","different":"Stagflation is mainly about inflation and unemployment inside the United States. The Plaza Accord concerns an over-strong dollar, a large trade deficit and international policy coordination.","dominant":"Monetary tightening and the slow fall in inflation expectations dominate the disinflation. Exchange-rate expectations, interest-rate differentials and coordinated intervention dominate the Plaza episode."},{"id":"covid-2020","similar":"Both saw US inflation rise well above what the Fed wanted after supply disruptions and strong demand, followed by sharp Federal Reserve interest-rate increases to bring it down.","different":"After 2020 inflation peaked at 8.0% in 2022 and fell back without a deep recession, whereas the early 1980s disinflation came with unemployment averaging 9.7%.","dominant":"In the 1970s, entrenched inflation expectations dominated. After 2020, supply bottlenecks and a strong demand rebound dominated, while longer-term expectations stayed less disturbed."}],"ib":{"subs":["3.2","3.3","3.5"],"kc":["Change","Intervention","Economic well-being","Choice"],"note":"The episode supports AD–AS analysis of supply shocks and evaluation of monetary policy; the short-run and long-run Phillips curve is HL only (guide PDF p. 44), so HL students can use the 1970s to analyse shifting expectations."},"cambridge":{"topics":["inflation","unemployment","aggregate demand and aggregate supply","monetary policy","the Phillips curve"],"note":"Useful for showing cost-push inflation, the conflict between macroeconomic objectives and the costs of reducing inflation."},"university":{"fields":["macroeconomics","monetary economics","economic history"],"note":"A university course would add the expectations-augmented Phillips curve, time inconsistency and credibility in policy, and the debate about policy rules versus discretion."},"civil":{"themes":["inflation management","monetary policy","oil-price shocks","central bank independence"],"note":"India also faced very high inflation after the first oil shock (28.6% in 1974), and later debates on anchoring expectations fed into the RBI’s adoption of flexible inflation targeting in 2016."},"economists":["friedman","keynes"],"causal":["inflation","unemployment","ratehike"],"concepts":["Cost-push inflation","Demand-pull inflation","Phillips curve","Natural rate of unemployment","Disinflation","Monetary policy","Contractionary policy","Real interest rate","SRAS","Central bank","Recession"],"cases":["MAC-042","GLO-051"],"policies":["Wage and price controls","Voluntary incomes policy (Whip Inflation Now)","Reserve targeting by the Federal Reserve","Credit controls","Contractionary monetary policy","Income tax cuts (Economic Recovery Tax Act)"],"questions":[{"q":"Using an AD–AS diagram, explain why a sharp rise in oil prices can cause inflation and unemployment to rise at the same time.","kind":"explain"},{"q":"Analyse how rising inflation expectations in the 1970s made inflation more persistent.","kind":"analyse"},{"q":"Evaluate the view that the cost of the 1981–82 recession was a price worth paying to reduce US inflation.","kind":"evaluate"},{"q":"Using the US inflation and unemployment data for 1979–1984, describe how the two series moved and explain the relationship you observe.","kind":"data"},{"q":"Compare the causes of US inflation in the 1970s with the causes of the rise in inflation after 2020.","kind":"compare"}],"retrieval":[{"q":"What is stagflation?","a":"A period in which inflation is high while output stagnates or falls and unemployment rises."},{"q":"Which shift on an AD–AS diagram represents an oil price shock?","a":"A leftward shift of the short-run aggregate supply curve."},{"q":"What did the Fed change on 6 October 1979?","a":"It began targeting the quantity of bank reserves instead of the short-term interest rate, allowing rates to rise sharply."},{"q":"What happened to the short-run Phillips curve as expected inflation rose in the 1970s?","a":"It shifted upwards, so each unemployment rate came with higher inflation."},{"q":"What was US inflation in 1980 and in 1983?","a":"13.5% in 1980 and 3.2% in 1983."}],"reflection":"If ending high inflation requires a recession, who should decide how much unemployment is acceptable, and on what grounds?","reading":[{"t":"Milton Friedman, ‘The Role of Monetary Policy’, American Economic Review, 1968","note":"The classic statement of the natural-rate argument that anticipated the breakdown of the simple Phillips curve."},{"t":"Thomas J. Sargent, ‘The Ends of Four Big Inflations’, 1982","note":"Argues that credible changes in policy regime can end inflation at lower cost; a key text in the credibility debate."},{"t":"Paul Volcker and Toyoo Gyohten, Changing Fortunes, 1992","note":"Volcker’s own account of the period, useful for the reasoning behind the 1979 change of procedure."}],"numbers":[{"value":"roughly quadrupled","claim":"Oil prices rose about fourfold in 1973–74","basis":"Widely documented; posted Gulf crude prices rose from about $3 to about $12 a barrel between mid-1973 and early 1974"},{"value":"more than doubled","claim":"Oil prices more than doubled over 1979–80","basis":"Widely documented effect of the Iranian revolution and the start of the Iran–Iraq war"},{"value":"close to 20%","claim":"The federal funds rate was close to 20% in 1981","basis":"Federal Reserve H.15 effective federal funds rate, monthly averages near 19% in early-to-mid 1981"},{"value":"10.8%","claim":"Monthly US unemployment peaked at 10.8% in late 1982","basis":"BLS seasonally adjusted unemployment rate, November and December 1982"},{"value":"90-day","claim":"Length of Nixon’s initial wage-price freeze","basis":"Executive Order 11615, 15 August 1971"},{"value":"1967 / 1968","claim":"Friedman’s AEA presidential address delivered December 1967, published in the American Economic Review in March 1968","basis":"American Economic Review, vol. 58, no. 1"}]},{"id":"oil-1973","title":"The first oil shock, 1973–74","years":"1973–1974","start":"1973-10","end":"1975-03","region":"Global: oil importers in North America, Western Europe and Japan","kind":"shock","standfirst":"In late 1973 the price of the world’s most important commodity roughly quadrupled within three months. The question for economists was how to respond to a shock that raised inflation and unemployment at the same time.","question":"How can a rise in the price of one input push an economy into inflation and recession at once, and what can policy do about it?","before":{"p":"By the early 1970s the industrial economies ran on cheap oil. Through the 1950s and 1960s crude prices were low and stable, and oil replaced coal in transport, heating, power and petrochemicals. US crude production peaked in 1970, so the United States relied increasingly on imports and lost the spare capacity that had once calmed world markets. The members of OPEC were taking control of output and prices from the large Western oil companies. Inflation was already rising: the Bretton Woods system of fixed exchange rates broke down between 1971 and 1973, and a synchronised boom in 1972–73 pushed up commodity prices.","facts":[{"t":"OPEC was founded in 1960 by Iran, Iraq, Kuwait, Saudi Arabia and Venezuela.","status":"fact"},{"t":"US crude oil production reached a peak in 1970 that was not exceeded until 2018, leaving the country more dependent on imported oil.","status":"fact"},{"t":"US consumer-price inflation was 3.3% in 1972 and 6.2% in 1973, before most of the oil price rise had passed through.","status":"fact"},{"t":"In August 1971 the United States suspended the dollar’s convertibility into gold; major currencies were floating by March 1973.","status":"fact"},{"t":"President Nixon imposed wage and price controls in August 1971; controls on domestic oil prices outlasted most of the others.","status":"fact"}]},"trigger":{"p":"On 6 October 1973 Egypt and Syria attacked Israel, beginning the October (Yom Kippur) War. On 16 October the Gulf members of OPEC raised the posted price of their benchmark crude by about 70% without negotiating with the oil companies. The next day Arab oil ministers announced monthly production cuts, and an embargo on the United States and the Netherlands followed because of their support for Israel. In December the Gulf producers more than doubled the posted price again, from January 1974.","status":"fact"},"timeline":[{"d":"1971-08","t":"Nixon closes the gold window","detail":"The United States suspended dollar convertibility into gold and froze wages and prices. The dollar’s later fall cut the real value of oil revenues priced in dollars, a grievance producers cited.","status":"fact"},{"d":"1973-03","t":"Generalised floating begins","detail":"After a second dollar devaluation in February, major currencies began floating against the dollar. The fixed-rate system of the post-war decades had ended.","status":"fact"},{"d":"1973-10-06","t":"The October War begins","detail":"Egypt and Syria attacked Israeli positions in Sinai and the Golan Heights. Arab oil producers prepared to use oil supplies as a political lever against Israel’s supporters.","status":"fact"},{"d":"1973-10-16","t":"OPEC sets prices without the companies","detail":"Gulf members of OPEC raised the posted price of Arabian Light from about $3 to about $5 a barrel, setting prices unilaterally for the first time rather than negotiating with the oil companies.","status":"fact"},{"d":"1973-10-17","t":"Arab production cuts and embargo","detail":"Arab exporters announced output cuts of 5% a month, followed by an embargo on the United States and the Netherlands. Buyers scrambled for supplies, and prices in spot markets rose well above posted prices.","status":"fact"},{"d":"1973-11","t":"The US economy turns down","detail":"The NBER dates the peak of the US business cycle to November 1973. Real GDP then fell at an annualised rate of 3.4% in the first quarter of 1974.","status":"fact"},{"d":"1973-12","t":"Posted price doubled again","detail":"Meeting in Tehran, Gulf producers set the posted price at $11.65 a barrel from 1 January 1974, roughly four times its level of early October.","status":"fact"},{"d":"1974-01","t":"Britain’s three-day week","detail":"With coal supplies also cut by a miners’ overtime ban, the UK government limited commercial use of electricity to three days a week from January to early March 1974.","status":"fact"},{"d":"1974-03","t":"Embargo on the US lifted","detail":"Most Arab producers ended the embargo on the United States in March 1974, but oil prices stayed at their new, much higher level.","status":"fact"},{"d":"1974-11","t":"International Energy Agency founded","detail":"Oil-importing OECD countries created the IEA to share supplies in emergencies, hold minimum oil stocks and coordinate their energy policies, aiming to reduce exposure to future embargoes.","status":"fact"},{"d":"1975-03","t":"US recession ends","detail":"The NBER dates the trough to March 1975. US unemployment averaged 8.5% in 1975, up from 4.9% in 1973, while inflation was still 9.1%.","status":"fact"},{"d":"1975-12","t":"Energy Policy and Conservation Act","detail":"Congress created the Strategic Petroleum Reserve and fuel-economy standards for new cars, while extending controls on the price of domestically produced crude oil.","status":"fact"}],"actors":[{"who":"OPEC","role":"An organisation of oil-exporting states acting as a cartel. In 1973 its Gulf members took over price-setting from the international oil companies and raised posted prices about fourfold."},{"who":"Arab oil exporters, led by Saudi Arabia","role":"Used production cuts and an embargo as a political weapon during and after the October War, turning a market already tight into an acute shortage."},{"who":"The Federal Reserve under Arthur Burns","role":"Tightened in 1973–74 as inflation rose, then eased as the recession deepened; critics argue policy was too loose across the decade, letting the shock feed wage and price expectations."},{"who":"The Nixon and Ford administrations","role":"Kept controls on domestic oil prices, introduced fuel-saving measures such as a national speed limit and, in 1975, cut taxes to support demand."},{"who":"The major oil companies","role":"Lost control of posted prices and, over the decade, much of their ownership of reserves as producer governments took stakes or nationalised. They gained on inventories and non-OPEC output."},{"who":"Households and firms in importing countries","role":"Faced higher bills for fuel, heating and energy-intensive goods, so their real incomes and profits fell while the prices they paid rose."}],"changed":"Oil-importing economies faced a large transfer of income to oil exporters: the price of their imports rose relative to their exports, and their current accounts weakened. Firms’ costs rose across transport, chemicals, plastics and power, so prices rose while output fell. US real GDP fell 0.5% in 1974 and 0.2% in 1975, unemployment rose from 4.9% in 1973 to 8.5% in 1975, and inflation reached 11.1% in 1974. The post-war belief that policy could steadily trade a little more inflation for lower unemployment was badly shaken.","predict":{"q":"Oil prices roughly quadrupled in three months. Before looking at the mechanism, which pair of outcomes would you expect in an oil-importing economy in 1974–75?","options":["Higher inflation and lower unemployment, as in a demand boom","Higher inflation and higher unemployment","Lower inflation and higher unemployment, as in a demand slump"],"answer":1,"explain":"A rise in the cost of a key input shifts SRAS to the left. The price level rises while real output falls, so inflation and unemployment rise together: stagflation. In the United States inflation was 11.1% in 1974 and unemployment reached 8.5% in 1975. A demand shock would have moved the two in opposite directions."},"mechanism":["Output cuts and embargo → supply of oil shifts left → price rises sharply because short-run demand and supply of oil are price-inelastic","Higher oil price → higher production costs for energy-using firms → SRAS shifts left → price level rises and real output falls (cost-push inflation)","Higher fuel bills → less income left for other goods → spending on cars and other goods falls → AD also weakens","Higher import bills → income transferred to oil exporters, who cannot spend it all at once → world spending falls in the short run","Rising prices → workers bargain for higher wages and expect more inflation → wage–price spiral shifts SRAS left again","Central bank accommodates → inflation persists; central bank tightens → recession deepens: the policy dilemma of a supply shock","Price controls on US crude → domestic price held below the world price → excess demand, queues and weaker incentives to conserve or produce"],"charts":[{"series":"us-gdp-q","from":"1973-01","to":"1974-10","title":"US real GDP, quarter by quarter","look":"Output had already dipped in mid-1973. After the October price rise, growth was negative in three of the four quarters of 1974, turning a slowdown into a recession.","marks":[{"at":"1973-10","label":"War and embargo"}]},{"panel":"infl","entities":["USA","GBR","JPN","DEU"],"from":"1970","to":"1979","title":"Same shock, different inflation","look":"Japan’s inflation reached 23.2% in 1974 and Britain’s 24.2% in 1975, while Germany’s peaked at 7.0%. Wage bargaining and monetary policy shaped how far the shock fed into prices.","marks":[{"at":"1974","label":"First full year"}]},{"series":"sp500-real","from":"1973-01","to":"1974-12","title":"Real share prices","look":"Inflation-adjusted share prices fell by more than half between January 1973 and December 1974 as profits were squeezed, inflation rose and interest rates climbed.","marks":[{"at":"1973-10","label":"October War"}]},{"series":"us-unemp","from":"1970","to":"1980","title":"US unemployment","look":"Unemployment rose from 4.9% in 1973 to 8.5% in 1975 and fell only slowly afterwards, even though inflation stayed high: the combination the simple Phillips curve did not expect.","marks":[{"at":"1975","label":"Peak year"}]}],"diagrams":[{"dg":"costpush","how":"Draw AD and SRAS₁ meeting at P₁ and Y₁ near full employment. Shift SRAS left to SRAS₂ because energy costs rise. The price level rises to P₂ and real output falls to Y₂. Note that expansionary policy, shifting AD right, would raise output but push prices higher still."},{"dg":"sshift","how":"In the world oil market, shift supply to the left (embargo and output cuts) along a steep, price-inelastic demand curve. The price rises far more, in percentage terms, than quantity falls, so producers’ total revenue rises."}],"policy":[{"who":"US Congress","when":"1973-11","what":"The Emergency Petroleum Allocation Act kept federal controls on domestic crude prices and allocated supplies among refiners and regions. Prices stayed below world levels, and many economists link the controls to shortages and petrol queues.","status":"fact"},{"who":"US Congress","when":"1974-01","what":"The Emergency Highway Energy Conservation Act set a national speed limit of 55 miles per hour to save fuel, one of several measures aimed at cutting demand rather than raising supply.","status":"fact"},{"who":"Federal Reserve","when":"1974","what":"Raised interest rates as inflation passed 10%, then cut them from late 1974 as unemployment rose. Critics argue it was too tight during the recession or too loose over the decade as a whole.","status":"fact"},{"who":"International Monetary Fund","when":"1974","what":"Set up an oil facility to lend to member countries facing larger oil import bills, helping to recycle oil exporters’ surpluses to importing countries with deficits.","status":"fact"},{"who":"OECD oil importers","when":"1974-11","what":"Created the International Energy Agency, with an emergency system for sharing oil among members and obligations to hold stocks, to reduce exposure to future embargoes.","status":"fact"},{"who":"US Congress","when":"1975-03","what":"The Tax Reduction Act gave households a one-off rebate on 1974 taxes and cut taxes for 1975, an expansionary fiscal response once the recession was clear.","status":"fact"}],"stakeholders":[{"who":"Oil-exporting governments","effect":"Revenues multiplied almost overnight, financing development spending and large purchases of foreign assets; some, such as Saudi Arabia, earned far more than they could spend quickly."},{"who":"Households in importing countries","effect":"Paid more for fuel and heating, so real incomes fell. Low-income households, which spend a larger share of income on energy, were hit hardest."},{"who":"Energy-intensive industries","effect":"Airlines, chemicals and car makers faced higher costs and weaker demand; US car makers lost sales to smaller, more fuel-efficient imported cars."},{"who":"Non-oil developing countries","effect":"Faced higher import bills and slower export demand. Many borrowed heavily, often from Western banks recycling oil surpluses, building debts that became a crisis in the 1980s."},{"who":"Non-OPEC producers","effect":"Higher prices made costly fields worth developing; North Sea and Alaskan oil began flowing later in the decade, reducing reliance on OPEC."}],"short":"In the short run the shock hit through prices and confidence. Petrol queues, rationing plans and speed limits appeared. Firms passed higher energy costs on, so inflation jumped: 11.1% in the United States in 1974 and 16.0% in the UK. Real incomes fell and spending on cars and other durables dropped, so the US entered a recession that lasted from November 1973 to March 1975. Share prices fell steeply. Policymakers faced a dilemma: easing would support jobs but add to inflation.","long":"The long-run effects ran through energy use, technology and ideas. Higher prices encouraged insulation, smaller cars, fuel-economy standards and new non-OPEC supply, so oil demand became more price-elastic over time. Productivity growth slowed in many rich economies after 1973, though how much oil was to blame is debated. OPEC surpluses were recycled through Western banks to borrowers in Latin America and elsewhere. In economics, the episode weakened faith in a stable Phillips curve trade-off and strengthened monetarist and supply-side arguments.","transmission":"The shock spread through trade, finance and prices. Every oil importer faced the same jump in its import bill, so inflation rose and growth slowed in many countries at once. Exporters’ surpluses were mirrored by deficits in importers’ current accounts. Floating exchange rates, new since 1973, absorbed some pressure but let weaker currencies fall, adding to imported inflation. Banks recycled petrodollar deposits as loans to developing countries. Outcomes differed: Germany’s tighter policy and wage restraint kept inflation far lower than in Britain or Japan.","winners":[{"t":"Oil-exporting governments, whose revenues multiplied.","status":"fact"},{"t":"Oil producers outside OPEC, such as North Sea and Alaskan fields, which became profitable at higher prices.","status":"fact"},{"t":"Makers of small, fuel-efficient cars, notably Japanese firms that gained market share in the United States.","status":"inference"}],"losers":[{"t":"Oil-importing developing countries facing higher import bills without oil revenues.","status":"fact"},{"t":"Workers in energy-intensive and car industries who lost jobs in the 1973–75 recession.","status":"fact"},{"t":"Savers holding cash and fixed-rate bonds, whose real value was eroded by double-digit inflation.","status":"inference"}],"unintended":[{"t":"US price controls, meant to protect consumers, weakened incentives to conserve and to produce, and contributed to petrol queues.","status":"interpretation"},{"t":"Recycling oil surpluses as bank loans to developing countries eased adjustment in the 1970s but built the debts behind the 1980s debt crisis.","status":"interpretation"},{"t":"High prices spurred non-OPEC exploration and energy efficiency, which later weakened OPEC’s market power.","status":"inference"}],"interpretations":[{"view":"Supply-shock view (mainstream)","p":"The oil price rise was an adverse supply shock that shifted SRAS left and made importing countries poorer. Some rise in prices and fall in output could not be avoided; policy could only decide how to split the pain between inflation and unemployment, and how long it lasted.","status":"interpretation"},{"view":"Monetarist (Friedman)","p":"A rise in one relative price need not raise the general price level persistently. Sustained inflation required monetary accommodation, and inflation was already rising before October 1973 because money growth had been too fast. On this view oil was the occasion, not the root cause, of 1970s inflation.","status":"interpretation"},{"view":"Barsky and Kilian","p":"Causation may partly run the other way: a global monetary expansion and boom in 1972–73 raised commodity prices and strengthened OPEC’s hand, so the oil shock was partly a symptom of earlier policy. Others stress the war and embargo as genuinely external. The weight to give each is disputed.","status":"controversy"},{"view":"Monetary response view (Bernanke and co-authors)","p":"Some research suggests much of the output loss after oil shocks came from central banks’ tightening in response to higher inflation, not from the oil price itself. Critics question the method and argue the oil effect was large on its own.","status":"controversy"}],"explain":["The cost-push AD–AS model shows why a rise in input costs raises the price level and cuts real output at the same time.","Low short-run price elasticity of demand for oil explains why modest supply cuts produced huge price rises and higher revenue for producers.","Cartel theory explains why coordinated output restrictions raise members’ joint profits, at least while members comply with their quotas."],"miss":["A one-off SRAS shift predicts a one-off rise in the price level, not years of high inflation; persistence needs expectations, wage bargaining and monetary accommodation.","Static models miss the time dimension: oil demand and non-OPEC supply became much more elastic over a decade, eroding the cartel’s power.","Simple models struggle to separate the oil shock from the earlier demand boom, the end of Bretton Woods and the productivity slowdown that coincided with it."],"differently":[{"t":"Letting domestic oil prices rise to world levels, with targeted help for poor households, would have encouraged conservation and supply and avoided queues. Critics of decontrol worried about windfall gains for producers and the burden on low-income consumers.","status":"controversy"},{"t":"A firmer monetary response, as in West Germany, might have limited second-round wage and price effects. The cost would have been a deeper short-run recession, which is why many governments chose to accommodate.","status":"interpretation"},{"t":"Holding emergency stocks and diversifying energy supplies before 1973 would have reduced vulnerability. Importers did this mainly after the shock, through the IEA’s stockholding rules and national reserves such as the US Strategic Petroleum Reserve.","status":"interpretation"}],"whatif":{"q":"Suppose the Federal Reserve had kept money growth tight throughout 1973–75. What would most likely have happened?","options":["Neither inflation nor unemployment would have risen","Inflation would probably have been lower, but the recession deeper or longer","Inflation would have been higher, because tight money raises firms’ costs"],"best":1,"explain":"Tight money cannot undo a supply shock: the higher oil price still shifts SRAS left. It can limit second-round effects on wages and expectations, so inflation would probably have been lower, as West Germany’s experience suggests. With AD held back while SRAS falls, output and employment would probably have fallen further in the short run. The size of each effect is uncertain and depends on how quickly expectations adjusted."},"compare":[{"id":"oil-1979","similar":"Both were oil supply disruptions linked to Middle East politics that sharply raised prices, pushed up inflation and contributed to recessions in oil-importing economies, with petrol queues in the United States.","different":"In 1979 the supply loss came from revolution and panic buying rather than a cartel decision, and the Fed under Volcker responded with sustained tightening rather than accommodation.","dominant":"1973–74: a cartel-driven SRAS shift, met by accommodating policy in many countries. 1979–80: a supply disruption followed by a monetary regime change aimed at breaking inflation."},{"id":"bretton-woods-1971","similar":"Both ended the post-war stability of the 1960s and fed 1970s inflation; the dollar’s fall after 1971 was one reason oil exporters wanted higher dollar prices.","different":"The end of Bretton Woods was a change in the international monetary system chosen by governments; the oil shock was a sudden rise in the price of a key input.","dominant":"1971–73: a monetary and exchange-rate regime change that loosened the anchor on inflation. 1973–74: a real supply shock to costs and output."},{"id":"stagflation-1970s","similar":"The 1973–74 shock opened the decade of stagflation, combining rising inflation with rising unemployment and weak growth across the industrial economies, and both challenged the simple Phillips curve.","different":"The oil shock was a single, datable event; the wider stagflation also reflected loose money, rising inflation expectations, a second oil shock and slower productivity growth over many years.","dominant":"1973–74: a sudden SRAS shift. The 1970s as a whole: repeated supply shocks combined with accommodating demand policy and entrenched expectations."}],"ib":{"subs":["2.2","2.5","2.11","3.2","3.3","3.5","4.6"],"kc":["Change","Interdependence","Scarcity","Intervention","Economic well-being"],"note":"Supports analysis of cost-push inflation with an SRAS shift, use of PED to explain oil revenue, and evaluation of policy trade-offs; the cartel analysis links to market power, which is HL only (2.11)."},"cambridge":{"topics":["cost-push inflation","aggregate supply","price elasticity of demand","oligopoly and cartels","balance of payments","inflation and unemployment"],"note":"A clear case for showing how a change in a single input price affects the whole economy."},"university":{"fields":["macroeconomics","energy economics","international economics","economic history"],"note":"A university course would add econometric evidence on the effects of oil shocks, the distinction between supply-driven and demand-driven oil price changes, and models of optimal monetary policy after a supply shock."},"civil":{"themes":["external sector","inflation management","energy security","balance of payments"],"note":"India’s inflation reached 28.6% in 1974 as oil and food prices rose together; the episode is a reference point for India’s exposure to imported energy and its current account."},"economists":["friedman","keynes"],"causal":["inflation","unemployment","growth"],"concepts":["Cost-push inflation","SRAS","Aggregate supply","Primary commodity","Price elasticity of demand","Oligopoly","Collusion","Current account","Price ceiling","Phillips curve","Floating exchange rate","Recession","Inflation"],"cases":["MAC-042","MIC-033","GLO-031","GLO-051"],"policies":["Emergency Petroleum Allocation Act (1973)","National 55 mph speed limit (1974)","IMF oil facility (1974)","International Energy Agency emergency sharing (1974)","Tax Reduction Act of 1975","Strategic Petroleum Reserve (1975)","Domestic oil price controls"],"questions":[{"q":"Explain why the 1973–74 oil price rise increased both inflation and unemployment in the United States.","kind":"explain"},{"q":"Using a diagram, analyse why oil exporters’ revenue rose even though the quantity of oil they sold fell.","kind":"analyse"},{"q":"Evaluate the use of price controls on domestic oil as a response to the 1973 oil shock.","kind":"evaluate"},{"q":"Using the inflation data for 1973–76, compare Germany and the United Kingdom and suggest two reasons for the difference.","kind":"data"},{"q":"Compare how the 1973 oil shock and the Great Depression appear on an AD–AS diagram, and explain what this implies for policy.","kind":"compare"}],"retrieval":[{"q":"When did the Arab oil embargo begin and end?","a":"It was announced in October 1973 and lifted for the United States in March 1974."},{"q":"What is cost-push inflation?","a":"A rise in the general price level caused by higher costs of production, shown as a leftward shift of SRAS."},{"q":"What was US inflation in 1974?","a":"11.1%."},{"q":"Why did oil revenues rise when output was cut?","a":"Short-run demand for oil was price-inelastic, so the percentage rise in price exceeded the percentage fall in quantity."},{"q":"What was the International Energy Agency set up to do?","a":"Coordinate importing countries’ energy policies, require oil stocks and share supplies in emergencies."}],"reflection":"If a supply shock makes a country poorer, can any macroeconomic policy avoid the loss, or can it only decide who bears it?","reading":[{"t":"Daniel Yergin, The Prize: The Epic Quest for Oil, Money and Power, 1991","note":"A detailed history of the oil industry, including the rise of OPEC and the 1973 embargo."},{"t":"Alan S. Blinder, Economic Policy and the Great Stagflation, 1979","note":"A contemporary economist’s analysis of supply shocks and US policy in the 1970s."},{"t":"Robert B. Barsky and Lutz Kilian, Do We Really Know that Oil Caused the Great Stagflation? A Monetary Alternative, 2001","note":"Sets out the argument that monetary conditions, not only oil, drove 1970s inflation."}],"numbers":[{"value":"about 70%","claim":"Rise in the posted price of Arabian Light on 16 October 1973 (from about $3.01 to $5.12 a barrel).","basis":"Decision of OPEC’s Gulf members, 16 October 1973; widely documented (e.g. Yergin, The Prize)."},{"value":"$11.65","claim":"Posted price of Arabian Light from 1 January 1974.","basis":"Tehran meeting of Gulf producers, December 1973; widely documented."},{"value":"roughly quadrupled / about fourfold","claim":"Increase in the posted oil price between early October 1973 and January 1974.","basis":"$3.01 to $11.65 per barrel; widely documented."},{"value":"5% a month","claim":"Arab production cuts announced on 17 October 1973.","basis":"OAPEC ministers’ announcement in Kuwait; widely documented."},{"value":"55 miles per hour","claim":"National speed limit set by the Emergency Highway Energy Conservation Act.","basis":"US federal law signed January 1974."},{"value":"1960; five founders","claim":"OPEC founding year and members.","basis":"Baghdad conference, September 1960."}]},{"id":"oil-1979","title":"The second oil shock, 1979–80","years":"1979–1980","start":"1978-10","end":"1982","region":"Global: Iran, the United States, Western Europe and Japan","kind":"shock","standfirst":"Revolution in Iran took one of the world’s largest oil exporters out of the market, and fear did the rest: crude prices more than doubled. This time the decisive response came from central banks, which chose to break inflation even at the cost of deep recession.","question":"Why did a partial loss of oil supply cause such a large price rise, and why was the policy response so different from 1973?","before":{"p":"After the first oil shock, the dollar price of oil rose only gradually between 1974 and 1978, and in real terms it drifted down as general inflation eroded it. Western economies recovered from the 1974–75 recession, but inflation stayed high, and the dollar fell sharply against the yen and the Deutsche Mark in 1977–78. Many governments still hoped to bring unemployment down without much extra inflation. Iran was one of OPEC’s largest exporters, and the Shah was a close ally of the West. In the United States, federal controls still held domestic crude prices below world levels.","facts":[{"t":"US consumer-price inflation was 6.5% in 1977 and 7.6% in 1978.","status":"fact"},{"t":"The yen strengthened from an average of 268.38 per dollar in 1977 to 210.46 in 1978.","status":"fact"},{"t":"Iran was OPEC’s second-largest exporter after Saudi Arabia in the late 1970s.","status":"fact"},{"t":"US controls on domestic crude oil prices, introduced in the early 1970s, were still in force in 1978.","status":"fact"}]},"trigger":{"p":"From October 1978, strikes by Iranian oil workers, part of the revolution against the Shah, cut Iran’s exports sharply, and they almost stopped around the turn of the year. The Shah left Iran in January 1979. Saudi Arabia and other producers raised output, but buyers feared further disruption and rushed to build stocks. Precautionary buying on top of the lost Iranian supply pushed spot prices far above official contract prices, and OPEC members raised their official prices in successive steps through 1979.","status":"fact"},"timeline":[{"d":"1978-10","t":"Strikes hit Iranian oil fields","detail":"Oil workers joined the revolutionary movement against the Shah. Iranian production fell steeply over the following weeks, removing a large share of OPEC exports from the market.","status":"fact"},{"d":"1979-01","t":"The Shah leaves Iran","detail":"The Shah left the country on 16 January and Ayatollah Khomeini returned on 1 February. Iranian exports resumed later in 1979, but at a lower level than before the revolution.","status":"fact"},{"d":"1979-04","t":"Carter announces phased decontrol","detail":"President Carter announced that controls on domestic crude prices would be phased out from June 1979, paired with a proposed tax on producers’ windfall profits.","status":"fact"},{"d":"1979-06","t":"Petrol queues in the United States","detail":"Allocation rules and price controls, combined with panic buying, produced long queues at petrol stations; several states introduced odd–even rationing based on number plates.","status":"fact"},{"d":"1979-07","t":"Carter’s energy address","detail":"In a televised speech on 15 July, President Carter described a national crisis of confidence and proposed limits on oil imports and a large synthetic-fuels programme.","status":"fact"},{"d":"1979-08","t":"Volcker becomes Fed chair","detail":"Paul Volcker took office at the Federal Reserve on 6 August, with US inflation running above 10% and the dollar under pressure in foreign exchange markets.","status":"fact"},{"d":"1979-10-06","t":"The Fed changes its approach","detail":"The Fed announced it would target the growth of bank reserves rather than short-term interest rates, allowing rates to rise as far as needed to slow money growth.","status":"fact"},{"d":"1980-01","t":"Recession begins","detail":"The NBER dates a US cycle peak to January 1980. In March the administration and the Fed introduced credit controls, which cut consumer borrowing sharply before they were lifted in July.","status":"fact"},{"d":"1980-04","t":"Windfall profit tax enacted","detail":"Congress passed the Crude Oil Windfall Profit Tax Act, taxing part of the gain domestic producers received as controlled prices rose towards world levels.","status":"fact"},{"d":"1980-09","t":"Iran–Iraq war begins","detail":"Iraq invaded Iran on 22 September, cutting exports from both countries and pushing prices up again; crude prices for this episode peaked around the turn of 1980–81.","status":"fact"},{"d":"1981-01","t":"Reagan completes decontrol","detail":"On 28 January 1981 President Reagan ended the remaining federal controls on crude oil and petrol prices, months ahead of the planned timetable.","status":"fact"},{"d":"1982","t":"Disinflation and deep recession","detail":"With interest rates very high, US unemployment averaged 9.7% in 1982 and inflation fell to 6.1%, then 3.2% in 1983. In August, Mexico’s debt crisis spread the strain to borrowing countries.","status":"fact"}],"actors":[{"who":"Iranian oil workers and the revolutionary movement","role":"Strikes from October 1978 brought Iranian oil production close to a halt, the immediate cause of the loss of supply."},{"who":"Saudi Arabia and other OPEC producers","role":"Saudi Arabia raised output to offset part of the loss, but OPEC members also raised official prices repeatedly, and for a period members charged different official prices."},{"who":"Paul Volcker and the Federal Reserve","role":"Chair from August 1979. Shifted to targeting bank reserves and let short-term interest rates rise to around 20%, accepting recession to break inflation expectations."},{"who":"Jimmy Carter","role":"President 1977–81. Began phased oil price decontrol, introduced a windfall profit tax and conservation measures, and appointed Volcker to the Federal Reserve."},{"who":"Margaret Thatcher’s government","role":"Elected in May 1979. Pursued tight monetary targets while North Sea oil and high interest rates pushed sterling up, squeezing British manufacturing."},{"who":"Japanese firms and unions","role":"Kept wage settlements moderate after 1979, limiting second-round inflation; Japan’s inflation peaked at 7.8% in 1980, against 23.2% in 1974."}],"changed":"Oil prices more than doubled between 1978 and 1980, renewing cost-push pressure in economies where inflation was already high. US inflation rose to 13.5% in 1980. The decisive change came in policy: central banks, led by the Federal Reserve, made reducing inflation their priority. Long-term US interest rates rose, with the 10-year yield averaging 13.91% in 1981, the dollar strengthened, and the US had two recessions in quick succession. By 1983 inflation had fallen to 3.2%. High prices also cut oil demand and spurred non-OPEC supply.","predict":{"q":"From October 1979 the Fed let short-term interest rates rise to record levels while inflation was above 10%. What would you expect to happen first?","options":["Inflation falls quickly with little effect on output","Output and employment fall first; inflation falls more slowly","Inflation rises further because higher rates raise firms’ costs"],"answer":1,"explain":"Monetary policy works with lags. Higher real interest rates cut investment, house building and spending on durables, so AD falls and unemployment rises before wage and price setting adjusts. US unemployment averaged 9.7% in 1982, while inflation fell from 13.5% in 1980 to 3.2% in 1983. The cost of disinflation fell first on output and jobs."},"mechanism":["Iranian strikes and revolution → supply of oil shifts left → with price-inelastic short-run demand, the price rises sharply","Fear of further disruption → firms and governments buy for stocks → demand for oil shifts right, adding to the price rise","Higher oil price → SRAS shifts left in importing economies → cost-push inflation and lower real output","Inflation already high and expected to persist → wages indexed or bargained upward → second-round effects risk a wage–price spiral","Fed targets reserves → short-term rates rise to around 20% → real interest rates turn strongly positive → investment and consumption fall → AD shifts left","Higher US interest rates → capital inflows → dollar appreciates → import prices fall, helping disinflation, while US exporters lose competitiveness","Sustained tightening → inflation expectations fall → the short-run Phillips curve shifts down over time (a shift, not a movement along the curve)","Prices stay high for several years → more efficient energy use and more non-OPEC supply → oil demand and supply become more elastic → prices fall in the mid-1980s"],"charts":[{"series":"us-cpi-infl","from":"1975","to":"1986","title":"US inflation: second peak and the break","look":"Inflation rose from 7.6% in 1978 to 13.5% in 1980, then fell to 3.2% by 1983 as tight money took hold. Compare the speed of this fall with the slow decline after 1975.","marks":[{"at":"1979","label":"Volcker appointed"},{"at":"1983","label":"Inflation at 3.2%"}]},{"series":"us10y","from":"1975","to":"1986","title":"Long-term interest rates","look":"The 10-year yield rose from 8.41% in 1978 to 13.91% in 1981 as the Fed tightened and investors demanded compensation for inflation risk. It fell as inflation came down.","marks":[{"at":"1979","label":"Fed changes approach"}]},{"series":"us-unemp","from":"1976","to":"1986","title":"The output cost of disinflation","look":"Unemployment rose in 1980 and again, more steeply, to average 9.7% in 1982. Compare this with the fall in inflation in the first chart to see the trade-off.","marks":[{"at":"1982","label":"Peak year"}]},{"panel":"infl","entities":["USA","GBR","JPN","DEU"],"from":"1976","to":"1985","title":"Second shock, different results","look":"Japan’s inflation peaked at 7.8% in 1980, far below its 1974 peak, while Britain’s reached 18.0%. Wage bargaining and monetary credibility mattered as much as the oil price.","marks":[{"at":"1980","label":"Peak for most"}]}],"diagrams":[{"dg":"costpush","how":"Shift SRAS left as oil costs rise, raising the price level and cutting real output. Then show the policy response: contractionary monetary policy shifts AD left, holding the price level down but reducing real output still further in the short run."},{"dg":"phillips","how":"HL only. Draw a short-run Phillips curve at high expected inflation and a vertical long-run curve at the natural rate. Tight money moves the economy along the short-run curve to higher unemployment; as expected inflation falls, the short-run curve shifts down."}],"policy":[{"who":"Federal Reserve","when":"1979-10","what":"Switched to targeting bank reserves and money growth, letting short-term interest rates rise to around 20% at their peaks in 1980–81. The aim was to break inflation expectations, accepting a recession.","status":"fact"},{"who":"Carter administration and Federal Reserve","when":"1980-03","what":"Introduced credit controls to restrain consumer borrowing. Spending fell much faster than expected, the economy contracted sharply in the second quarter, and the controls were lifted by July.","status":"fact"},{"who":"US Congress","when":"1980-04","what":"Passed the Crude Oil Windfall Profit Tax Act, an excise tax on part of the difference between decontrolled prices and a base price, so that the government shared in producers’ gains.","status":"fact"},{"who":"Reagan administration","when":"1981-01","what":"Ended remaining federal price and allocation controls on crude oil and petrol, letting domestic prices move with world prices and removing the rules blamed for the 1979 queues.","status":"fact"},{"who":"UK government","when":"1980-03","what":"The Medium Term Financial Strategy set declining targets for money growth and public borrowing over several years, aiming to bring down inflation and the inflation expectations built into wages.","status":"fact"}],"stakeholders":[{"who":"US borrowers and home-buyers","effect":"Faced loan and mortgage rates at record levels; house building and car sales fell sharply in 1980–82 as higher real interest rates cut demand for credit."},{"who":"Manufacturing workers in the US and UK","effect":"Bore heavy job losses as demand fell and strong currencies hurt exports; many plants in older industrial regions closed permanently."},{"who":"Savers and lenders","effect":"Gained once interest rates rose well above inflation in the early 1980s, ending years in which real returns on deposits and bonds had often been negative."},{"who":"Developing-country borrowers","effect":"Had borrowed at floating rates in dollars; higher US rates and a stronger dollar raised debt service sharply, leading to Mexico’s 1982 crisis and a lost decade in Latin America."},{"who":"Oil exporters","effect":"Earned large revenues in 1979–81, but high prices reduced demand for OPEC oil, and its market share and prices fell in the mid-1980s."}],"short":"In 1979 the shock looked like a repeat of 1973: petrol queues, rising prices and falling confidence. US inflation rose to 11.3% in 1979 and 13.5% in 1980. The difference was the policy response. After October 1979 the Fed let interest rates rise steeply, and the 1980 credit controls briefly cut consumer spending. US real GDP fell 0.3% in 1980; after a short recovery a deeper recession followed from mid-1981 to late 1982, and unemployment averaged 9.7% in 1982.","long":"Over the following decade inflation fell across most rich economies, and governments increasingly gave central banks independence and clear inflation goals to lock in the gains. High oil prices accelerated energy saving and non-OPEC production in the North Sea, Alaska and Mexico, and the oil price fell sharply in 1986. The years of high interest rates and a strong dollar left a legacy of debt crises in Latin America and job losses in older industries. The episode became the standard example of a disinflation that worked but was costly.","transmission":"The oil price rise reached every importer at once, but after 1979 transmission ran mainly through interest rates and exchange rates. Tight US policy drew capital into dollar assets, the dollar rose, and other central banks had to choose between matching US rates and accepting weaker currencies and imported inflation. Developing countries that had borrowed in dollars at floating rates saw debt service jump as commodity prices fell, and Mexico’s 1982 crisis began a wider debt crisis. Oil exporters gained until demand fell.","winners":[{"t":"Oil exporters and non-OPEC producers in 1979–81, while prices stayed high.","status":"fact"},{"t":"Savers and creditors once real interest rates turned clearly positive in the early 1980s.","status":"inference"},{"t":"Holders of dollar assets as the dollar appreciated from 1980–81.","status":"inference"}],"losers":[{"t":"Indebted developing countries facing higher interest costs and weaker commodity export prices.","status":"fact"},{"t":"Workers in US and UK manufacturing during the 1980–82 recessions.","status":"fact"},{"t":"Households with variable-rate debt, and firms in interest-sensitive sectors such as housing and cars.","status":"inference"}],"unintended":[{"t":"US price controls and allocation rules, meant to shield consumers, worsened the 1979 petrol queues by stopping prices from clearing local shortages.","status":"interpretation"},{"t":"Sustained high oil prices undermined OPEC by encouraging conservation and rival supply, contributing to the 1986 price collapse.","status":"inference"},{"t":"The 1980 credit controls cut spending far more sharply than intended and were withdrawn within months.","status":"inference"}],"interpretations":[{"view":"Monetarist (Friedman)","p":"Inflation is ultimately a monetary phenomenon. The oil shock raised one relative price, but double-digit inflation persisted because money had grown too fast for a decade. On this view Volcker’s control of money growth, not oil, explains why inflation fell after 1980.","status":"interpretation"},{"view":"Keynesian and supply-shock view","p":"Oil drove much of the 1979–80 spike, and falling commodity prices later helped disinflation. Tight money was needed, but its costs were larger than necessary; a more gradual approach, perhaps with incomes policies, might have cut inflation with less unemployment.","status":"interpretation"},{"view":"Credibility and expectations","p":"The cost of disinflation depends on whether people believe the central bank. Volcker’s sustained tightening eventually established credibility and lowered expected inflation; the recession was deep partly because credibility had been lost in the 1970s and took time to rebuild.","status":"interpretation"},{"view":"The British debate","p":"Economists dispute whether the 1980–81 slump in British manufacturing came mainly from tight monetary policy, from North Sea oil pushing up sterling, or from both. In 1981, 364 economists signed a public letter opposing the government’s macroeconomic policy, yet output began to recover later that year, which each side read differently.","status":"controversy"}],"explain":["The cost-push AD–AS model shows why the oil price rise raised prices and cut real output again in 1979–80.","The expectations-augmented Phillips curve (HL only) explains why reducing inflation required a period of unemployment above the natural rate.","The foreign exchange model shows why higher US interest rates attracted capital and appreciated the dollar, spreading tight policy abroad."],"miss":["Standard models treat the oil market as a supply shift, but much of the 1979 price spike came from precautionary buying and expectations, not lost production alone.","They give little guidance on how fast credibility builds, which largely decided how costly the Volcker disinflation turned out to be.","Simple models miss distributional effects: high rates and a strong dollar concentrated losses on manufacturing regions and indebted developing countries.","Money-growth targets worked less well than monetarist models suggested, partly because the demand for money became unstable as financial markets were deregulated."],"differently":[{"t":"Removing US oil price controls earlier would have let prices ration supply and reduced the 1979 queues, at the cost of higher prices for consumers in the short run and larger windfall gains for domestic producers.","status":"interpretation"},{"t":"A more gradual disinflation, possibly supported by incomes policies, might have reduced the unemployment cost. Critics argue gradualism had failed in the 1970s and only a sharp break could restore credibility.","status":"controversy"},{"t":"Clearer coordination of stock policies among oil-importing countries in 1979 might have damped the precautionary buying that added so much to the price spike, since much of the shortage came from stockbuilding rather than lost production.","status":"interpretation"}],"whatif":{"q":"If the Fed had not tightened sharply in 1979–81, what would most likely have happened to US inflation in the early 1980s?","options":["It would have fallen anyway as oil prices eased","It would probably have stayed high for longer, with a milder recession at first","It would have fallen faster, because high interest rates add to costs"],"best":1,"explain":"Without tighter money, expectations of high inflation would probably have persisted, so inflation would likely have stayed higher for longer, although the 1986 oil price fall would eventually have helped. Unemployment might have been lower in 1981–82. Some economists argue the later costs of entrenched inflation would have been greater; the size of the trade-off cannot be measured directly."},"compare":[{"id":"oil-1973","similar":"Both were Middle East supply disruptions that sharply raised oil prices and inflation in importing countries, and both brought petrol queues to the United States under price controls.","different":"In 1979 the loss came from revolution rather than a cartel decision, precautionary buying amplified it, and central banks responded with sustained tightening instead of accommodation.","dominant":"1973–74: an SRAS shift met by accommodating policy, leading to entrenched inflation. 1979–82: an SRAS shift followed by a deliberate leftward AD shift to break expectations."},{"id":"stagflation-1970s","similar":"The 1979 shock was the final and most acute phase of the 1970s stagflation, combining high inflation with weak growth and rising unemployment in most industrial economies.","different":"The 1970s stagflation built over a decade from several causes; the 1979–80 episode added a sharp new oil shock and ended with a change of regime in monetary policy.","dominant":"The 1970s as a whole: repeated supply shocks plus loose money and rising expectations. 1979–82: an oil shock followed by a demand contraction that reset expectations."}],"ib":{"subs":["3.2","3.3","3.5","3.7","4.5","4.6"],"kc":["Change","Intervention","Economic well-being","Interdependence","Equity"],"note":"Supports evaluation of contractionary monetary policy and its trade-offs, analysis of cost-push inflation, and (HL only) application of the short-run and long-run Phillips curves to disinflation."},"cambridge":{"topics":["inflation","monetary policy","unemployment","exchange rates","price controls","supply-side policy"],"note":"A case for weighing the costs of reducing inflation against unemployment, and for linking interest rates to exchange rates."},"university":{"fields":["monetary economics","macroeconomics","economic history","international finance"],"note":"A university course would add the expectations-augmented Phillips curve, rules versus discretion and time inconsistency, estimates of the sacrifice ratio, and the literature on the 1980s debt crisis."},"civil":{"themes":["inflation management","monetary policy","external sector","energy security"],"note":"India’s inflation reached 11.3% in 1980 as oil import costs rose; the Volcker episode is also a reference point in debates on inflation targeting, which India adopted in 2016."},"economists":["friedman","keynes"],"causal":["inflation","ratehike","unemployment"],"concepts":["Cost-push inflation","Monetary policy","Contractionary policy","Real interest rate","Phillips curve","Natural rate of unemployment","Disinflation","Price ceiling","Appreciation","Recession","Central bank","Inflation targeting"],"cases":["MAC-042","MAC-012","MAC-003"],"policies":["Fed reserve targeting (October 1979)","Credit Control Program (1980)","Crude Oil Windfall Profit Tax Act (1980)","Oil price decontrol (1979–81)","Medium Term Financial Strategy (UK, 1980)","Odd–even petrol rationing"],"questions":[{"q":"Explain how a rise in interest rates by a central bank can reduce inflation.","kind":"explain"},{"q":"Analyse why the 1979–82 disinflation in the United States was accompanied by high unemployment.","kind":"analyse"},{"q":"Evaluate the decision of the Federal Reserve to give priority to reducing inflation over reducing unemployment in 1979–82.","kind":"evaluate"},{"q":"Using US data for 1978–1983, describe what happened to inflation, unemployment and the 10-year bond yield, and explain one reason for each change.","kind":"data"},{"q":"Compare Japan’s inflation in 1974 and 1980. What does the difference suggest about the role of wage bargaining and monetary policy after a supply shock?","kind":"compare"}],"retrieval":[{"q":"What cut Iran’s oil exports in late 1978?","a":"Strikes by oil workers during the revolution against the Shah."},{"q":"What did the Fed announce on 6 October 1979?","a":"It would target bank reserves and money growth rather than short-term interest rates, allowing rates to rise sharply."},{"q":"What was US inflation in 1980, and in 1983?","a":"13.5% and 3.2%."},{"q":"What is disinflation?","a":"A fall in the rate of inflation: prices still rise, but more slowly."},{"q":"Why did the dollar appreciate in the early 1980s?","a":"High US interest rates attracted capital inflows, raising demand for dollars."}],"reflection":"Was the unemployment of 1981–82 a price worth paying for lower inflation, and who should have the power to make that choice?","reading":[{"t":"William L. Silber, Volcker: The Triumph of Persistence, 2012","note":"A biography centred on the Fed’s anti-inflation policy of 1979–82."},{"t":"Paul A. Volcker and Toyoo Gyohten, Changing Fortunes: The World’s Money and the Threat to American Leadership, 1992","note":"First-hand accounts of the period by the US and Japanese officials involved."},{"t":"Daniel Yergin, The Prize: The Epic Quest for Oil, Money and Power, 1991","note":"Covers the Iranian revolution, the 1979 panic and the 1986 price collapse."}],"numbers":[{"value":"more than doubled","claim":"World crude oil prices between 1978 and 1980.","basis":"Widely documented (e.g. official Saudi and spot prices rose from roughly $13–14 to over $30 a barrel); the catalogue Brent series begins only in 1987."},{"value":"around 20%","claim":"Peak short-term US interest rates (federal funds rate) in 1980–81.","basis":"Federal Reserve H.15 data: effective federal funds rate peaked near 19–20% in 1980–81; widely documented."},{"value":"364","claim":"Number of economists who signed the March 1981 letter to The Times criticising UK policy.","basis":"Widely documented."},{"value":"above 10%","claim":"US inflation when Volcker took office in August 1979.","basis":"Consistent with catalogue us-cpi-infl annual 1979 value of 11.3%."},{"value":"2016","claim":"Year India adopted a statutory inflation target.","basis":"Amended RBI Act, 2016; matches case MAC-003."}]},{"id":"plaza-1985","title":"The Plaza Accord and the falling dollar","years":"1985–1987","start":"1985-02","end":"1987-12","region":"United States, Japan and West Germany (G5)","kind":"policy","standfirst":"By early 1985 the US dollar had risen so far that American manufacturers were losing markets and Congress was considering protectionist laws. Five governments then tried something unusual: to talk and trade a major currency down together, and later to hold it steady.","question":"Can governments deliberately move a floating exchange rate, and what happens to trade and asset prices when they do?","before":{"p":"Between 1980 and early 1985 the dollar rose strongly against other major currencies. The Federal Reserve had tightened sharply to fight inflation, while tax cuts and higher defence spending widened the US budget deficit. The result was high real interest rates that drew capital into dollar assets. The dollar bought 1.82 Deutsche Marks on average in 1980 and 2.94 in 1985. US exports became expensive, imports cheap, and the current account moved into a large deficit. Industries facing import competition pressed Congress for protection.","facts":[{"t":"The Deutsche Mark per dollar rate averaged 1.82 in 1980 and 2.94 in 1985 (Federal Reserve data).","status":"fact"},{"t":"The dollar reached its peak in February 1985 and had already begun to fall before the Plaza meeting.","status":"fact"},{"t":"US 10-year Treasury yields averaged 12.44% in 1984, far above inflation of 4.3%, so real interest rates were high.","status":"fact"},{"t":"In early 1985 James Baker became Treasury Secretary and the administration moved away from its earlier hands-off stance on the exchange rate.","status":"fact"}]},"trigger":{"p":"On 22 September 1985 the finance ministers and central bank governors of the G5 (the United States, Japan, West Germany, France and the United Kingdom) met at the Plaza Hotel in New York. Their statement said that a further orderly appreciation of the main non-dollar currencies was desirable and that they stood ready to cooperate to achieve it. Central banks then sold dollars on the foreign exchange market.","status":"fact"},"timeline":[{"d":"1985-02","t":"The dollar peaks","detail":"After almost five years of appreciation, the dollar reaches its highest level against major currencies and begins to ease, partly as US interest rates come down from their earlier peaks.","status":"fact"},{"d":"1985-09-22","t":"Plaza Accord announced","detail":"G5 ministers and central bankers meet in New York and announce that non-dollar currencies should appreciate in an orderly way. The announcement is backed by coordinated sales of dollars.","status":"fact"},{"d":"1985-10","t":"Coordinated intervention continues","detail":"Central banks continue selling dollars in the weeks after the meeting. The dollar falls quickly, especially against the yen and the Deutsche Mark.","status":"fact"},{"d":"1986","t":"Yen strengthens sharply","detail":"The yen averages 168.5 per dollar in 1986, against 238.47 in 1985. Japanese exporters face falling yen revenues and Japan’s economy slows in what became known as the ‘endaka’ (strong-yen) recession.","status":"fact"},{"d":"1986","t":"Bank of Japan cuts rates","detail":"The Bank of Japan begins a series of discount-rate cuts to support the economy against the strong yen, reaching 2.5% in February 1987, a low level for the time.","status":"fact"},{"d":"1987-02-22","t":"Louvre Accord","detail":"Finance ministers of the G5 and Canada meet in Paris and agree that currencies are now broadly consistent with fundamentals and that they will cooperate to stabilise them around current levels.","status":"fact"},{"d":"1987-08","t":"Greenspan succeeds Volcker at the Fed","detail":"Alan Greenspan becomes chair of the Federal Reserve. Concerns about inflation and the dollar push US interest rates up during 1987.","status":"fact"},{"d":"1987-10-19","t":"Black Monday stock market crash","detail":"US share prices fall by more than a fifth in a single day. Public disagreement between the United States and West Germany over interest rates and the dollar is one of several explanations offered.","status":"fact"},{"d":"1988","t":"US trade deficit starts to narrow","detail":"With a lag of two to three years after the dollar’s peak, US export volumes grow strongly and the current account deficit begins to shrink, although it remains large.","status":"fact"}],"actors":[{"who":"US Treasury under James Baker","role":"Led the push for coordinated action to lower the dollar, partly to head off protectionist bills in Congress, and later sought stability at the Louvre."},{"who":"Federal Reserve (Volcker, then Greenspan)","role":"Took part in intervention and eased policy in 1985–86; US interest rate decisions mattered at least as much as intervention for the dollar’s path."},{"who":"Japan’s Ministry of Finance and the Bank of Japan","role":"Agreed to yen appreciation at the Plaza (the finance minister was Noboru Takeshita), then cut interest rates to cushion exporters, a decision later linked to Japan’s asset bubble."},{"who":"West German government and the Bundesbank","role":"Supported a weaker dollar but resisted pressure to stimulate demand, and raised interest rates in 1987, causing public friction with the US Treasury."},{"who":"US Congress","role":"Considered protectionist trade bills in 1985 aimed especially at Japan; this pressure was a main reason the administration acted, and it later passed the 1988 Omnibus Trade and Competitiveness Act."}],"changed":"The dollar fell a long way: the yen per dollar rate dropped from 238.47 in 1985 to 128.14 in 1988, and the mark rate from 2.94 to 1.76. US exporters regained price competitiveness and protectionist pressure eased. Japanese firms faced a sharp loss of competitiveness and moved production abroad, especially to Southeast Asia. In Japan, low interest rates and abundant credit fed a rapid rise in share and land prices in the late 1980s. The episode became the leading example of deliberate international exchange-rate coordination.","predict":{"q":"Five governments announce that the dollar should fall, and their central banks sell dollars. Before looking at the mechanism, what is the most likely effect on the US trade deficit within the first year?","options":["It narrows quickly as US exports become cheaper","It may widen at first, then narrow over the following years","It is unaffected because exchange rates do not influence trade"],"answer":1,"explain":"Trade volumes respond slowly because contracts and buying habits take time to change. At first, the US pays more dollars for the same imports, so the deficit in value terms can widen. As volumes adjust, exports rise and imports fall. This pattern is the J-curve, and the US deficit did not start to narrow until 1987–88."},"mechanism":["Large US budget deficits and tight money → high US real interest rates → capital flows into dollar assets → demand for dollars rises → dollar appreciates (1980–85)","Strong dollar → US exports dearer abroad and imports cheaper at home → net exports fall → current account deficit widens and protectionist pressure grows","Plaza announcement and central-bank sales of dollars → supply of dollars on the foreign exchange market rises and traders expect official resistance to a strong dollar → dollar depreciates","Falling US interest rates in 1985–86 → smaller return on dollar assets → weaker capital inflow → demand for dollars falls → further depreciation","Dollar depreciation → US goods become cheaper abroad, but volumes respond with a lag → J-curve: the deficit narrows only from 1987–88 if the Marshall–Lerner condition holds","Yen appreciation → Japanese net exports fall → Japanese AD shifts left → Bank of Japan cuts interest rates → credit expands → share and land prices rise strongly","Louvre target ranges + differing national interest-rate policies → markets test the commitment → tension over the dollar adds to financial instability in October 1987"],"charts":[{"series":"fx-japan","from":"1980","to":"1990","title":"Yen per US dollar, 1980–1990","look":"The rate is high and fairly flat to 1985, then falls steeply after the Plaza Accord. A falling line means a weaker dollar and a stronger yen. Note how the fall slows after the Louvre Accord.","marks":[{"at":"1985-09","label":"Plaza Accord"},{"at":"1987-02","label":"Louvre Accord"}]},{"series":"fx-germany","from":"1980","to":"1990","title":"Deutsche Marks per US dollar, 1980–1990","look":"The dollar rises from 1.82 marks in 1980 to 2.94 in 1985, then loses most of that rise by 1987. Compare the turning point with the February 1985 peak.","marks":[{"at":"1985-02","label":"Dollar peak"},{"at":"1985-09","label":"Plaza Accord"}]},{"series":"sp500","from":"1987-01","to":"1987-12","title":"S&P 500 index, monthly, 1987","look":"Share prices rise to 329.4 in August 1987, then fall to 245.0 in November after the October crash. Ask how far currency tensions, rather than other factors, explain the fall.","marks":[{"at":"1987-10","label":"Black Monday"}]},{"series":"us10y","from":"1980","to":"1990","title":"US 10-year Treasury yield, 1980–1990","look":"Yields fall from 12.44% in 1984 to 7.68% in 1986, reducing the return on dollar assets. This helps explain why the dollar was already falling before the Plaza meeting.","marks":[{"at":"1985-09","label":"Plaza Accord"}]}],"diagrams":[{"dg":"fx","how":"Draw the market for dollars in terms of yen. Show supply of dollars shifting right as central banks sell dollars, and demand shifting left as US interest rates fall and expectations change. The equilibrium yen price of a dollar falls: the dollar depreciates."},{"dg":"adas","how":"For Japan, shift AD left as yen appreciation reduces net exports, lowering real output. Then show the Bank of Japan’s rate cuts shifting AD back to the right, and discuss why easy credit may have flowed into asset prices instead."}],"policy":[{"who":"G5 finance ministers and central bank governors","when":"1985-09","what":"Announced at the Plaza Hotel that an orderly appreciation of non-dollar currencies was desirable, and backed the statement with coordinated sales of dollars on the foreign exchange market.","status":"fact"},{"who":"Federal Reserve","when":"1986","what":"Lowered its discount rate several times during 1986 as inflation fell, reducing US interest rates and the return on dollar assets, which reinforced the dollar’s depreciation.","status":"fact"},{"who":"Bank of Japan","when":"1986","what":"Cut its discount rate in a series of steps from January 1986 to 2.5% by February 1987, aiming to offset the contractionary effect of the strong yen on the Japanese economy.","status":"fact"},{"who":"G5 and Canada","when":"1987-02","what":"Agreed at the Louvre to stabilise exchange rates near prevailing levels, with surplus countries to support domestic demand and the United States to reduce its budget deficit.","status":"fact"},{"who":"Federal Reserve (Greenspan)","when":"1987-10","what":"Announced the day after the crash that it stood ready to provide liquidity to support the financial system, and lowered short-term rates, helping to prevent a wider financial crisis.","status":"fact"},{"who":"US Congress","when":"1988","what":"Passed the Omnibus Trade and Competitiveness Act, which strengthened the administration’s powers to act against trading partners judged to be using unfair trade practices, reflecting continuing concern about the deficit.","status":"fact"}],"stakeholders":[{"who":"US manufacturers and farmers selling abroad","effect":"Gained as the dollar fell and their goods became cheaper in foreign markets, though export volumes recovered only gradually after 1986."},{"who":"Japanese exporters","effect":"Saw yen revenues from dollar sales fall sharply; many cut costs and moved production to the United States and Southeast Asia."},{"who":"US consumers","effect":"Paid more for imported goods such as cars and electronics as the dollar weakened, losing part of the purchasing power the strong dollar had given them."},{"who":"Foreign holders of dollar assets","effect":"Lost in their own currencies as the dollar fell; Japanese investors in US bonds and property suffered large currency losses."},{"who":"Southeast Asian economies","effect":"Received large inflows of Japanese direct investment as firms relocated production, supporting rapid export-led growth in the late 1980s and early 1990s."},{"who":"Japanese households and asset owners","effect":"Benefited from cheaper imports and rising share and land values in the late 1980s, then faced large losses when the bubble burst after 1990."}],"short":"In the short run the dollar fell quickly against the yen and the Deutsche Mark, more quickly than many participants expected. Because trade volumes adjust slowly, the US trade deficit did not shrink at first. Japan slipped into a strong-yen slowdown, and the Bank of Japan cut interest rates. By early 1987 governments were more worried about the dollar falling too far, which led to the Louvre Accord and to tension that formed part of the background to the October 1987 crash.","long":"Over the longer run US export volumes recovered and the current account deficit narrowed from 1988, but the savings–investment imbalance behind it did not disappear. Japan’s low interest rates and credit expansion fed an asset bubble that burst after 1990, followed by a long period of slow growth. Japanese direct investment reshaped manufacturing in Southeast Asia. The episode also left governments more cautious about formal exchange-rate targets, as the Louvre ranges proved hard to defend.","transmission":"The accord itself was an act of transmission: five governments coordinated policy across borders. Exchange-rate changes then spread through trade, as Japanese and German exporters lost competitiveness, and through investment, as Japanese firms moved production to the United States and Southeast Asia. Economies whose currencies were closely linked to the dollar, including several in East Asia, gained competitiveness against Japan. Financial markets carried the tensions too: the October 1987 crash spread from New York to markets worldwide within days.","winners":[{"t":"US exporting industries regained price competitiveness as the dollar fell.","status":"fact"},{"t":"Southeast Asian economies gained from Japanese direct investment in new factories.","status":"fact"},{"t":"Holders of Japanese shares and land gained during the late-1980s boom, at least until 1990.","status":"inference"}],"losers":[{"t":"Japanese exporters lost competitiveness and profits as the yen strengthened.","status":"fact"},{"t":"Japanese investors holding dollar assets suffered large currency losses.","status":"fact"},{"t":"US consumers paid higher prices for imported goods.","status":"inference"}],"unintended":[{"t":"Easy monetary policy in Japan after the strong-yen shock contributed to a share and land price bubble that burst in the early 1990s.","status":"controversy"},{"t":"The Louvre commitment to stabilise currencies, combined with conflicting national interest-rate policies, created tension that some link to the October 1987 crash.","status":"controversy"},{"t":"Relocation of Japanese manufacturing to Southeast Asia helped build the export-led boom in that region, which later formed part of the background to the 1997 crisis.","status":"inference"}],"interpretations":[{"view":"Coordination worked","p":"Supporters argue that the Plaza announcement changed market expectations: by showing that the major governments wanted a weaker dollar, it signalled that future policy, including interest rates, would push in that direction. On this view, intervention mattered mainly as a signal rather than through the amount of dollars sold.","status":"interpretation"},{"view":"Fundamentals did the work","p":"Sceptics, including Martin Feldstein, argue that the dollar was already falling from February 1985 because US interest rates were falling and the earlier rise had overshot. On this view sterilised intervention, which leaves the money supply unchanged, has limited power to move a large currency market for long.","status":"interpretation"},{"view":"The Japanese bubble view","p":"Some economists, especially in Japan, argue that commitments to support the dollar and expand domestic demand kept Japanese interest rates too low for too long, feeding the late-1980s bubble. Others stress domestic financial deregulation, aggressive bank lending against land and weak supervision instead.","status":"controversy"},{"view":"Twin-deficits reading","p":"A current account deficit reflects national saving below investment. On this reading, a weaker dollar could only partly close the US deficit while the budget deficit kept national saving low; changing the exchange rate was treating a symptom rather than the cause.","status":"interpretation"}],"explain":["Supply and demand in the foreign exchange market explain how intervention and lower US interest rates reduced the value of the dollar.","The J-curve and the Marshall–Lerner condition explain why the US trade deficit narrowed only after a delay of two to three years.","The AD–AS model shows how yen appreciation reduced Japanese net exports and why the Bank of Japan responded with lower interest rates."],"miss":["Simple exchange-rate models give little role to announcements and expectations, which many observers think mattered more than the amount of dollars sold.","They treat the current account as driven by the exchange rate, overlooking the role of national saving and the US budget deficit.","They say little about how easy money can flow into asset prices rather than goods prices, as appears to have happened in Japan."],"differently":[{"t":"Some argue the United States should have reduced its budget deficit earlier, which would have lowered real interest rates and the dollar without relying on intervention, and addressed the low national saving behind the trade deficit.","status":"interpretation"},{"t":"Some Japanese economists argue the Bank of Japan should have raised interest rates sooner in 1987–88, despite international pressure to support demand, to restrain credit growth, share prices and land prices.","status":"controversy"},{"t":"Others argue the Louvre Accord should not have set implicit target ranges at all, since markets could test them and conflicts between national interest-rate policies were likely to undermine them.","status":"interpretation"}],"whatif":{"q":"Suppose the G5 had not met in September 1985 and no coordinated intervention had taken place. What is the most likely path of the dollar?","options":["It would have continued to fall, but probably more slowly and with more uncertainty","It would have kept rising at its 1980–85 pace","It would have stayed exactly at its September 1985 level"],"best":0,"explain":"The dollar had been falling since February 1985 as US interest rates declined, so a continued fall seems likely even without the accord. What the accord may have changed is the speed and the confidence of the move, and the political pressure for trade restrictions. Economists still disagree about how much of the fall the accord itself caused."},"compare":[{"id":"bretton-woods-1971","similar":"Both involve the United States seeking a weaker dollar, with major trading partners asked to accept stronger currencies in order to reduce the US external deficit.","different":"In 1971 the issue was the collapse of a fixed system; in 1985 currencies were already floating and governments tried to steer a market rate by intervention and signals.","dominant":"In 1971 the end of gold convertibility dominates. In 1985 market expectations and interest-rate differentials, shaped by coordinated signals, dominate."},{"id":"asia-1997","similar":"Both show large exchange-rate movements reshaping trade and investment in East Asia, and both involve currencies under pressure from shifting international capital flows and changing expectations.","different":"The Plaza fall was planned by governments and broadly orderly; the 1997 depreciations were forced by capital flight from economies defending pegs with limited foreign reserves.","dominant":"In 1985 deliberate policy coordination and falling US interest rates dominate. In 1997 sudden capital outflows and weaknesses in domestic banking systems dominate."},{"id":"stagflation-1970s","similar":"Both are shaped by US monetary policy: the high real interest rates of the Volcker disinflation helped push the dollar up in the years before 1985.","different":"The 1970s problem was high domestic inflation alongside rising unemployment; the Plaza problem was an over-strong currency, a widening trade deficit and growing protectionist pressure.","dominant":"Rising inflation expectations and monetary accommodation dominate the 1970s. By contrast, international capital flows and exchange-rate expectations dominate the Plaza episode."}],"ib":{"subs":["4.5","4.6","3.5","4.3"],"kc":["Interdependence","Intervention","Change"],"note":"The event supports analysis of floating exchange rates, intervention and the current account; the Marshall–Lerner condition and the J-curve are HL only (guide PDF p. 56), which makes the delayed US trade response a useful HL evaluation example."},"cambridge":{"topics":["exchange rate systems","balance of payments","international policy coordination","protectionism"],"note":"Useful for showing how exchange rates are influenced by interest rates and intervention, and how they affect trade over time."},"university":{"fields":["international finance","open-economy macroeconomics","economic history"],"note":"A university course would examine the portfolio-balance and signalling channels of sterilised intervention, exchange-rate overshooting, and the saving–investment identity behind current account balances."},"civil":{"themes":["external sector","exchange rate management","international economic cooperation"],"note":"The episode shows how major-currency movements affect emerging economies; the Japanese investment that moved into Southeast Asia after 1985 is a useful comparison for debates on attracting manufacturing FDI to India."},"economists":["friedman"],"causal":["currency","ratehike"],"concepts":["Exchange rate","Floating exchange rate","Managed exchange rate","Depreciation","Appreciation","Current account","J-curve","Marshall-Lerner condition","Protectionism","Foreign direct investment","Budget deficit"],"cases":["GLO-026"],"policies":["Coordinated foreign exchange intervention","Exchange-rate target ranges (Louvre Accord)","Discount-rate cuts (Federal Reserve, Bank of Japan)","Lender-of-last-resort liquidity support","Trade legislation (Omnibus Trade and Competitiveness Act)"],"questions":[{"q":"Explain how the sale of dollars by central banks could cause the dollar to depreciate against the yen.","kind":"explain"},{"q":"Analyse why the US trade deficit continued to widen for a time after the dollar began to fall in 1985.","kind":"analyse"},{"q":"Evaluate the view that the Plaza Accord, rather than market forces, caused the fall in the dollar after 1985.","kind":"evaluate"},{"q":"Using the yen per dollar data for 1984–1988, calculate the percentage change in the exchange rate between 1985 and 1987 and state whether the dollar appreciated or depreciated.","kind":"data"},{"q":"Compare the Plaza Accord of 1985 with the end of the Bretton Woods system in 1971 as attempts to change the value of the dollar.","kind":"compare"}],"retrieval":[{"q":"Which five countries made up the G5 at the Plaza meeting?","a":"The United States, Japan, West Germany, France and the United Kingdom."},{"q":"What did the Louvre Accord of February 1987 aim to do?","a":"Stabilise exchange rates around their then current levels after the dollar’s large fall."},{"q":"What is the J-curve?","a":"The pattern in which a depreciation first worsens the trade balance, then improves it as trade volumes adjust."},{"q":"What happened to the yen per dollar rate between 1985 and 1987?","a":"It fell from 238.47 to 144.62, meaning the dollar depreciated and the yen appreciated."},{"q":"Why had the dollar risen so strongly before 1985?","a":"High US real interest rates, linked to tight money and large budget deficits, attracted capital into dollar assets."}],"reflection":"If a country’s trade deficit reflects low national saving, how much can any exchange-rate agreement achieve on its own?","reading":[{"t":"Yoichi Funabashi, Managing the Dollar: From the Plaza to the Louvre, 1988","note":"A detailed account of the negotiations behind both accords, based on interviews with participants."},{"t":"Paul Volcker and Toyoo Gyohten, Changing Fortunes, 1992","note":"An American and a Japanese official describe the period from both sides, including the Plaza and Louvre meetings."},{"t":"Martin Feldstein (ed.), American Economic Policy in the 1980s, 1994","note":"Includes discussion of exchange-rate policy and the debate about how far intervention moved the dollar."}],"numbers":[{"value":"2.5%","claim":"The Bank of Japan’s discount rate reached 2.5% in February 1987","basis":"Bank of Japan official discount rate history"},{"value":"more than a fifth","claim":"US share prices fell by more than a fifth on 19 October 1987","basis":"The Dow Jones Industrial Average fell about 22.6% that day"},{"value":"G5 (five countries)","claim":"The Plaza meeting involved the United States, Japan, West Germany, France and the United Kingdom","basis":"Plaza Accord communiqué, 22 September 1985"},{"value":"two to three years","claim":"The lag between the dollar’s peak (February 1985) and the start of the narrowing of the US current account deficit (1988)","basis":"US balance-of-payments data; widely documented"}]},{"id":"india-1991","title":"India’s 1991 crisis and the turn to reform","years":"1990–1994","start":"1990-08","end":"1994-08","region":"India","kind":"crisis","standfirst":"In mid-1991 India’s foreign exchange reserves had fallen so low that the country was close to defaulting on its external payments, and its gold was flown to London as security for a loan. The emergency became the starting point for the most far-reaching change in Indian economic policy since independence.","question":"How did a distant war and years of fiscal deficits push India to the edge of default, and why did the response go beyond rescue to a change of economic model?","before":{"p":"From the 1950s India followed a planned, state-led strategy. Firms needed government licences to set up or expand capacity, many key industries were reserved for the public sector, and high tariffs and import licensing protected domestic producers: an import-substitution approach. Growth from 1950 to 1980 averaged about 3.5% a year. In the 1980s growth quickened as some controls were relaxed, but government spending ran well ahead of revenue and the gap was increasingly financed by borrowing, including from abroad. By 1990–91 the current account deficit was about 3% of GDP, short-term external debt was rising, and inflation had reached 9.0% in 1990.","facts":[{"t":"The Industries (Development and Regulation) Act of 1951 required firms to obtain licences to establish or substantially expand industrial capacity.","status":"fact"},{"t":"The Industrial Policy Resolution of 1956 reserved a list of basic and strategic industries for the state sector.","status":"fact"},{"t":"India had already borrowed from the IMF under an extended arrangement agreed in 1981, after the second oil shock.","status":"fact"},{"t":"The rupee was managed against a basket of currencies and depreciated gradually in the late 1980s, from 12.34 per dollar in 1985 to 17.5 in 1990 (annual averages).","status":"fact"},{"t":"The economist Raj Krishna described India’s long-run growth of about 3.5% a year as the ‘Hindu rate of growth’, a phrase later widely used and criticised.","status":"fact"}]},"trigger":{"p":"Iraq invaded Kuwait on 2 August 1990. Oil prices rose sharply, and Brent crude averaged $23.68 a barrel in 1990 against $18.25 in 1989, raising India’s import bill. Remittances from Indian workers in the Gulf fell, many workers were evacuated from Kuwait, and exports to the region were lost. Political instability at home and downgrades by credit-rating agencies then cut India’s access to commercial borrowing, and non-resident Indians withdrew deposits.","status":"fact"},"timeline":[{"d":"1990-08-02","t":"Iraq invades Kuwait","detail":"The Gulf crisis raises oil prices, cuts remittances from Indian workers in the region and disrupts exports. India’s current account, already in deficit, deteriorates quickly.","status":"fact"},{"d":"1990-11","t":"Chandra Shekhar forms a minority government","detail":"V. P. Singh’s government falls. The new minority government, dependent on outside support, cannot present a full budget for 1991–92 and passes only an interim budget in March 1991.","status":"fact"},{"d":"1991-01","t":"India draws on IMF credit","detail":"India borrows from the IMF, including under the Compensatory and Contingency Financing Facility, which supported countries hit by temporary shocks such as higher oil import costs.","status":"fact"},{"d":"1991-05","t":"Gold sold with a buy-back option","detail":"The government authorises the State Bank of India to sell about 20 tonnes of gold, previously confiscated from smugglers, with an option to repurchase it, raising foreign currency for urgent payments.","status":"fact"},{"d":"1991-06-21","t":"Narasimha Rao government takes office","detail":"After an election campaign interrupted by the assassination of Rajiv Gandhi on 21 May, P. V. Narasimha Rao forms a Congress government and appoints Manmohan Singh as finance minister.","status":"fact"},{"d":"1991-07","t":"RBI pledges gold abroad","detail":"The Reserve Bank of India pledges about 47 tonnes of gold with the Bank of England and the Bank of Japan, shipping it to London, to raise about $400 million in loans.","status":"fact"},{"d":"1991-07-01","t":"Rupee devalued in two steps","detail":"The RBI lowers the rupee’s official value on 1 July and again on 3 July 1991, by about 18–19% in total against major currencies, to restore export competitiveness and confidence.","status":"fact"},{"d":"1991-07-04","t":"Trade policy reform begins","detail":"The Ministry of Commerce abolishes cash subsidies for exports and replaces import replenishment licences with tradable Exim scrips, linking import rights to export earnings as a step towards freer trade.","status":"fact"},{"d":"1991-07-24","t":"Budget and New Industrial Policy","detail":"On the same day the government presents a budget aimed at cutting the fiscal deficit and announces a New Industrial Policy that abolishes licensing for most industries and opens the door to foreign investment.","status":"fact"},{"d":"1991-10","t":"IMF stand-by arrangement approved","detail":"The IMF approves a stand-by arrangement supporting India’s stabilisation programme, with conditions on fiscal adjustment and structural reform. World Bank adjustment lending follows.","status":"fact"},{"d":"1992-03","t":"Dual exchange rate introduced","detail":"Under the Liberalised Exchange Rate Management System, exporters convert most foreign earnings at a market-determined rate and the rest at the official rate, a transitional step towards a market rate.","status":"fact"},{"d":"1993-03","t":"Unified market-determined rupee","detail":"The two rates are merged into a single, market-determined exchange rate. The RBI continues to intervene to limit volatility. In August 1994 the rupee becomes convertible on the current account.","status":"fact"}],"actors":[{"who":"Government of India (Prime Minister P. V. Narasimha Rao, Finance Minister Manmohan Singh)","role":"Took office in June 1991 at the height of the crisis, devalued, cut the fiscal deficit and launched industrial, trade and financial reforms while managing a minority position in Parliament."},{"who":"Reserve Bank of India (Governor S. Venkitaramanan)","role":"Managed the dwindling reserves, arranged the gold pledge, carried out the July devaluation and later oversaw the move to a market-determined exchange rate."},{"who":"Chandra Shekhar government (1990–91)","role":"Held office as the crisis deepened; drew on IMF credit and authorised the first gold sale, but lacked the parliamentary strength to pass a full budget."},{"who":"International Monetary Fund and World Bank","role":"The IMF provided emergency credit in January 1991 and a stand-by arrangement in October 1991, and the World Bank followed with adjustment lending, with conditions that supported fiscal adjustment and structural reform."},{"who":"Non-resident Indians and Gulf workers","role":"Their remittances and deposits had helped finance the deficit. The Gulf war cut remittances, and withdrawals of deposits deepened the reserve loss."},{"who":"Credit-rating agencies and international lenders","role":"Downgraded India and stopped rolling over commercial credit, turning a current account problem into a financing crisis."}],"changed":"India moved from a licence-based, inward-looking economy towards a more open, market-oriented one. Industrial licensing was largely abolished, tariffs were cut in stages through the 1990s, foreign direct and portfolio investment were permitted, and the rupee became market-determined in 1993 and convertible on the current account in 1994. In the short run growth slowed and inflation reached 13.9% in 1991. Over time reserves were rebuilt and external financing shifted away from short-term borrowing. Above all, the crisis made politically difficult reforms possible.","predict":{"q":"India keeps the rupee at an officially managed value. The oil import bill jumps, Gulf remittances fall and foreign lenders stop rolling over loans. If the RBI holds the rupee at its existing value, what happens to its foreign exchange reserves?","options":["They fall, because the RBI must sell foreign currency to meet the excess demand for it","They rise, because a fixed rate attracts foreign capital","They stay the same, because the exchange rate is fixed"],"answer":0,"explain":"Demand for foreign currency rises (for oil) while its supply falls (fewer remittances and loans). At the managed rate there is excess demand for foreign currency, so the RBI must sell from its reserves to hold the rate. Reserves fall until the rate is changed, the deficit is financed elsewhere, or demand is reduced."},"mechanism":["Persistent fiscal deficits in the 1980s → national saving falls short of investment → current account deficits financed by external borrowing → foreign debt, including short-term debt, rises","Gulf war raises oil prices → demand for oil imports is price-inelastic in the short run → import spending rises → current account deficit widens","Remittances from Gulf workers and exports to Iraq and Kuwait fall → current transfers and export receipts fall → current account deteriorates further","Rating downgrades and political uncertainty → lenders stop rolling over credit and non-resident deposits are withdrawn → financial account inflows reverse → the RBI sells reserves to defend the rupee → reserves fall to a few weeks of imports","Gold pledged and IMF credit obtained → emergency foreign currency covers urgent payments → default is avoided and time is bought for adjustment","Devaluation → Indian exports cheaper abroad, imports dearer at home → expenditure switching; the current account improves with a lag if the Marshall–Lerner condition holds, while dearer imports add to inflation (cost-push)","Fiscal tightening and import compression → AD shifts left (expenditure reducing) → growth slows in 1991–92 and the current account deficit narrows","Delicensing, tariff cuts and openness to FDI → more competition, investment and access to technology → productivity rises → LRAS shifts right over a period of years"],"charts":[{"series":"fx-india","from":"1985","to":"1996","title":"Rupees per US dollar, 1985–1996","look":"A rising line means a weaker rupee. Note the gradual slide to 1990, the step in July 1991, and the further move to 31.26 in 1993 as the rate became market-determined.","marks":[{"at":"1991-07","label":"Two-step devaluation"},{"at":"1993-03","label":"Market-determined rate"}]},{"series":"brent-m","from":"1987","to":"1993","title":"Brent crude oil price, 1987–1993","look":"The oil price spikes after Iraq invades Kuwait in August 1990 and falls back during 1991. The 1990 average of $23.68 compares with $18.25 in 1989.","marks":[{"at":"1990-08","label":"Iraq invades Kuwait"}]},{"panel":"infl","entities":["IND"],"from":"1985","to":"1997","title":"Consumer-price inflation in India, 1985–1997","look":"Inflation rises from 9.0% in 1990 to 13.9% in 1991, reflecting the oil shock, devaluation and earlier deficits, then falls to 6.3% in 1993 as stabilisation takes hold.","marks":[{"at":"1991","label":"Crisis year"}]},{"panel":"gdp","entities":["IND"],"from":"1985","to":"2005","title":"India’s GDP in current US dollars, 1985–2005","look":"GDP measured in dollars falls from $321.0 billion in 1990 to $270.1 billion in 1991, mainly because each rupee is worth fewer dollars after devaluation. Then it rises to $468.4 billion by 2000.","marks":[{"at":"1991","label":"Devaluation year"}]}],"diagrams":[{"dg":"fx","how":"Draw the market for foreign currency (dollars) priced in rupees. Shift demand right (dearer oil) and supply left (lower remittances, capital outflow). At the managed rate, show excess demand met by RBI reserve sales. Then show devaluation as a higher official rupee price of a dollar."},{"dg":"adas","how":"In the short run, shift AD left for fiscal tightening and import compression, and SRAS left for dearer imported inputs after devaluation: output falls and the price level rises. For the long run, shift LRAS right to show the effect of delicensing, trade opening and investment."}],"policy":[{"who":"Reserve Bank of India","when":"1991-07","what":"Pledged about 47 tonnes of gold with the Bank of England and the Bank of Japan to raise emergency loans, and devalued the rupee in two steps on 1 and 3 July.","status":"fact"},{"who":"Government of India, Ministry of Commerce","when":"1991-07","what":"Abolished cash compensatory support for exports and introduced tradable Exim scrips, the first of a series of measures that reduced import licensing and moved towards tariffs as the main form of protection.","status":"fact"},{"who":"Government of India, Ministry of Industry","when":"1991-07","what":"Announced the New Industrial Policy: industrial licensing abolished except for a short list of industries, the list reserved for the public sector cut sharply, and automatic approval for foreign equity up to 51% in priority industries.","status":"fact"},{"who":"Government of India, Ministry of Finance","when":"1991-07","what":"Presented a budget aimed at reducing the fiscal deficit through spending restraint and revenue measures, and began cutting very high import duties, a process continued in later budgets.","status":"fact"},{"who":"Government of India and Reserve Bank of India","when":"1991-08","what":"Appointed the Narasimham Committee on the financial system; its November 1991 report led to lower pre-emption of bank funds, interest-rate deregulation, prudential norms and entry of new private banks.","status":"fact"},{"who":"Reserve Bank of India and Government of India","when":"1992-03","what":"Introduced a dual exchange rate, unified it into a market-determined rate in March 1993, and made the rupee convertible on the current account in August 1994.","status":"fact"}],"stakeholders":[{"who":"Exporters, including textiles, engineering and software services","effect":"Gained from devaluation and easier access to imported inputs and technology; the later growth of IT services exports built on this more open environment."},{"who":"Firms that had relied on licences and high tariffs","effect":"Faced new domestic entrants and, as tariffs fell, import competition; some expanded and modernised, while others lost market share or closed."},{"who":"Households and consumers","effect":"Faced inflation of 13.9% in 1991 and slower income growth; later gained a wider choice of goods and lower relative prices for many manufactured products."},{"who":"Gulf migrant workers and their families","effect":"Lost jobs and earnings when the Gulf war began; states such as Kerala, which relied heavily on remittances, were especially affected."},{"who":"Public-sector enterprises and their workers","effect":"Lost protected positions as reserved sectors were opened to private firms; partial sale of government shareholdings began, though large-scale privatisation remained limited."}],"short":"In the short run the crisis and its remedy were painful. Inflation rose to 13.9% in 1991, real growth slowed sharply in 1991–92, and imports were compressed to save foreign currency. Measured in US dollars, India’s GDP fell from $321.0 billion in 1990 to $270.1 billion in 1991, mainly because the rupee was worth less. Yet emergency borrowing, devaluation and fiscal tightening avoided a default, and reserves began to recover within about a year.","long":"Over the longer run growth rose above its pre-1980 pace, and GDP in current dollars grew from $270.1 billion in 1991 to $468.4 billion in 2000 and $1,675.6 billion in 2010. Services exports, especially IT, expanded rapidly, foreign investment increased and poverty fell substantially. Reform was gradual: labour law, land, agriculture and privatisation moved slowly. Critics point to limited growth in formal manufacturing jobs and rising inequality; supporters argue the reforms made faster growth sustainable.","transmission":"This crisis travelled into India rather than out of it. The Gulf war reached India through three channels: a higher oil import bill, lost remittances and lost exports to the region. Global lenders then amplified the shock by withdrawing credit. Because India’s financial links with the rest of the world were limited, the crisis did not spread to other economies. The same limited capital-account openness and lower reliance on short-term debt are often cited to explain why India was little affected in 1997.","winners":[{"t":"Export-oriented firms gained from a more competitive rupee and freer access to imported inputs.","status":"fact"},{"t":"Foreign investors gained access to a large market from which they had largely been excluded.","status":"fact"},{"t":"Consumers gained over time from wider choice and lower relative prices of many manufactured goods.","status":"inference"}],"losers":[{"t":"Households faced high inflation in 1991–92, which hit those without indexed incomes hardest.","status":"fact"},{"t":"Gulf migrant workers lost jobs and earnings when the war began.","status":"fact"},{"t":"Firms that had relied on licensing and protection faced new competition, and some lost market share or closed.","status":"inference"}],"unintended":[{"t":"Devaluation raised the rupee cost of servicing foreign-currency debt and of imported oil, adding to inflation in 1991–92.","status":"inference"},{"t":"Newly liberalised financial markets outpaced regulation: the 1992 securities scam exposed weaknesses in banks’ and brokers’ controls and prompted stronger oversight.","status":"fact"},{"t":"The experience of near-default appears to have shaped a lasting preference among Indian policymakers for holding large foreign exchange reserves as insurance.","status":"interpretation"}],"interpretations":[{"view":"Fiscal origins (Vijay Joshi and I. M. D. Little, among others)","p":"The crisis was rooted in the large fiscal deficits of the 1980s, which spilled into current account deficits and rising foreign debt. On this reading the Gulf war was the proximate trigger of a crisis that underlying policies had made likely.","status":"interpretation"},{"view":"Growth began earlier (Dani Rodrik and Arvind Subramanian)","p":"India’s growth acceleration began around 1980, before the 1991 reforms, helped by a more pro-business stance by government. The 1991 reforms sustained and broadened growth rather than starting it. Others reply that 1980s growth rested on borrowing that could not continue.","status":"controversy"},{"view":"Liberalisation was decisive (Jagdish Bhagwati, Arvind Panagariya)","p":"Decades of licensing, protection and public-sector reservation held back productivity and exports. The 1991 reforms removed many of these constraints and made faster growth sustainable; earlier and deeper liberalisation, on this view, would have brought the gains sooner and to more people.","status":"interpretation"},{"view":"Social opportunity (Jean Drèze and Amartya Sen)","p":"Market reforms were useful but insufficient. Without stronger public action on basic education, health and nutrition, many people lacked the capabilities to take up new opportunities in an open economy, so the gains from growth were unevenly shared across regions and social groups.","status":"interpretation"}],"explain":["Balance-of-payments accounting shows how a wider current account deficit plus a reversal of financial inflows must drain official reserves under a managed exchange rate.","Foreign exchange market analysis explains why devaluation was needed once reserves could no longer hold the rupee at its official value.","Supply-side analysis explains how removing licensing and lowering tariffs could raise productivity and shift LRAS to the right over time."],"miss":["Standard models say little about confidence and politics: the crisis accelerated when ratings fell and governments were unstable, not only when the current account worsened.","They usually treat reform as a policy choice, whereas in 1991 the crisis itself created the political room for changes that had been resisted for years.","They do not capture the distributional and regional effects of reform, such as who gained jobs and who lost protection."],"differently":[{"t":"Many economists argue that fiscal consolidation in the late 1980s, when growth was strong, could have reduced foreign and short-term borrowing and made India far less vulnerable to an oil shock or a loss of lender confidence.","status":"interpretation"},{"t":"Some argue that broader reform of labour law and land markets in the 1990s would have encouraged more labour-intensive manufacturing and formal jobs; others argue that gradualism made reform politically durable across changes of government.","status":"controversy"},{"t":"Others argue that larger public investment in basic education, health and rural infrastructure alongside liberalisation would have spread the gains from growth more widely and raised the economy’s long-run productive capacity.","status":"interpretation"}],"whatif":{"q":"Suppose India had not pledged its gold or obtained IMF support in 1991. What is the most likely outcome?","options":["A default on external payments, with sharper import cuts and a deeper recession","No change, because the crisis would have resolved itself as oil prices fell in 1991","Faster growth, because India would have avoided IMF conditions"],"best":0,"explain":"With reserves covering only a few weeks of imports and lenders unwilling to roll over credit, missing payments was a real risk. Default would probably have cut India off from credit and forced even deeper import compression. Lower oil prices in 1991 helped, but probably not quickly enough. Other bilateral support might have been found, so the outcome cannot be known."},"compare":[{"id":"asia-1997","similar":"Both crises involved rapidly falling reserves, a currency that could no longer be held at its managed value, a large depreciation and IMF-supported programmes with structural conditions.","different":"India’s crisis grew from fiscal and current account deficits with limited capital mobility; the 1997 crises were driven by sudden private capital outflows and weak banks.","dominant":"In India 1991, current account deficits and the loss of external credit dominate. In Asia 1997, capital-account reversals and banking fragility dominate."},{"id":"oil-1973","similar":"Both show how a sharp oil price rise widens the current account deficit of an oil-importing economy and adds to cost-push inflation through higher fuel and transport costs.","different":"In 1973–74 the oil shock was global and long-lasting; in 1990 the oil spike was short, but it hit an economy that already had little room to absorb it.","dominant":"In 1973 the global supply shock dominates. In 1991 India’s pre-existing fiscal and external weaknesses dominate, with oil as the trigger."},{"id":"eurozone-2010","similar":"Both involved governments with large fiscal deficits losing access to market borrowing and turning to the IMF and other partners for emergency finance that came with conditions.","different":"India could devalue its own currency to restore competitiveness; eurozone members such as Greece could not, so adjustment had to come through slower wage and price growth and recession.","dominant":"In India, devaluation combined with structural reform dominates the adjustment. In the eurozone, internal devaluation and fiscal austerity within a shared currency dominate."}],"ib":{"subs":["4.6","4.5","3.6","3.7","4.2","4.10"],"kc":["Change","Interdependence","Intervention","Economic well-being","Equity"],"note":"The event links the balance of payments, exchange-rate adjustment, supply-side policy and development strategy in one case, which supports evaluation in extended responses; the J-curve and Marshall–Lerner condition are HL only (guide PDF p. 56)."},"cambridge":{"topics":["balance of payments","exchange rate systems","supply-side policies","protectionism and trade liberalisation","fiscal policy","economic development"],"note":"Useful for showing how a current account crisis develops under a managed exchange rate and how devaluation and supply-side reform are used to correct it."},"university":{"fields":["development economics","international finance","political economy","economic history"],"note":"A university course would add currency-crisis models in which fiscal deficits under a managed exchange rate drain reserves, debates on sequencing reform and opening the capital account, and the political economy of reform in a crisis."},"civil":{"themes":["external sector","balance of payments","economic reforms (liberalisation, privatisation, globalisation)","industrial policy","fiscal policy","exchange rate management"],"note":"This is a defining episode for India’s external sector and reform history, linking the RBI’s reserve and exchange-rate management with the Government of India’s fiscal, industrial and trade policy choices."},"economists":["sen","ricardo"],"causal":["currency","supplyside","inflation","growth"],"concepts":["Balance of payments","Current account","Financial account","Current transfers","Remittance","Devaluation","Managed exchange rate","Fixed exchange rate","Expenditure switching","Expenditure reducing","Marshall-Lerner condition","J-curve","Import substitution","Deregulation","Privatisation","Foreign direct investment","Budget deficit","Market-based supply-side policies","Protectionism"],"cases":["GLO-014","GLO-041","DEV-006"],"policies":["Devaluation of the rupee (July 1991)","Gold pledge to the Bank of England and the Bank of Japan","IMF stand-by arrangement (1991)","New Industrial Policy (1991)","Exim scrips and trade liberalisation","Fiscal consolidation (Union Budget 1991–92)","Liberalised Exchange Rate Management System (1992)","Current account convertibility (1994)","Financial-sector reform after the Narasimham Committee (1991)"],"questions":[{"q":"Explain how a rise in oil prices and a fall in remittances could cause India’s foreign exchange reserves to fall under a managed exchange rate.","kind":"explain"},{"q":"Analyse the likely effects of the July 1991 devaluation on India’s current account and inflation, distinguishing the short run from the long run.","kind":"analyse"},{"q":"Evaluate the view that India’s 1991 crisis was caused mainly by the Gulf war rather than by domestic policy.","kind":"evaluate"},{"q":"Using the rupee per dollar data for 1990–1993, calculate the percentage change in the exchange rate between 1990 and 1993 and explain what it shows about the rupee.","kind":"data"},{"q":"Compare India’s 1991 crisis with the Asian financial crisis of 1997 in terms of causes and policy responses.","kind":"compare"}],"retrieval":[{"q":"What event in August 1990 triggered India’s balance-of-payments crisis?","a":"Iraq’s invasion of Kuwait, which raised oil prices, cut Gulf remittances and disrupted exports."},{"q":"Where was the RBI’s pledged gold sent in July 1991, and why?","a":"To London, as security for loans from the Bank of England and the Bank of Japan to raise emergency foreign currency."},{"q":"What did the New Industrial Policy of July 1991 do to industrial licensing?","a":"It abolished licensing for most industries, keeping it only for a short list."},{"q":"When did the rupee become market-determined and when did it become convertible on the current account?","a":"It became market-determined in March 1993 and current-account convertible in August 1994."},{"q":"What was consumer-price inflation in India in 1991?","a":"13.9%."}],"reflection":"Should a country wait for a crisis before making difficult reforms, or does a crisis provide the political room that reform needs?","reading":[{"t":"Vijay Joshi and I. M. D. Little, India’s Economic Reforms, 1991–2001, 1996","note":"A careful analysis of the origins of the crisis and the first phase of reform, with attention to fiscal policy."},{"t":"Montek S. Ahluwalia, ‘Economic Reforms in India since 1991: Has Gradualism Worked?’, Journal of Economic Perspectives, 2002","note":"A concise account of what was reformed, by a senior official involved, with an assessment of the gradual approach."},{"t":"Arvind Panagariya, India: The Emerging Giant, 2008","note":"Sets the reforms in the long history of Indian policy and argues for their central role in faster growth."},{"t":"Jean Drèze and Amartya Sen, India: Economic Development and Social Opportunity, 1995","note":"Argues that reform needed to be matched by public action on education and health; a counterweight to purely market-focused accounts."}],"numbers":[{"value":"about 3.5% a year","claim":"India’s average growth rate from 1950 to 1980","basis":"Widely cited national-accounts average; the basis of Raj Krishna’s ‘Hindu rate of growth’ phrase"},{"value":"about 3% of GDP","claim":"India’s current account deficit in 1990–91","basis":"Government of India Economic Survey and RBI data, commonly cited as about 3.1% of GDP"},{"value":"a few weeks of imports","claim":"Foreign exchange reserves had fallen to cover only a few weeks of imports by mid-1991","basis":"Commonly cited as about two weeks of import cover (Economic Survey 1991–92; RBI accounts)"},{"value":"about 20 tonnes","claim":"Gold sold through the State Bank of India in May 1991 with a repurchase option","basis":"Widely documented; government-owned gold confiscated from smugglers"},{"value":"about 47 tonnes; about $400 million","claim":"Gold pledged by the RBI with the Bank of England and the Bank of Japan in July 1991, and the sum raised","basis":"RBI history; usually given as 46.91 tonnes"},{"value":"about 18–19%","claim":"Cumulative devaluation of the rupee on 1 and 3 July 1991 against major currencies","basis":"RBI history of exchange-rate management"},{"value":"51%","claim":"Foreign equity share eligible for automatic approval in priority industries under the 1991 New Industrial Policy","basis":"Statement on Industrial Policy, 24 July 1991"},{"value":"1951; 1956","claim":"Industries (Development and Regulation) Act; Industrial Policy Resolution","basis":"Statutes and policy documents of the Government of India"}]},{"id":"dotcom-2000","title":"The dot-com bubble and bust","years":"1995–2002","start":"1995-08","end":"2002-10","region":"United States, with global technology markets","kind":"bubble","standfirst":"A genuine technological change, the commercial internet, drew a wave of investment and a rise in share prices that many investors came to see as permanent. The episode asks how a real innovation can still produce an asset bubble, and why its collapse led to only a mild recession.","question":"How can investors overvalue a technology that really does change the economy, and why did the bust hurt shareholders far more than workers?","before":{"p":"In the mid-1990s the United States combined steady growth, falling unemployment and low inflation. Personal computers were spreading, and the World Wide Web gave firms a new way to sell, advertise and communicate. Venture capitalists funded young internet companies, many of which had little revenue and no profits but promised to dominate new markets. Investors were willing to pay high prices for the shares of such firms because they expected rapid growth. Telecommunications firms borrowed to lay fibre-optic cable in anticipation of soaring internet traffic. Households, many buying shares for the first time through mutual funds and online brokers, saw their wealth rise year after year.","facts":[{"t":"The S&P 500 index averaged 465.25 in January 1995 and 1,428.68 in December 1999 (monthly averages).","status":"fact"},{"t":"US unemployment fell from 5.6% in 1995 to 4.0% in 2000, while consumer-price inflation stayed between 1.6% and 3.4% a year.","status":"fact"},{"t":"The US Telecommunications Act of 1996 opened local and long-distance telephone markets to more competition, encouraging investment in networks.","status":"fact"},{"t":"The US federal government ran budget surpluses from 1998 to 2001.","status":"fact"}]},"trigger":{"p":"There was no single trigger, which is typical of bubbles. The Federal Reserve raised its policy rate six times between June 1999 and May 2000. In early 2000 many internet firms were burning through cash with no profits in sight, and investors began to question whether they would ever earn enough to justify their share prices. The technology-heavy NASDAQ index peaked on 10 March 2000 and then fell, slowly at first and then steeply.","status":"interpretation"},"timeline":[{"d":"1995-08","t":"Netscape's share offering","detail":"Netscape, maker of an early web browser, sells shares to the public. The price roughly doubles on the first day, signalling investor appetite for internet companies with few profits.","status":"fact"},{"d":"1996-12","t":"Greenspan's 'irrational exuberance' speech","detail":"Federal Reserve chairman Alan Greenspan asks publicly how central bankers would know when 'irrational exuberance' had raised asset values too far. Share prices dip briefly, then keep rising.","status":"fact"},{"d":"1998-09","t":"Fed cuts rates after LTCM","detail":"After Russia's default and the rescue of Long-Term Capital Management, the Fed cuts interest rates three times in autumn 1998. Share prices resume their rise into 1999.","status":"fact"},{"d":"1999-06","t":"Fed begins raising rates","detail":"With unemployment low and growth strong, the Fed starts a series of six rate increases, taking its target from 4.75% to 6.5% by May 2000.","status":"fact"},{"d":"2000-01","t":"AOL and Time Warner announce merger","detail":"AOL, an internet company, agrees to combine with the media group Time Warner, a deal later seen as a symbol of peak confidence in internet valuations.","status":"fact"},{"d":"2000-03-10","t":"NASDAQ peaks","detail":"The NASDAQ Composite closes at about 5,050. Over the next two and a half years it loses close to four-fifths of its value.","status":"fact"},{"d":"2000-04","t":"UK auctions 3G mobile licences","detail":"Telecom firms bid about £22.5 billion for UK third-generation mobile licences, and other European auctions follow, loading the sector with debt just as share prices turn.","status":"fact"},{"d":"2001-01","t":"Fed starts cutting rates","detail":"The Fed cuts its target rate between meetings in January 2001, the first of eleven cuts that year, taking the rate to 1.75% by December.","status":"fact"},{"d":"2001-03","t":"US recession begins","detail":"The NBER later dates a recession from March to November 2001. Real GDP falls at an annualised 1.3% in the first quarter and 1.6% in the third.","status":"fact"},{"d":"2001-09-11","t":"Terrorist attacks on the United States","detail":"The attacks close US stock exchanges for several days and deepen uncertainty. The S&P 500 averages 1,044.64 in September, down from 1,178.5 in August.","status":"fact"},{"d":"2001-12","t":"Enron files for bankruptcy","detail":"The collapse of Enron, followed by WorldCom in July 2002, reveals accounting fraud and damages trust in reported profits and in auditors.","status":"fact"},{"d":"2002-07","t":"Sarbanes–Oxley Act signed","detail":"Congress tightens rules on corporate accounting, auditor independence and executive responsibility for financial statements. Share prices reach their lows in October 2002.","status":"fact"}],"actors":[{"who":"Internet start-ups and their venture-capital backers","role":"Raised money from share sales on the promise of future market dominance; many spent heavily on growth and advertising and failed when funding dried up."},{"who":"Telecommunications firms","role":"Borrowed heavily to build fibre-optic networks and buy mobile licences, creating far more capacity than demand required in the short run."},{"who":"Federal Reserve under Alan Greenspan","role":"Questioned high valuations in 1996 but chose not to target share prices directly; raised rates in 1999–2000 and cut them sharply from 2001."},{"who":"Households and fund investors","role":"Bought shares directly and through mutual funds and pensions; rising wealth supported consumption, and falling wealth later restrained it."},{"who":"Investment banks, analysts and auditors","role":"Brought new firms to market and published optimistic research; conflicts of interest and accounting failures were exposed after the bust."}],"changed":"Business investment in computers, software and communications equipment grew rapidly in the late 1990s, and US productivity growth picked up. Rising share prices increased household wealth and encouraged consumption, so saving fell. When the bubble burst, investment in technology fell sharply, many young firms disappeared and telecom companies went bankrupt under their debts. Yet the network capacity and much of the know-how remained, and some surviving firms grew into dominant companies. Unemployment rose from 4.0% in 2000 to 6.0% in 2003, a smaller rise than in many recessions.","predict":{"q":"Share prices fall heavily from 2000 to 2002, and household wealth drops. Before reading on, predict what happens to US consumer spending and real GDP.","options":["Consumer spending keeps growing slowly and the recession is mild, helped by rate cuts and tax cuts","Consumer spending collapses and real GDP falls for several years","Consumer spending rises sharply because shares become cheaper to buy"],"answer":0,"explain":"Falling wealth did restrain consumption, but it was spread across many households, little of it was financed by bank loans, and the banking system stayed sound. Large interest-rate cuts and tax cuts supported spending. The main fall in AD came from business investment, so the recession was short and shallow."},"mechanism":["New technology + optimistic expectations → expected future profits rise → demand for technology shares increases → share prices rise","Rising share prices → feedback: past gains attract new buyers and easy share issuance funds more start-ups → prices rise further above values based on realistic profits","Higher wealth and cheap equity finance → consumption and investment rise → AD shifts right; productivity gains also shift LRAS right, so inflation stays low","Higher interest rates, doubts about profits and cash running out → demand for shares falls → share prices fall","Falling share prices → negative wealth effect on consumption and higher cost of equity finance → investment in technology falls sharply → AD shifts left","Lower AD → real GDP growth slows and cyclical unemployment rises → central bank cuts rates and government cuts taxes → AD partly restored"],"charts":[{"series":"sp500","from":"1995-01","to":"2003-12","title":"S&P 500 index, monthly average","look":"Steady rise from 465.25 in January 1995 to a peak monthly average of 1,485.46 in August 2000, then a fall to 837.03 by February 2003. The broad index fell less than technology shares did.","marks":[{"at":"1996-12","label":"Irrational exuberance speech"},{"at":"2000-03","label":"NASDAQ peaks"},{"at":"2002-07","label":"Sarbanes–Oxley"}]},{"series":"us-gdp-q","from":"1999-01","to":"2003-10","title":"US real GDP growth, quarterly, annualised %","look":"Growth reaches 7.5% in the second quarter of 2000, then falls; output contracts at 1.3% and 1.6% annualised in the first and third quarters of 2001. Note that the quarters in between were positive.","marks":[{"at":"2001-01","label":"Recession begins"},{"at":"2001-07","label":"September 11"}]},{"series":"us-unemp","from":"1995","to":"2005","title":"US unemployment rate, annual average %","look":"Unemployment falls to 4.0% in 2000 and rises to 6.0% in 2003. It kept rising after the recession officially ended, a pattern often called a jobless recovery.","marks":[{"at":"2001","label":"Recession year"}]}],"diagrams":[{"dg":"adas","how":"Start from an economy near full employment. Show AD shifting left as business investment in technology falls and the wealth effect reduces consumption. Real output falls below its potential level and the price level rises more slowly. Then show expansionary monetary and fiscal policy shifting AD partly back to the right."},{"dg":"lras","how":"Show LRAS shifting right because investment in information technology raised productivity. This helps explain why the late-1990s boom brought low inflation, and why the bust did not destroy the economy's productive capacity even though share prices fell."}],"policy":[{"who":"Federal Reserve","when":"1999-06","what":"Raised its federal funds target six times from 4.75% to 6.5% by May 2000 to slow demand in a tight labour market, a tightening that coincided with the peak in technology shares.","status":"fact"},{"who":"Federal Reserve","when":"2001","what":"Cut its target rate eleven times during 2001, to 1.75%, and later to 1% by June 2003, to support demand after the bust and the September 11 attacks.","status":"fact"},{"who":"US Congress and President George W. Bush","when":"2001-06","what":"Enacted income tax cuts, including rebate payments to households in 2001, which added to disposable income during the recession, although their design was mainly long term.","status":"fact"},{"who":"US Congress","when":"2002-07","what":"Passed the Sarbanes–Oxley Act, which created a public oversight board for auditors, strengthened auditor independence and required senior executives to certify their firms' financial statements personally.","status":"fact"}],"stakeholders":[{"who":"Shareholders in technology firms","effect":"Gained heavily in the late 1990s and lost much of it from 2000; those who bought near the peak suffered the largest losses."},{"who":"Workers in technology and telecoms","effect":"Enjoyed strong demand for skills and share options in the boom, then faced layoffs and worthless options as firms cut back or failed."},{"who":"Workers elsewhere in the economy","effect":"Were affected less, as the recession was mild, but the slow rise in employment after 2001 meant job seekers faced weak hiring for several years."},{"who":"Consumers","effect":"Benefited in the long run from cheaper communications and new online services, many of them built on network infrastructure financed during the bubble."},{"who":"Employees of Enron and WorldCom","effect":"Lost jobs and, in Enron's case, much of their retirement savings held in company shares, exposing the risk of concentrated pension holdings."}],"short":"In the short run the bust cut business investment, especially in technology and telecoms, and reduced household wealth. Real GDP growth fell from 4.1% in 2000 to 1.0% in 2001 and unemployment rose. Because banks had not lent heavily against technology shares, the banking system stayed sound, and fast interest-rate cuts plus tax cuts supported spending. The recession was among the mildest in post-war US history, but hiring stayed weak for some time afterwards.","long":"In the long run, the internet changed retailing, media and communications, as investors had expected, although few of the firms that floated in the bubble survived. Fibre networks built at a loss became cheap capacity for later users. US productivity growth stayed relatively strong until the mid-2000s. Policy lessons were mixed: the episode encouraged the view that central banks could clean up after an asset bust, a view many economists revisited after 2008.","transmission":"The bubble and its bust were international because technology and telecom shares were traded globally. European and Asian technology markets rose and fell with the NASDAQ, and Germany's Neuer Markt for growth firms was closed in 2003. European telecom groups that had paid heavily for mobile licences faced debt problems. East Asian exporters of electronics saw demand slow in 2001. The real effects abroad were smaller than the market swings, because the shock was mainly to wealth and investment rather than to banks.","winners":[{"t":"Early investors and founders who sold shares before 2000.","status":"fact"},{"t":"Later users of telecom and internet infrastructure, who gained capacity built at a loss by others.","status":"inference"},{"t":"Surviving internet firms, which faced less competition once rivals failed.","status":"inference"}],"losers":[{"t":"Investors who bought technology shares near the peak in 2000.","status":"fact"},{"t":"Creditors and shareholders of bankrupt telecom firms such as WorldCom.","status":"fact"},{"t":"Technology workers laid off from 2001, many of whom had been partly paid in share options.","status":"fact"}],"unintended":[{"t":"Very low interest rates after 2001, intended to support recovery, may have fed the later US housing boom, a link argued by John Taylor and others but disputed by the Fed.","status":"controversy"},{"t":"Overbuilt fibre-optic networks lowered the cost of bandwidth, helping later internet firms grow.","status":"inference"},{"t":"Accounting scandals revealed in the bust led to the Sarbanes–Oxley Act, which raised compliance costs and may have discouraged some smaller firms from listing.","status":"controversy"}],"interpretations":[{"view":"Behavioural finance (Robert Shiller)","p":"Shiller argued that share prices had risen far above levels justified by earnings and dividends, driven by feedback loops, media stories and the belief that prices would keep rising. His book Irrational Exuberance, published in March 2000, became a reference point for the view that markets can misprice assets for years.","status":"interpretation"},{"view":"Rational uncertainty about a new technology","p":"Another view holds that high prices reflected genuine uncertainty: no one knew which firms would win, and a few huge successes could justify investing in many losers. Supporters of efficient markets add that bubbles are easy to identify afterwards but hard to identify in advance.","status":"controversy"},{"view":"Should central banks lean against bubbles?","p":"The Greenspan Fed argued that bubbles are hard to diagnose and that raising rates to burst them would damage the wider economy, so it was better to cut rates after a bust. Economists at the Bank for International Settlements argued instead for leaning against credit and asset booms early.","status":"controversy"}],"explain":["The AD/AS model explains how falling investment and a negative wealth effect shifted AD left, slowing growth and raising cyclical unemployment.","Supply and demand for shares explain how changing expectations of future profits move share prices.","Monetary policy analysis explains how lower interest rates cushioned the fall in spending by making borrowing cheaper."],"miss":["Models based on rational, maximising investors struggle to explain why prices rose so far above any plausible estimate of future profits.","Standard macroeconomic models in use at the time largely ignored asset prices, so they gave little warning of how a bust might affect demand.","Simple models treat all asset busts alike; they miss why this one, without heavy bank lending, was much less damaging than credit-fuelled busts."],"differently":[{"t":"Regulators could have tackled analysts' conflicts of interest and weak accounting standards before the bust rather than after it, which might have reduced the flow of money into firms with little prospect of profit.","status":"interpretation"},{"t":"The Fed could have raised margin requirements on share purchases bought with borrowed money, a tool Greenspan considered. Critics argued this would have had little effect, since most share buying was not financed by margin loans.","status":"controversy"}],"whatif":{"q":"Suppose the Fed had raised interest rates sharply in 1997 to stop share prices rising. What is the most plausible outcome?","options":["Share prices might have risen less, but at the cost of slower growth and higher unemployment, with uncertain effects on the size of the later bust","The bubble would have ended with no effect on the wider economy","Inflation would have risen because higher interest rates raise firms' costs"],"best":0,"explain":"Higher rates would have reduced demand across the whole economy, not only in technology shares, so jobs and output would probably have been lost. Investors expecting very high returns might not have been deterred by a few points of interest. Whether a smaller bubble would have meant a smaller bust is uncertain, and this debate continues among central bankers."},"compare":[{"id":"gfc-2008","similar":"Both followed long rises in asset prices driven by optimistic expectations, and in both the Fed cut interest rates sharply after the bust to support demand.","different":"The dot-com bubble was mainly in shares bought with savings, so losses fell on investors. The housing bubble was financed by bank and shadow-bank credit, so losses broke the financial system.","dominant":"Dot-com: a wealth and investment shock to AD. GFC: a banking crisis and credit crunch that magnified the fall in AD."},{"id":"great-depression","similar":"Both followed a boom in share prices built on new technologies, from radio and cars in the 1920s to the internet in the 1990s, and a sharp stock-market fall.","different":"In the 1930s bank failures and a shrinking money supply turned a crash into a depression. In 2001 the banks held up and policy eased quickly, so the recession was mild.","dominant":"Depression: monetary contraction, bank failures and debt deflation. Dot-com: a fall in business investment and household wealth, cushioned by rapid monetary and fiscal easing."}],"ib":{"subs":["3.2","3.5","3.3","2.4"],"kc":["Change","Choice","Efficiency","Intervention"],"note":"The episode connects behavioural ideas about investor choice with AD/AS analysis and monetary policy, and it gives students a clear case for evaluating whether a central bank should respond to asset prices."},"cambridge":{"topics":["aggregate demand","the business cycle","monetary policy","behavioural economics","financial markets"],"note":"Useful for showing how wealth effects and investment move aggregate demand, and for evaluating monetary policy responses to a downturn."},"university":{"fields":["financial economics","macroeconomics","behavioural finance","economic history"],"note":"A university course would add asset-pricing models, tests of market efficiency, models of speculative bubbles with limits to arbitrage, and the debate on whether monetary policy should respond to asset prices."},"civil":{"themes":["financial markets","monetary policy","technology and growth","corporate governance"],"note":"The boom in US technology spending helped raise demand for Indian IT services in the late 1990s, and the governance scandals that followed are a reference point for debates on auditing and disclosure."},"economists":["keynes","hayek"],"causal":["ratehike","growth","unemployment"],"concepts":["Wealth","Investment","Aggregate demand","Business cycle","Recession","Cyclical unemployment","Monetary policy","Expansionary policy","Behavioural economics","Bounded rationality","Availability bias","Asymmetric information"],"cases":[],"policies":["Interest-rate changes","Income tax cuts and rebates","Accounting and audit regulation","Margin requirements"],"questions":[{"q":"Explain how a fall in share prices can reduce aggregate demand.","kind":"explain"},{"q":"Using an AD/AS diagram, analyse why the late-1990s US boom combined fast growth with low inflation.","kind":"analyse"},{"q":"Evaluate the view that central banks should raise interest rates to prevent asset-price bubbles.","kind":"evaluate"},{"q":"Using the unemployment and quarterly GDP data, describe the 2001 recession and explain why unemployment kept rising after growth resumed.","kind":"data"},{"q":"Compare the dot-com bust with the 2008 financial crisis, explaining why one caused a much deeper recession.","kind":"compare"}],"retrieval":[{"q":"On what date did the NASDAQ Composite peak?","a":"10 March 2000."},{"q":"What is the wealth effect?","a":"The change in consumption that follows a change in household wealth, such as a fall in share prices."},{"q":"When did the NBER date the 2001 US recession?","a":"March to November 2001."},{"q":"What did the Sarbanes–Oxley Act of 2002 aim to do?","a":"Improve the reliability of corporate financial reporting by tightening rules on auditors and executive responsibility."},{"q":"Why did the dot-com bust not cause a banking crisis?","a":"Most share purchases were financed by savings rather than bank loans, so losses fell on investors, not on banks."}],"reflection":"If a new technology is clearly important, how would you decide whether the prices investors pay for it are reasonable?","reading":[{"t":"Robert J. Shiller, Irrational Exuberance, 2000","note":"Written at the peak; explains the psychological and institutional forces behind high share prices."},{"t":"Charles P. Kindleberger, Manias, Panics, and Crashes, 1978 (later editions)","note":"A historical framework for bubbles and busts that the dot-com episode fits closely."},{"t":"Carlota Perez, Technological Revolutions and Financial Capital, 2002","note":"Argues that financial bubbles often accompany the installation of major new technologies."},{"t":"John Cassidy, dot.con, 2002","note":"A journalist's narrative of the bubble, its promoters and its collapse."}],"numbers":[{"value":"about 5,050","claim":"NASDAQ Composite closing peak on 10 March 2000","basis":"Exchange record: 5,048.62."},{"value":"close to four-fifths","claim":"NASDAQ Composite fall from March 2000 peak to October 2002 low","basis":"Peak 5,048.62; low of 1,114.11 on 9 October 2002, a fall of about 78%."},{"value":"roughly doubles","claim":"Netscape share price on its first trading day, August 1995","basis":"Offered at $28, the shares closed at about $58 on the first day."},{"value":"six; 4.75% to 6.5%","claim":"Federal Reserve rate increases June 1999–May 2000","basis":"FOMC decisions, June 1999 to May 2000."},{"value":"eleven; 1.75%; 1%","claim":"Fed rate cuts in 2001, end-2001 target, and June 2003 target","basis":"FOMC decisions, 2001–03."},{"value":"about £22.5 billion","claim":"Proceeds of the UK 3G mobile licence auction, April 2000","basis":"UK Radiocommunications Agency auction result."},{"value":"three","claim":"Fed rate cuts in autumn 1998","basis":"FOMC decisions of September, October and November 1998."},{"value":"1998 to 2001","claim":"Years of US federal budget surplus","basis":"US Office of Management and Budget historical tables (fiscal years)."}]},{"id":"asia-1997","title":"The Asian financial crisis","years":"1997–98","start":"1997-07","end":"1998-12","region":"East and South-East Asia","kind":"crisis","standfirst":"Some of the fastest-growing economies in the world lost a large share of their dollar income within a year, after a run on the Thai baht spread across the region. The episode asks how a fixed exchange rate, short-term foreign borrowing and fragile banks can turn a currency fall into a deep recession.","question":"Why did a currency devaluation in one middle-sized economy turn into a regional recession, and did the policy response help or hurt?","before":{"p":"By the mid-1990s Thailand, South Korea, Indonesia and Malaysia had grown quickly for decades, helped by high saving, investment in factories and schooling, and exports to rich markets. Their currencies were held stable against the US dollar, either by a peg or by a tightly managed band. Interest rates at home were well above those in the United States and Japan, so banks and firms borrowed in dollars and yen, often for short periods, and lent the money on at home in local currency. Much of it went into property and share prices. Thailand ran a large current account deficit, financed by these capital inflows. The arrangement worked only while lenders were willing to keep rolling the loans over.","facts":[{"t":"Thailand's central bank kept the baht within a narrow range against a basket of currencies dominated by the US dollar for more than a decade before 1997.","status":"fact"},{"t":"Thailand created the Bangkok International Banking Facility in 1993, which made it easier for domestic borrowers to raise foreign-currency loans.","status":"fact"},{"t":"Thailand's current account deficit was about 8% of GDP in 1996.","status":"fact"},{"t":"In January 1997 Hanbo Steel, part of a large South Korean business group, went bankrupt, an early sign of strain in Korea's highly indebted corporate sector.","status":"fact"},{"t":"The baht averaged 25.76 per US dollar in 1987 and 25.36 in 1996, a decade of near-stability against the dollar.","status":"fact"}]},"trigger":{"p":"In early 1997 Thai property developers and finance companies began to fail, and speculators sold the baht in expectation of a devaluation. The Bank of Thailand spent much of its usable reserves, partly through forward contracts, defending the peg in May. On 2 July 1997, with reserves close to exhausted, it let the baht float. The currency fell sharply, and lenders began to ask which other Asian economies had the same weaknesses.","status":"fact"},"timeline":[{"d":"1997-05","t":"Speculative attack on the baht","detail":"Heavy selling of the baht forces the Bank of Thailand to commit much of its foreign-currency reserves, largely through forward contracts, to defend the peg.","status":"fact"},{"d":"1997-07-02","t":"Thailand floats the baht","detail":"Thailand abandons the peg. The baht depreciates at once, and the annual average for 1997 is 31.07 per US dollar against 25.36 in 1996.","status":"fact"},{"d":"1997-07-11","t":"Philippine peso allowed to float","detail":"The Philippines lets the peso move more freely within days of the Thai float, the first sign that investors were reassessing similar economies.","status":"fact"},{"d":"1997-08","t":"IMF programme for Thailand","detail":"Thailand agrees an IMF-led rescue package with conditions on fiscal policy, interest rates and the closure of insolvent finance companies. Indonesia floats the rupiah in mid-August.","status":"fact"},{"d":"1997-10","t":"Pressure reaches Hong Kong","detail":"An attack on the Hong Kong dollar peg is resisted with sharply higher interest rates, and share prices in Hong Kong fall steeply, rippling into markets elsewhere.","status":"fact"},{"d":"1997-11","t":"Indonesian bank closures spark runs","detail":"Under its first IMF programme Indonesia closes sixteen private banks with only limited protection for depositors. Depositors run on other banks, and the rupiah continues to fall.","status":"fact"},{"d":"1997-12","t":"South Korea's IMF rescue","detail":"South Korea, short of reserves to repay maturing short-term debt, agrees the largest IMF-led package to that date. Foreign banks are later persuaded to roll over their loans.","status":"fact"},{"d":"1998-05-21","t":"Suharto resigns in Indonesia","detail":"After a currency collapse, rising prices and riots, President Suharto steps down. Indonesian consumer-price inflation reaches 58.5% for 1998 as a whole.","status":"fact"},{"d":"1998-08","t":"Russia defaults; contagion widens","detail":"Russia devalues and defaults on domestic debt in August. Losses spread to emerging markets in general and to leveraged investors in rich countries.","status":"fact"},{"d":"1998-09","t":"Malaysia imposes capital controls","detail":"Malaysia restricts the movement of short-term capital and fixes the ringgit at 3.80 per US dollar, a rate it keeps until 2005.","status":"fact"},{"d":"1998-09","t":"LTCM rescue and Fed rate cuts","detail":"The New York Fed organises a private rescue of the hedge fund Long-Term Capital Management, and the Fed cuts interest rates three times in autumn 1998.","status":"fact"}],"actors":[{"who":"Bank of Thailand","role":"Defended the baht peg with reserves and forward sales of dollars, then floated the currency on 2 July 1997 when its usable reserves ran low."},{"who":"International Monetary Fund (IMF)","role":"Lent to Thailand, Indonesia and South Korea on conditions that included high interest rates, initial fiscal tightening, bank closures and structural reforms."},{"who":"Foreign banks and portfolio investors","role":"Had lent short-term in dollars and yen; their refusal to roll over loans and their sales of local assets turned a currency problem into a liquidity crisis."},{"who":"Domestic banks, finance companies and conglomerates","role":"Borrowed in foreign currency and lent or invested in local currency, so depreciation raised the burden of their debts and many became insolvent."},{"who":"Government of Malaysia under Mahathir Mohamad","role":"Rejected an IMF programme, cut interest rates and in September 1998 imposed capital controls with a fixed ringgit, a contested alternative strategy."},{"who":"US Treasury and Federal Reserve","role":"Shaped the IMF packages and, after Russia's default and the LTCM rescue, cut US interest rates, easing global financial conditions."}],"changed":"Within a year, the crisis economies moved from rapid growth to deep recession. Currencies lost a large part of their value, so imports became expensive and firms with dollar debts faced much larger repayments in local currency. Banks failed or were nationalised, credit contracted, investment collapsed and unemployment and poverty rose, most severely in Indonesia. Current account deficits turned into surpluses, mainly because imports fell. Afterwards the region's governments accumulated large foreign-exchange reserves as self-insurance and became wary of short-term foreign borrowing.","predict":{"q":"Illustrative figures: a Thai firm owes US$10 million and earns its revenue in baht. The baht falls from 25 to 40 per dollar. What happens to the firm's debt measured in baht?","options":["It rises by about 60%, even though nothing about the firm's business has changed","It stays the same, because the loan was agreed in dollars","It falls, because a weaker baht makes Thai exports cheaper"],"answer":0,"explain":"The debt is fixed in dollars, so its baht value is the dollar amount times the exchange rate: 250 million baht becomes 400 million baht. This currency mismatch is the heart of the crisis. Cheaper exports help over time, but the jump in debt arrives at once and can make a firm insolvent before export gains appear."},"mechanism":["Pegged exchange rate + higher domestic interest rates → firms and banks borrow short-term in dollars and yen, believing the exchange-rate risk is small","Capital inflows → credit boom → rising property and share prices; current account deficits widen","Doubts about the peg → capital flight: supply of baht on the foreign exchange market increases and demand falls → reserves drain until the peg is abandoned","Depreciation → baht value of dollar debts rises (currency mismatch) → firms and banks become insolvent → bank lending contracts","Lenders refuse to roll over short-term loans (a sudden stop) → the financial account inflow reverses → imports must fall sharply","Higher interest rates to defend the currency, falling asset prices and lost confidence → consumption and investment fall → AD shifts left → real output falls and unemployment rises","Investors reassess similar economies (contagion) → the same sequence repeats in Indonesia, South Korea and Malaysia"],"charts":[{"series":"fx-thailand","from":"1990","to":"2002","title":"Baht per US dollar, annual average","look":"A decade of near-stability around 25 baht, then a jump to 31.07 in 1997 and 41.32 in 1998. A higher number means a weaker baht. The rate does not return to its pre-crisis level.","marks":[{"at":"1997","label":"Baht floated, July"}]},{"series":"fx-south-korea","from":"1990","to":"2002","title":"Won per US dollar, annual average","look":"The won averaged 805.16 per dollar in 1996 and 1,404.2 in 1998. Compare the timing with Thailand: Korea was hit later in 1997, after contagion spread north.","marks":[{"at":"1997","label":"IMF package, December"}]},{"panel":"gdp","entities":["THA","KOR","IDN","MYS"],"from":"1993","to":"2003","title":"GDP in current US dollars, US$ billions","look":"Indonesia's GDP falls from 227.4 billion dollars in 1996 to 95.4 billion in 1998. Much of this fall reflects depreciation, because local-currency output is converted at a far weaker rate.","marks":[{"at":"1998","label":"Trough in dollar terms"}]},{"panel":"infl","entities":["IDN","THA","KOR","MYS"],"from":"1993","to":"2003","title":"Consumer-price inflation, annual %","look":"Depreciation raises import prices. Indonesia's inflation reaches 58.5% in 1998; Thailand's (8.0%) and Korea's (7.5%) rise far less, then all fall back as recession bites.","marks":[{"at":"1998","label":"Imported inflation peaks"}]}],"diagrams":[{"dg":"fx","how":"Draw the market for baht with the exchange rate in US dollars per baht. Capital flight and lost confidence shift demand for baht left and supply of baht right. The equilibrium rate falls well below the old pegged rate, which the central bank can no longer hold with reserves."},{"dg":"adas","how":"Show AD shifting left as investment, consumption and credit collapse, with higher interest rates adding to the fall. Real output falls below the full employment level. Depreciation also raises import costs, so SRAS may shift left, pushing prices up while output falls."}],"policy":[{"who":"Bank of Thailand","when":"1997-07","what":"Ended the peg and let the baht float after spending much of its usable reserves. This stopped the drain on reserves but transferred the shock to borrowers with foreign-currency debts.","status":"fact"},{"who":"IMF with Thailand, Indonesia and South Korea","when":"1997","what":"Provided large loans conditional on high interest rates to stabilise currencies, initial fiscal tightening, closure or recapitalisation of weak financial institutions and wider structural reforms.","status":"fact"},{"who":"Creditor banks, coordinated by official lenders","when":"1997-12","what":"Foreign banks were persuaded to roll over and later reschedule short-term loans to Korean banks, slowing the outflow of capital that the official loans alone could not offset.","status":"fact"},{"who":"Government of Malaysia","when":"1998-09","what":"Imposed controls on short-term capital outflows and fixed the ringgit at 3.80 per US dollar, then lowered interest rates instead of following an IMF-style programme.","status":"fact"},{"who":"IMF and crisis governments, second stage","when":"1998","what":"As recessions deepened, fiscal targets were relaxed to allow larger budget deficits and more spending on social safety nets, a significant revision of the original programmes' demand for tightening.","status":"fact"},{"who":"ASEAN members, China, Japan and South Korea","when":"2000","what":"Agreed the Chiang Mai Initiative, a network of bilateral currency swap lines intended to give the region its own source of emergency foreign currency and reduce reliance on the IMF.","status":"fact"}],"stakeholders":[{"who":"Workers in the crisis economies","effect":"Lost jobs as firms failed and investment collapsed; real wages fell as import prices rose. Many moved back into informal or rural work."},{"who":"Poor households, especially in Indonesia","effect":"Faced sharply higher prices for food and imported goods. Poverty rose markedly in 1998, reversing part of the gains of earlier decades."},{"who":"Firms with dollar debts","effect":"Saw their debts rise in local-currency terms overnight. Many large firms and conglomerates defaulted or were restructured, and some were sold to foreign buyers."},{"who":"Exporters with local-currency costs","effect":"Gained price competitiveness from depreciation, though many could not expand at first because credit for imported inputs and working capital dried up."},{"who":"Foreign creditors and investors","effect":"Suffered losses on loans and shares, but many short-term lenders were repaid with the help of official rescue loans, which raised questions of moral hazard."},{"who":"Consumers and firms in importing countries","effect":"Benefited from cheaper Asian goods and lower commodity prices in 1998, while producers competing with Asian firms faced stronger import competition and pressure on prices."}],"short":"In the short run the crisis economies suffered a severe contraction. Depreciation raised the value of foreign-currency debts, banks failed, credit dried up and interest rates were held high to stop the slide in the currency. Imports fell much faster than exports grew, so current accounts swung into surplus through falling income, not booming sales abroad. Inflation rose where depreciation was largest, above all in Indonesia, and unemployment and poverty increased across the region.","long":"Over the following decade, South Korea, Thailand and Malaysia returned to growth, helped by competitive exchange rates and recovering exports, while Indonesia's recovery was slower and coincided with a political transition. Governments restructured their banks, tightened supervision and built up large foreign-exchange reserves. Many economists see that reserve build-up, and the current account surpluses behind it, as part of the global saving flow into US assets that preceded 2008, though that link is debated.","transmission":"The crisis spread less through trade than through finance. Investors who lost money in Thailand reassessed economies with similar features: pegged currencies, short-term foreign debt and weak bank supervision. Funds sold assets across the region to meet losses, and banks cut credit lines. Trade links added pressure, since a cheaper baht made rival exporters less competitive. By 1998 falling Asian demand had depressed commodity prices, which hurt exporters such as Russia, and Russia's default spread losses to other emerging markets and to leveraged investors in New York.","winners":[{"t":"Importers of Asian manufactures, who paid lower prices after 1997–98.","status":"inference"},{"t":"Foreign buyers who acquired Asian firms and assets at depressed prices after the crisis.","status":"fact"},{"t":"Exporters in the crisis economies with local-currency costs and access to finance, once trade credit recovered.","status":"inference"}],"losers":[{"t":"Workers and poor households in Indonesia, Thailand and South Korea, through job losses and higher prices for essentials.","status":"fact"},{"t":"Owners and creditors of failed banks, finance companies and conglomerates.","status":"fact"},{"t":"Taxpayers in the crisis economies, who bore much of the cost of recapitalising or closing banks.","status":"fact"}],"unintended":[{"t":"Closing Indonesian banks in November 1997 with only limited protection for depositors triggered runs on other banks and deepened the panic.","status":"fact"},{"t":"Large official loans that repaid foreign creditors may have encouraged future risky lending to emerging markets, a moral hazard concern raised at the time.","status":"controversy"},{"t":"Asian governments' later accumulation of very large reserves, partly to avoid ever needing the IMF again, added to global imbalances in the 2000s.","status":"interpretation"}],"interpretations":[{"view":"Fundamentals and moral hazard","p":"One view, prominent in early analyses by Paul Krugman and others, stresses weaknesses inside the crisis economies: implicit government backing for banks and connected firms encouraged excessive borrowing and poor investment. On this reading the crisis exposed losses that already existed, and reform of banking and governance was the necessary cure.","status":"interpretation"},{"view":"Financial panic (Radelet and Sachs)","p":"Steven Radelet and Jeffrey Sachs argued that the economies were basically solvent but illiquid: short-term foreign debt exceeded reserves, so a loss of confidence became self-fulfilling. They criticised early IMF bank closures and austerity for deepening the panic rather than calming it.","status":"interpretation"},{"view":"Critics of the IMF (Stiglitz)","p":"Joseph Stiglitz, then chief economist at the World Bank, argued that premature capital-account liberalisation caused the vulnerability and that IMF demands for high interest rates and fiscal tightening worsened the recessions. Defenders of the IMF reply that very high rates were needed to stop a self-feeding collapse of the currencies.","status":"controversy"},{"view":"Capital controls in Malaysia","p":"Whether Malaysia's 1998 controls worked is still debated. Supporters point to its recovery without an IMF programme; sceptics note the controls came after the worst pressure had passed, when regional interest rates were already falling, so their separate effect is hard to identify.","status":"controversy"}],"explain":["The foreign exchange market model explains why capital flight lowers the currency's value and why a central bank with limited reserves cannot hold a peg indefinitely.","The AD/AS model explains how falling investment, consumption and credit shift AD left, reducing real output and employment.","Balance of payments accounting explains why a sudden reversal of financial account inflows forces a matching swing in the current account, mainly through lower imports."],"miss":["Simple exchange rate models predict that depreciation boosts net exports and output; they miss balance-sheet effects, where dollar debts make depreciation contractionary in the short run.","Standard models treat the exchange rate as set by fundamentals; they miss self-fulfilling panics, in which fear of devaluation alone can cause it.","Basic AD/AS analysis has little to say about bank runs and credit crunches, which magnified the fall in spending."],"differently":[{"t":"Stronger bank supervision and limits on short-term foreign-currency borrowing during the boom years might have reduced the currency mismatch that made depreciation so damaging, though such rules can be evaded and may slow growth.","status":"interpretation"},{"t":"Central banks, acting as lenders of last resort, could have protected depositors more clearly when weak banks were closed, especially in Indonesia, to avoid runs on sound institutions. Broad protection, however, shifts losses to taxpayers.","status":"interpretation"},{"t":"Earlier coordinated rollover of private short-term loans, as eventually arranged for Korea, might have reduced the need for very high interest rates, although the success of a rollover depends on creditor cooperation.","status":"controversy"}],"whatif":{"q":"Suppose Thailand had allowed the baht to float gradually in 1995–96, before reserves ran low. What is the most plausible outcome?","options":["A smaller, more orderly depreciation, though firms with dollar debts would still have faced losses","No change, because the crisis was purely the result of contagion from abroad","An immediate boom, because a weaker baht has only positive effects on output"],"best":0,"explain":"An earlier, voluntary exit would have kept reserves intact and might have discouraged unhedged dollar borrowing, so the adjustment could have been smaller. It would not have removed the underlying problems of weak banks and an asset bubble, and a pre-emptive move can itself trigger capital flight. The counterfactual is uncertain: we cannot observe how investors would have responded."},"compare":[{"id":"india-1991","similar":"Both were balance of payments crises in which foreign-currency reserves ran low, the currency was devalued or floated, and IMF support came with conditions on fiscal and structural policy.","different":"India's crisis followed fiscal deficits in a relatively closed economy with limited private foreign debt. Asia's crisis struck open, fast-growing economies whose private banks and firms had borrowed heavily abroad.","dominant":"India 1991: a fiscal and current account problem met by reform. Asia 1997: a private capital-account reversal with banking collapse and contagion."},{"id":"gfc-2008","similar":"Both featured a credit boom, rising asset prices, banks funding long-term lending with short-term borrowing, and a sudden loss of confidence that spread across countries.","different":"In 2008 the crisis began in the economy that issues the world's reserve currency, so its central bank could create the dollars it needed. Asian economies had to borrow foreign currency they could not print.","dominant":"Asia: currency mismatch and sudden stop of foreign capital. GFC: losses on mortgage securities and a run on short-term funding of banks."},{"id":"eurozone-2010","similar":"Both involved large capital inflows that financed current account deficits, followed by a sudden stop of finance and painful adjustment under externally designed programmes with IMF participation.","different":"Eurozone members could not devalue, so adjustment came slowly through falling wages and prices. Asian currencies depreciated sharply, which hurt foreign-currency borrowers at first but later helped exports recover.","dominant":"Asia: sharp depreciation and its balance-sheet effects on private borrowers. Eurozone: no exchange-rate adjustment, so internal devaluation and fears about sovereign debt dominate."}],"ib":{"subs":["4.5","4.6","3.5","3.2"],"kc":["Interdependence","Intervention","Change","Economic well-being"],"note":"The episode lets students apply foreign exchange and balance of payments diagrams to a real case and evaluate the trade-off between defending a currency with high interest rates and protecting domestic output, which suits Paper 1 essays and Paper 2 data responses."},"cambridge":{"topics":["exchange rate systems","balance of payments","capital flows","monetary policy","international financial institutions"],"note":"Useful for comparing fixed and floating exchange rates and for evaluating policies to correct balance of payments instability."},"university":{"fields":["international finance","open-economy macroeconomics","financial crises","development economics"],"note":"A university course would add models of currency crises, from speculative-attack models to self-fulfilling crises, and the balance-sheet approach to currency mismatch and 'original sin' in foreign borrowing."},"civil":{"themes":["external sector","exchange rate management","capital account convertibility","financial stability","role of the IMF"],"note":"India was largely insulated in 1997–98, which helped shape a cautious, gradual approach to opening its capital account and to building foreign-exchange reserves."},"economists":["stiglitz","friedman"],"causal":["currency","ratehike","growth","unemployment"],"concepts":["Fixed exchange rate","Floating exchange rate","Managed exchange rate","Devaluation","Depreciation","Capital flight","Current account","Financial account","Portfolio investment","Moral hazard","Contractionary policy","Recession"],"cases":["GLO-027","MAC-035"],"policies":["Exchange-rate peg","Floating exchange rate","Interest-rate increases to defend a currency","IMF conditional lending","Bank closure and recapitalisation","Capital controls","Regional currency swap lines"],"questions":[{"q":"Explain why a sharp depreciation of the baht raised the burden of debt for Thai firms that had borrowed in US dollars.","kind":"explain"},{"q":"Using a foreign exchange market diagram, analyse why the Bank of Thailand could not maintain the baht peg in 1997.","kind":"analyse"},{"q":"Evaluate the view that the IMF's demand for high interest rates in 1997–98 did more harm than good to the crisis economies.","kind":"evaluate"},{"q":"Using the chart of GDP in current US dollars, explain why Indonesia's GDP in dollars fell by more than its real output did in 1998.","kind":"data"},{"q":"Compare the Asian crisis of 1997–98 with India's 1991 crisis in terms of causes and policy responses.","kind":"compare"}],"retrieval":[{"q":"On what date did Thailand float the baht?","a":"2 July 1997."},{"q":"What is a currency mismatch?","a":"Owing debts in a foreign currency while earning income in the domestic currency, so depreciation raises the real burden of the debt."},{"q":"Which country rejected an IMF programme and imposed capital controls in September 1998?","a":"Malaysia, which also fixed the ringgit at 3.80 per US dollar."},{"q":"Why do current accounts tend to move into surplus after a sudden stop of capital inflows?","a":"Without new foreign finance, the country must cut imports (and raise exports) so that spending matches available foreign exchange."},{"q":"What regional arrangement did East Asian governments agree in 2000?","a":"The Chiang Mai Initiative, a network of currency swap lines."}],"reflection":"If you were advising a fast-growing economy today, how far would you limit short-term foreign borrowing, knowing that the limit might also slow investment in good years?","reading":[{"t":"Joseph E. Stiglitz, Globalization and Its Discontents, 2002","note":"A critical insider account of IMF policy in East Asia, useful for evaluation but best read alongside the IMF's defenders."},{"t":"Paul Blustein, The Chastening: Inside the Crisis that Rocked the Global Financial System and Humbled the IMF, 2001","note":"A journalist's detailed narrative of decision-making in Thailand, Indonesia and Korea."},{"t":"Steven Radelet and Jeffrey Sachs, 'The East Asian Financial Crisis: Diagnosis, Remedies, Prospects', Brookings Papers on Economic Activity, 1998","note":"The classic statement of the financial-panic interpretation."},{"t":"Paul Krugman, The Return of Depression Economics, 1999","note":"An accessible account of currency crises and contagion written soon after the events."}],"numbers":[{"value":"about 8% of GDP","claim":"Thailand's current account deficit in 1996","basis":"Widely cited IMF and Bank of Thailand estimates (about 7.9% of GDP)."},{"value":"sixteen","claim":"Number of private banks closed by Indonesia in November 1997","basis":"Widely documented in IMF and academic accounts of the first Indonesian programme."},{"value":"three","claim":"Number of Federal Reserve interest-rate cuts in autumn 1998","basis":"FOMC decisions of September, October and November 1998."},{"value":"2005","claim":"Year Malaysia ended the fixed ringgit rate of 3.80 per US dollar","basis":"Bank Negara Malaysia moved to a managed float in July 2005."},{"value":"3.80","claim":"Fixed ringgit rate per US dollar from September 1998","basis":"Bank Negara Malaysia announcement; consistent with the catalogue's annual averages of 3.8 for 1999–2004."}]},{"id":"gfc-2008","title":"The global financial crisis","years":"2007–09","start":"2007-08","end":"2009-06","region":"United States, Europe and the world economy","kind":"crisis","standfirst":"Losses on US mortgages that were small relative to the world economy set off a run on the financial system and the deepest global recession since the 1930s. The episode asks how a housing bust became a banking panic, and what governments and central banks did to stop it becoming a depression.","question":"How did falling house prices in parts of the United States bring the global financial system close to collapse, and did the policy response work?","before":{"p":"Through the early 2000s inflation was low and recessions were mild, a period economists called the Great Moderation. US house prices rose strongly for a decade, helped by low interest rates and looser lending. Lenders increasingly sold mortgages to banks that pooled them into securities, which were then sliced, rated and sold to investors around the world. Subprime loans to borrowers with weak credit records grew quickly, often with low initial rates that reset higher later. Banks and other financial firms, including those outside traditional regulation, financed long-term assets with short-term borrowing and held little capital against possible losses. Rising prices made the system look safe.","facts":[{"t":"The Federal Reserve held its policy rate at 1% from June 2003 to June 2004, then raised it in seventeen steps to 5.25% by June 2006.","status":"fact"},{"t":"US house prices roughly doubled in nominal terms between the late 1990s and their peak in 2006, on the S&P/Case–Shiller national index.","status":"fact"},{"t":"US unemployment averaged 4.6% in both 2006 and 2007, and consumer-price inflation was 3.2% and 2.9%.","status":"fact"},{"t":"Fannie Mae and Freddie Mac, government-sponsored enterprises, backed or held a large share of US mortgages.","status":"fact"}]},"trigger":{"p":"US house prices stopped rising in 2006 and began to fall. Subprime borrowers whose rates reset could no longer refinance, and defaults rose. Because mortgage securities were complex and widely held, no one knew where the losses lay. On 9 August 2007 the French bank BNP Paribas froze three investment funds, saying it could not value their US mortgage assets. Banks stopped trusting each other and interbank lending rates jumped.","status":"fact"},"timeline":[{"d":"2007-08-09","t":"BNP Paribas freezes three funds","detail":"The bank cannot value assets backed by US subprime mortgages. The European Central Bank injects liquidity into money markets the same day, and the Fed follows.","status":"fact"},{"d":"2007-09","t":"Run on Northern Rock","detail":"After news that the UK mortgage lender needed emergency support from the Bank of England, depositors queue to withdraw savings, the first UK bank run in generations. It is nationalised in February 2008.","status":"fact"},{"d":"2007-12","t":"US recession begins","detail":"The NBER later dates the start of the recession to December 2007. Central banks announce coordinated measures to supply dollar funding to banks.","status":"fact"},{"d":"2008-03","t":"Bear Stearns rescued","detail":"The investment bank runs out of short-term funding and is sold to JPMorgan Chase with Federal Reserve financial support, and the Fed begins lending to investment banks.","status":"fact"},{"d":"2008-09-07","t":"Fannie Mae and Freddie Mac taken over","detail":"The US government places the two mortgage giants into conservatorship, taking control of them as losses mount on the mortgages they backed or held.","status":"fact"},{"d":"2008-09-15","t":"Lehman Brothers files for bankruptcy","detail":"No public rescue or private buyer is found. Lehman's failure, the largest bankruptcy in US history, spreads panic through money markets worldwide.","status":"fact"},{"d":"2008-09-16","t":"AIG rescued; money fund breaks the buck","detail":"The Fed lends to the insurer AIG, which had sold protection on mortgage securities. A large money-market fund holding Lehman debt falls below its fixed share value, triggering withdrawals.","status":"fact"},{"d":"2008-10","t":"TARP and coordinated rate cuts","detail":"Congress passes the Troubled Asset Relief Program after rejecting a first version. On 8 October major central banks cut rates together, and the UK announces bank recapitalisation.","status":"fact"},{"d":"2008-12","t":"Fed rate reaches near zero","detail":"The Fed sets a target range for its policy rate of 0 to 0.25%, having announced purchases of mortgage-backed securities in November.","status":"fact"},{"d":"2009-02","t":"US fiscal stimulus enacted","detail":"The American Recovery and Reinvestment Act combines tax cuts, transfers to states and households, and public investment worth roughly 800 billion dollars over several years.","status":"fact"},{"d":"2009-03","t":"Markets bottom; QE expands","detail":"The S&P 500 averages 757.13 in March 2009, its low point. The Fed enlarges asset purchases and the Bank of England starts quantitative easing.","status":"fact"},{"d":"2009-06","t":"US recession ends","detail":"The NBER later dates the end of the recession to June 2009, but US unemployment keeps rising, averaging 9.6% in 2010.","status":"fact"}],"actors":[{"who":"Mortgage lenders and securitising banks","role":"Made and packaged loans, many to subprime borrowers, earning fees on volume while passing much of the credit risk on to investors."},{"who":"Credit rating agencies","role":"Gave high ratings to many mortgage securities that later suffered heavy losses, encouraging investors and banks to hold them as if they were safe."},{"who":"Investment banks and the shadow banking system","role":"Financed holdings of long-term securities with very short-term borrowing, so a loss of confidence could drain their funding within days."},{"who":"Federal Reserve under Ben Bernanke","role":"Cut rates to near zero, lent to banks and non-banks on a large scale, supplied dollars to foreign central banks and bought assets in quantitative easing."},{"who":"US Treasury, Congress and other governments","role":"Took over mortgage agencies, injected capital into banks, backed bank debts and enacted fiscal stimulus packages."},{"who":"Households with mortgages","role":"Borrowed heavily against rising house prices; when prices fell, many owed more than their homes were worth and cut spending or defaulted."}],"changed":"The crisis turned a fall in house prices into a collapse of credit. Banks hoarded cash, lending to firms and households contracted and world trade fell steeply in late 2008. US real GDP fell at an annualised 8.5% in the fourth quarter of 2008, and unemployment rose from 4.6% in 2007 to 9.3% in 2009. Governments took large stakes in banks, central banks cut rates to near zero and began quantitative easing, and budget deficits widened. Recovery in the United States and Europe was slow.","predict":{"q":"A bank holds long-term mortgage securities funded by loans that must be renewed every night. Lenders hear rumours of losses. What is most likely to happen?","options":["Lenders refuse to renew, the bank must sell assets quickly at low prices, and its losses grow","Nothing, because the bank's assets still pay interest","The bank's lenders offer more funding because interest rates are high"],"answer":0,"explain":"Short-term lenders can withdraw at once, while the bank's assets cannot be sold quickly at full value. A run forces fire sales, which lower prices for every holder of similar assets and spread losses to other institutions. This maturity mismatch, outside traditional deposit insurance, explains how modest mortgage losses became a system-wide panic."},"mechanism":["Low interest rates, global saving inflows and looser lending standards → demand for housing rises → house prices increase, encouraging further borrowing and building","Securitisation → lenders pass on credit risk → weaker incentives to check borrowers (asymmetric information and moral hazard) → more risky loans","House prices fall → defaults rise → mortgage securities lose value → banks with little capital face large losses","Uncertainty about who holds losses → short-term lenders withdraw (a run on shadow banks) → fire sales of assets → asset prices fall further","Bank losses and hoarding of cash → credit crunch: lending to firms and households falls → investment and consumption fall","Falling wealth, confidence and credit → AD shifts left → real GDP falls and unemployment rises; the fall spreads abroad through finance and trade","Central bank rate cuts, liquidity support, quantitative easing, bank recapitalisation and fiscal stimulus → AD partly restored and the financial system stabilised"],"charts":[{"series":"sp500","from":"2006-01","to":"2009-12","title":"S&P 500 index, monthly average","look":"A peak monthly average of 1,539.66 in October 2007, a slide through 2008, a collapse after Lehman's failure in September, and a low of 757.13 in March 2009 before recovery.","marks":[{"at":"2007-08","label":"BNP Paribas funds frozen"},{"at":"2008-09","label":"Lehman fails"},{"at":"2009-03","label":"Market low; QE expands"}]},{"series":"us-gdp-q","from":"2006-01","to":"2009-10","title":"US real GDP growth, quarterly, annualised %","look":"Growth weakens through 2007, turns negative in early 2008 and plunges to minus 8.5% in the fourth quarter of 2008. Positive growth returns in the third quarter of 2009.","marks":[{"at":"2008-10","label":"Post-Lehman collapse"}]},{"series":"us-unemp","from":"2003","to":"2014","title":"US unemployment rate, annual average %","look":"Unemployment averages 4.6% in 2007, 9.3% in 2009 and 9.6% in 2010, and falls back only slowly. Unemployment lags output: it keeps rising after GDP starts to recover.","marks":[{"at":"2009","label":"Recession ends mid-year"}]},{"series":"fx-united-kingdom","from":"2004","to":"2012","title":"Pounds per US dollar, annual average","look":"A higher number means a weaker pound. Sterling averages 0.50 per dollar in 2007 and 0.64 in 2009, a sharp depreciation as UK banks suffered and interest rates fell.","marks":[{"at":"2008","label":"Banking crisis"}]}],"diagrams":[{"dg":"adas","how":"Show AD shifting sharply left as credit, investment, consumption and exports fall, opening a large deflationary gap. Then show expansionary monetary and fiscal policy shifting AD part of the way back, and discuss why the recovery was slow if banks and households were repairing their balance sheets."},{"dg":"asym","how":"Use the asymmetric information diagram to show how lenders who sold loans on knew more about borrower risk than investors did, so risky mortgages were overproduced relative to the socially optimum level. Asymmetric information is HL only (2.10; guide PDF p. 26)."}],"policy":[{"who":"Federal Reserve","when":"2008-12","what":"Cut its policy rate to a range of 0 to 0.25% after starting cuts in September 2007, and opened lending facilities for banks, investment banks and money markets.","status":"fact"},{"who":"Federal Reserve and Bank of England","when":"2009-03","what":"Bought government bonds and, in the US, mortgage-backed securities on a large scale (quantitative easing) to lower long-term interest rates once policy rates were near zero.","status":"fact"},{"who":"US Treasury and Congress","when":"2008-10","what":"The Troubled Asset Relief Program authorised up to 700 billion dollars, mostly used to inject capital into banks and support the car industry, rather than to buy troubled assets as first planned.","status":"fact"},{"who":"UK government","when":"2008-10","what":"Recapitalised major banks, taking large stakes in the Royal Bank of Scotland and in Lloyds TSB and HBOS (merged as Lloyds Banking Group in January 2009), and offered state backing for new bank borrowing to restore their access to funding.","status":"fact"},{"who":"US Congress and President Barack Obama","when":"2009-02","what":"The American Recovery and Reinvestment Act provided tax cuts, support to state governments, extended unemployment benefits and infrastructure spending, aiming to raise aggregate demand and protect jobs.","status":"fact"},{"who":"G20 governments","when":"2009-04","what":"At the London summit, leaders agreed to increase IMF resources and coordinate stimulus, and committed to strengthen financial regulation, later including higher bank capital requirements under Basel III.","status":"fact"}],"stakeholders":[{"who":"Homeowners with mortgages","effect":"Many faced negative equity and foreclosure as prices fell, especially subprime borrowers whose payments reset higher; lost housing wealth reduced spending."},{"who":"Workers","effect":"Millions lost jobs as firms cut output; long-term unemployment rose sharply, and young people entering the labour market faced weak hiring for years."},{"who":"Bank shareholders and executives","effect":"Shareholders in failed or rescued banks lost much of their investment. Many executives kept pay earned in the boom years, fuelling public anger about who paid for the crisis."},{"who":"Taxpayers and governments","effect":"Took on large risks through rescues and stimulus; budget deficits and public debt rose sharply, shaping a decade of fiscal debate."},{"who":"Savers","effect":"Earned very low interest for years after central banks cut rates to near zero, while owners of bonds and shares gained as QE raised asset prices."},{"who":"Exporting emerging economies","effect":"Faced a sudden fall in world trade in late 2008 and capital outflows, though many recovered quickly, helped by their own stimulus, notably in China."}],"short":"In the short run the crisis froze credit markets and caused the sharpest contraction in output in rich countries since the 1930s. US real GDP fell by 2.6% in 2009 and unemployment roughly doubled. Share prices roughly halved from peak to trough. Inflation fell, and US consumer prices fell by 0.4% in 2009. Swift and large policy action stopped bank runs from spreading further, and output began to grow again in mid-2009.","long":"In the long run, recovery was slow in the United States and slower in much of Europe, where the crisis fed into the eurozone debt crisis. Output in many economies stayed below its pre-crisis trend. Central banks kept rates near zero for years and held large bond portfolios. Regulators raised capital and liquidity requirements for banks and created new powers to resolve failing firms. Public anger at bank rescues influenced politics, and economists rethought the role of finance in macroeconomics.","transmission":"The crisis spread through finance first. European banks had bought US mortgage securities and borrowed dollars short-term, so they shared the losses and the funding squeeze. After Lehman's failure, trust collapsed across money markets everywhere. Then trade transmitted the shock: orders for cars, machinery and electronics fell, hitting exporters such as Germany, Japan and South Korea. Capital fled to US Treasury bonds, so the dollar strengthened against many currencies. World GDP in current dollars fell from 64,072.3 billion in 2008 to 60,718.3 billion in 2009.","winners":[{"t":"Holders of US government bonds, whose prices rose as investors sought safety and interest rates fell.","status":"fact"},{"t":"Banks that survived, which acquired failed rivals at low prices, such as JPMorgan Chase with Bear Stearns.","status":"fact"},{"t":"Owners of financial assets in the following decade, as low interest rates and QE raised share and bond prices.","status":"interpretation"}],"losers":[{"t":"Workers who lost jobs, especially those without degrees and young people entering the labour market.","status":"fact"},{"t":"Households that lost their homes to foreclosure or fell into negative equity.","status":"fact"},{"t":"Shareholders and many creditors of Lehman Brothers and other failed firms.","status":"fact"},{"t":"Taxpayers in economies where bank rescues turned out to be very costly, such as Ireland and Iceland.","status":"fact"}],"unintended":[{"t":"Rescuing large financial firms may have strengthened the belief that some firms are too big to fail, encouraging future risk-taking (moral hazard).","status":"controversy"},{"t":"Years of very low interest rates and QE raised the prices of assets mostly held by richer households, which some economists argue widened wealth inequality.","status":"controversy"},{"t":"Rising public debt after rescues and stimulus helped prompt fiscal austerity from 2010 in the UK and parts of Europe, which many economists argue slowed recovery.","status":"controversy"}],"interpretations":[{"view":"Keynesian and credit-channel view","p":"Many economists, including Ben Bernanke drawing on his research on the 1930s, stress that the banking panic disrupted credit and cut aggregate demand. On this reading, rapid liquidity support, near-zero rates, QE and fiscal stimulus prevented a second Great Depression, and austerity from 2010 came too early.","status":"interpretation"},{"view":"Monetary policy too loose (John Taylor)","p":"John Taylor argued that the Fed kept rates well below the level implied by his policy rule in 2002–04, fuelling the housing boom. Bernanke and others replied that house prices also rose in countries with tighter policy and that lending standards mattered more.","status":"controversy"},{"view":"Financial instability (Hyman Minsky)","p":"Followers of Minsky argue that long periods of stability encourage borrowers and lenders to take on more risk, so the system moves from cautious to speculative finance until a fall in asset prices triggers forced selling. The crisis is often described as a Minsky moment.","status":"interpretation"},{"view":"Global saving glut and imbalances","p":"Another view, set out by Bernanke in 2005, links low long-term interest rates to large saving surpluses in Asia and oil exporters flowing into US assets. Critics reply that gross flows, especially through European banks, mattered more than net current account balances.","status":"controversy"}],"explain":["The AD/AS model explains how falls in investment, consumption and exports shifted AD left, reducing real output and raising cyclical unemployment.","The Keynesian multiplier explains why an initial fall in spending caused a larger fall in national income, and why fiscal stimulus could offset part of it.","Asymmetric information and moral hazard explain why securitised lending allowed poor-quality loans to be made and sold on."],"miss":["Many pre-crisis macroeconomic models had no banks or financial sector, so they could not show how a run on short-term funding could cause a deep recession.","Standard models assume that cutting interest rates boosts spending; they miss the zero lower bound and the weak response of borrowers repairing their balance sheets.","Models that treat risk as independent across loans missed how a national fall in house prices would cause defaults to rise everywhere at once."],"differently":[{"t":"Regulators could have required more capital and liquid assets of banks and of the shadow banking system, and checked lending standards, before 2007. Critics note that rules can push risk into less regulated corners.","status":"interpretation"},{"t":"Lehman Brothers might have been rescued or wound down in an orderly way. US officials said they lacked legal authority to lend without adequate collateral; others argue a way could have been found.","status":"controversy"},{"t":"More of the rescue effort could have gone to reducing household mortgage debt, which some economists argue would have sped up the recovery of consumer spending. Others warn that this raises fairness questions about helping those who borrowed most.","status":"controversy"}],"whatif":{"q":"Suppose central banks and governments had not intervened in late 2008, letting troubled banks fail. What is the most plausible outcome?","options":["A deeper collapse in credit and output, closer to the 1930s, although future risk-taking might have been lower","A quick recovery, because failed banks would be replaced at once","Higher inflation, because bank failures increase the money supply"],"best":0,"explain":"The 1930s suggest that widespread bank failures shrink the money supply and credit, deepening recessions. Most economists therefore expect that non-intervention would have produced a much deeper slump. However, we cannot observe the counterfactual, and some argue that letting more firms fail would have reduced moral hazard and the long-run costs of too big to fail."},"compare":[{"id":"great-depression","similar":"Both began with asset busts in the United States, spread through banking panics and the international financial system, and caused deep falls in output and employment across many countries.","different":"In the 1930s the money supply collapsed and policy stayed tight under the gold standard. In 2008 central banks expanded their balance sheets quickly and governments used fiscal stimulus.","dominant":"Depression: monetary contraction, bank failures and gold-standard constraints. GFC: a run on shadow banking and short-term funding, contained by aggressive monetary and fiscal policy."},{"id":"dotcom-2000","similar":"Both followed long rises in asset prices driven by optimism and cheap finance, and both were met with sharp cuts in US interest rates by the Federal Reserve.","different":"Dot-com losses fell mainly on shareholders and the banks stayed sound. Housing losses were concentrated in leveraged banks and shadow banks, so the credit system itself broke down.","dominant":"Dot-com: a wealth and investment shock. GFC: a leveraged credit boom whose bust froze lending and amplified the fall in AD."},{"id":"eurozone-2010","similar":"The eurozone crisis grew partly out of the GFC: bank losses, recession and rescues raised public debt, and markets began to doubt some governments' ability to repay.","different":"The US could rely on its own central bank and currency. Eurozone members lacked national monetary policy and exchange rates, so banking and sovereign problems reinforced each other.","dominant":"GFC: a private-sector credit boom and banking collapse. Eurozone: a self-reinforcing loop between sovereign debt and weak banks inside a monetary union."}],"ib":{"subs":["3.2","3.5","3.6","2.10","4.5"],"kc":["Interdependence","Intervention","Economic well-being","Change"],"note":"The crisis gives students a single case for analysing AD shocks, monetary and fiscal policy and, for HL students, asymmetric information (2.10 is HL only; guide PDF p. 26), and for evaluating the effectiveness and side effects of intervention."},"cambridge":{"topics":["aggregate demand","the business cycle","monetary policy","fiscal policy","the role of banks","market failure and asymmetric information"],"note":"Useful for evaluating the effectiveness of monetary and fiscal policy in a deep recession and for discussing the regulation of financial markets."},"university":{"fields":["monetary economics","financial economics","macroeconomics","economic history"],"note":"A university course would add models of bank runs and liquidity, the zero lower bound and unconventional monetary policy, and macroeconomic models with financial frictions and leverage."},"civil":{"themes":["financial stability","monetary policy","fiscal policy","banking regulation","external sector"],"note":"India faced capital outflows, rupee depreciation and slower growth in 2008–09, and responded with rate cuts, liquidity support and fiscal stimulus, a useful comparison with advanced economies."},"economists":["keynes","friedman","hayek","stiglitz"],"causal":["stimulus","unemployment","growth","ratehike"],"concepts":["Asymmetric information","Moral hazard","Adverse selection","Recession","Deflationary gap","Cyclical unemployment","Monetary policy","Quantitative easing","Fiscal policy","Expansionary policy","Budget deficit","National debt","Keynesian multiplier","Automatic stabiliser","Wealth"],"cases":["MAC-013","MAC-014","MAC-007"],"policies":["Interest-rate cuts","Lender-of-last-resort lending","Quantitative easing","Bank recapitalisation","Fiscal stimulus","Higher capital requirements (Basel III)","Bank stress tests"],"questions":[{"q":"Explain how a fall in house prices can lead to a fall in bank lending.","kind":"explain"},{"q":"Using an AD/AS diagram, analyse the effect of the 2008 credit crunch on real GDP and unemployment in the United States.","kind":"analyse"},{"q":"Evaluate the effectiveness of quantitative easing as a response to the global financial crisis.","kind":"evaluate"},{"q":"Using the quarterly GDP and annual unemployment data, explain why unemployment kept rising after the recession officially ended in June 2009.","kind":"data"},{"q":"Compare the policy responses to the global financial crisis and to the Great Depression.","kind":"compare"}],"retrieval":[{"q":"When did Lehman Brothers file for bankruptcy?","a":"15 September 2008."},{"q":"What is securitisation?","a":"Pooling loans such as mortgages and selling securities that pay investors from the loans' repayments."},{"q":"What is quantitative easing?","a":"Large-scale central bank purchases of bonds or other assets, financed by creating central bank money, to lower long-term interest rates."},{"q":"What was the Troubled Asset Relief Program used for mainly?","a":"Injecting capital into banks and supporting the car industry, rather than buying troubled assets as first planned."},{"q":"What happened on 9 August 2007?","a":"BNP Paribas froze three funds holding US mortgage assets, and interbank lending markets seized up."}],"reflection":"Bank rescues in 2008 probably prevented a deeper slump, yet they also protected some of the people who caused the crisis; how would you weigh efficiency against equity in that choice?","reading":[{"t":"Adam Tooze, Crashed: How a Decade of Financial Crises Changed the World, 2018","note":"A global history that explains the role of European banks and dollar funding."},{"t":"Ben S. Bernanke, The Courage to Act, 2015","note":"The Fed chairman's own account of decisions during the crisis; read critically as an insider's view."},{"t":"Atif Mian and Amir Sufi, House of Debt, 2014","note":"Argues that household debt and falling house prices explain much of the depth of the recession."},{"t":"Carmen M. Reinhart and Kenneth S. Rogoff, This Time Is Different, 2009","note":"Places the crisis in eight centuries of financial crises and shows how often booms end in busts."}],"numbers":[{"value":"1%; seventeen; 5.25%","claim":"Fed policy rate 2003–04, number of increases 2004–06 and the June 2006 level","basis":"FOMC decisions, June 2003 to June 2006."},{"value":"roughly doubled","claim":"Rise in US house prices from the late 1990s to the 2006 peak","basis":"S&P/Case–Shiller US National Home Price Index, nominal."},{"value":"three","claim":"Number of funds frozen by BNP Paribas on 9 August 2007","basis":"BNP Paribas announcement, 9 August 2007."},{"value":"0 to 0.25%","claim":"Fed target range from December 2008","basis":"FOMC statement, 16 December 2008."},{"value":"up to 700 billion dollars","claim":"TARP authorisation, October 2008","basis":"Emergency Economic Stabilization Act of 2008."},{"value":"roughly 800 billion dollars","claim":"Size of the American Recovery and Reinvestment Act, February 2009","basis":"Congressional Budget Office estimate of about $787 billion at enactment."},{"value":"December 2007 to June 2009","claim":"US recession dates","basis":"NBER Business Cycle Dating Committee."},{"value":"roughly halved","claim":"Fall in the S&P 500 from peak to trough","basis":"Catalogue monthly averages: 1,539.66 (October 2007) to 757.13 (March 2009)."}]},{"id":"eurozone-2010","title":"The euro area sovereign debt crisis","years":"2009–2015","start":"2009-10","end":"2015-08","region":"Euro area: Greece, Ireland, Portugal, Spain, Italy","kind":"crisis","standfirst":"Between 2009 and 2015, several euro-area governments lost access to borrowing at affordable rates, and their economies went through deep and long recessions. The crisis tested whether a single currency could work without a common budget, a common banking system or a lender of last resort for governments.","question":"Why did a debt problem in one small economy grow into a crisis that threatened the euro itself, and why was recovery in the hardest-hit countries so slow?","before":{"p":"The euro began in 1999, and Greece joined in 2001. Membership removed exchange-rate risk inside the area, and the bond yields of southern members fell close to Germany’s. Cheap credit flowed from the core to the periphery: into housing in Ireland and Spain, and into government and household borrowing in Greece and Portugal. Wages and prices in these economies rose faster than in Germany, eroding competitiveness, and large current account deficits opened. With one interest rate for all members, the ECB could not tighten for the booming periphery alone. When the 2008 financial crisis struck, both banks and governments in these countries were exposed.","facts":[{"t":"The euro was launched on 1 January 1999 by eleven countries; Greece joined in 2001, and euro notes and coins entered circulation in 2002.","status":"fact"},{"t":"The Maastricht Treaty set reference values of 3% of GDP for budget deficits and 60% of GDP for government debt, later backed by the Stability and Growth Pact.","status":"fact"},{"t":"Spain and Ireland ran budget surpluses in the years just before 2008; their vulnerabilities lay mainly in private borrowing and property-lending banks, not in public debt.","status":"fact"},{"t":"In September 2008 the Irish government took on responsibility for the liabilities of its main banks, tying the state’s finances to large banking losses.","status":"fact"}]},"trigger":{"p":"In October 2009 Greece’s newly elected government revealed that the budget deficit would be far larger than previously reported, at more than 12% of GDP, and the figures were later revised higher still. Rating agencies downgraded Greek debt and investors began to doubt that Greece could repay. Because Greece could neither devalue nor create its own currency, rising bond yields fed straight into the cost of rolling over its debts. By spring 2010 it could no longer borrow on acceptable terms.","status":"fact"},"timeline":[{"d":"2009-10","t":"Greek deficit revised sharply upwards","detail":"A new Greek government announces that the deficit is far larger than previously reported. Downgrades follow, and the yield gap between Greek and German government bonds starts to widen rapidly.","status":"fact"},{"d":"2010-05","t":"First Greek rescue programme","detail":"Euro-area governments and the IMF agree loans of €110 billion to Greece, conditional on spending cuts, tax rises and structural reforms monitored by the Commission, the ECB and the IMF, later known as the troika.","status":"fact"},{"d":"2010-05","t":"Rescue fund and ECB bond buying","detail":"Governments create a temporary rescue fund, the European Financial Stability Facility, and the ECB begins buying government bonds in secondary markets through its Securities Markets Programme to calm markets.","status":"fact"},{"d":"2010-11","t":"Ireland receives a programme","detail":"Overwhelmed by the cost of supporting its banks, Ireland agrees an €85 billion EU–IMF programme. The crisis is shown to be about banks and private debt as well as public borrowing.","status":"fact"},{"d":"2011-05","t":"Portugal receives a programme","detail":"Portugal, with slow growth and rising borrowing costs, agrees a €78 billion EU–IMF programme with conditions on fiscal consolidation and reforms to labour and product markets.","status":"fact"},{"d":"2011-07","t":"ECB raises interest rates again","detail":"Under Jean-Claude Trichet, the ECB raises its main rate for the second time in 2011, citing inflation risks. Critics argue this tightened conditions just as the crisis spread to Spain and Italy.","status":"fact"},{"d":"2011-12","t":"Draghi’s ECB offers three-year loans","detail":"Mario Draghi, ECB President since November, reverses the 2011 rate rises and offers banks unlimited three-year loans, easing bank funding stress; Italy has already replaced its government amid soaring borrowing costs.","status":"fact"},{"d":"2012-03","t":"Greek debt restructured","detail":"Private holders of Greek government bonds accept losses of more than half the face value in an exchange that accompanies a second official programme, the largest sovereign restructuring of its kind to that date.","status":"fact"},{"d":"2012-07","t":"Spain’s banks aided; Draghi’s pledge","detail":"Euro-area ministers agree up to €100 billion for Spain’s banks. Days later, in London, Draghi says the ECB is ready to do “whatever it takes”, within its mandate, to preserve the euro.","status":"fact"},{"d":"2012-09","t":"Outright Monetary Transactions announced","detail":"The ECB offers potentially unlimited purchases of short-term bonds of countries that accept a rescue programme. Yields in Spain and Italy fall, although the scheme is not used.","status":"fact"},{"d":"2015-01","t":"ECB launches quantitative easing","detail":"With inflation near zero and a negative deposit rate already in place since June 2014, the ECB announces large-scale purchases of government bonds, beginning in March 2015.","status":"fact"},{"d":"2015-07","t":"Greek referendum and third programme","detail":"After banks closed and capital controls began on 29 June, Greek voters reject creditors’ terms in a referendum. Within weeks the government accepts a third programme, agreed in August 2015, to stay in the euro.","status":"fact"}],"actors":[{"who":"Greek governments (Papandreou, Papademos, Samaras, Tsipras)","role":"Negotiated successive programmes with creditors, carried out deep spending cuts and tax rises, and in 2015 tested, then accepted, creditors’ terms after a referendum."},{"who":"European Central Bank (Trichet, then Draghi)","role":"Supplied liquidity to banks, bought bonds, raised rates in 2011, then cut them, and in 2012 pledged to act as a backstop through Outright Monetary Transactions."},{"who":"The troika: European Commission, ECB and IMF","role":"Designed and monitored the conditions attached to rescue loans for Greece, Ireland, Portugal and Cyprus, including fiscal targets and structural reforms."},{"who":"German government (Chancellor Angela Merkel)","role":"As the largest creditor country, insisted on strict conditions and fiscal rules in return for support, while ultimately agreeing to new permanent rescue funds."},{"who":"Bond investors and banks","role":"Their reassessment of default and redenomination risk drove the sharp rise in yields; banks’ large holdings of their own governments’ bonds linked sovereign and banking stress."}],"changed":"Countries that had borrowed freely in the 2000s faced a sudden stop: private capital left, and official loans replaced it. Governments cut spending and raised taxes while output fell, so unemployment rose to levels not seen in decades. Wages and prices adjusted slowly downwards, an internal devaluation. The euro area built institutions it had lacked at birth: a permanent rescue fund, joint bank supervision and a central bank willing to act as a backstop for government bond markets. Public attitudes to the euro and to austerity hardened in both creditor and debtor countries.","predict":{"q":"Greece could not devalue while it used the euro. If it needed to regain competitiveness against its euro partners, what would you expect to happen to its price level?","options":["Prices fall or rise more slowly than partners’: an internal devaluation","Prices rise faster, because the government prints money","No change, because the ECB fixes Greek prices"],"answer":0,"explain":"Without a national currency, the only way to lower the real exchange rate is for domestic wages and prices to fall relative to partners’. This usually happens through high unemployment and weak demand, which is slow and painful. Greek consumer prices fell by 0.9% in 2013, 1.3% in 2014 and 1.7% in 2015."},"mechanism":["Euro entry removes currency risk → periphery borrowing costs fall → credit-financed boom shifts AD right in Greece, Ireland, Spain and Portugal","Wages and prices rise faster than in Germany at a fixed nominal exchange rate → real exchange rate appreciates → exports lose competitiveness → current account deficits widen","2008–09 recession and bank losses → tax revenue falls while spending and bank support rise → public debt jumps (the sovereign–bank loop)","Investors doubt repayment → bond yields rise → higher refinancing costs worsen deficits → doubts grow further, a self-reinforcing spiral when no national central bank can act as backstop","Austerity cuts government spending and raises taxes → AD shifts left → real GDP falls → the debt-to-GDP ratio can rise in the short run even as borrowing is cut","No devaluation possible → adjustment through falling wages and prices (internal devaluation) → competitiveness returns slowly, with high unemployment meanwhile","ECB commitment to buy bonds (Outright Monetary Transactions) → fear of default or exit falls → yields drop without bonds needing to be bought"],"charts":[{"panel":"gdp","entities":["GRC","PRT","IRL"],"from":"2005","to":"2019","title":"GDP in current US$ billions: Greece, Portugal, Ireland","look":"Greek GDP fell from 355.9 in 2008 to 195.7 in 2015. Part of that fall reflects a weaker euro against the dollar; Ireland’s jump in 2015 reflects multinational accounting, not a sudden boom.","marks":[{"at":"2010","label":"First Greek programme"},{"at":"2012","label":"Greek debt restructured"},{"at":"2015","label":"Third Greek programme"}]},{"panel":"infl","entities":["GRC","IRL","ESP","DEU"],"from":"2006","to":"2019","title":"Consumer-price inflation: Greece, Ireland, Spain, Germany","look":"Look for internal devaluation: Ireland’s prices fell 4.4% in 2009, and Greek inflation was negative from 2013 to 2016, while Germany’s stayed positive. Falling relative prices restore competitiveness, slowly.","marks":[{"at":"2010","label":"Austerity programmes begin"},{"at":"2015","label":"ECB starts QE"}]},{"series":"fx-euro","from":"2008","to":"2017","title":"Euros per US dollar, 2008–2017","look":"Despite the crisis, the euro did not collapse. The bigger move came with negative rates and quantitative easing: the annual average rose from 0.75 euros per dollar in 2014 to 0.90 in 2015, a weaker euro.","marks":[{"at":"2012-07","label":"Draghi’s pledge"},{"at":"2015-01","label":"QE announced"}]},{"series":"uk10y","from":"2007","to":"2016","title":"UK 10-year government bond yield, 2007–2016","look":"A comparison outside the euro: the UK also ran large deficits, yet its yield fell from 3.62% in 2010 to 1.92% in 2012. One explanation is that it borrowed in a currency its own central bank issues.","marks":[{"at":"2010","label":"Greek crisis erupts"},{"at":"2012","label":"Euro crisis peak"}]}],"diagrams":[{"dg":"defgap","how":"Draw AD–AS for Greece. Shift AD left as government spending falls, taxes rise and confidence collapses, opening a deflationary gap: real GDP falls below full employment output and the price level comes under downward pressure. Then show SRAS shifting right only slowly as wages fall."},{"dg":"adas","how":"Draw the counterfactual with a national currency. A devaluation raises net exports, shifting AD right and closing part of the gap faster, but it also raises import prices. Compare this with the slow internal-devaluation route that euro membership required."}],"policy":[{"who":"Euro-area governments and the IMF","when":"2010-05","what":"Agreed the first Greek programme of €110 billion, conditional on fiscal consolidation, privatisation and structural reforms, followed by programmes for Ireland in 2010 and Portugal in 2011.","status":"fact"},{"who":"Euro-area governments","when":"2012-10","what":"Replaced the temporary rescue facility with the permanent European Stability Mechanism, able to lend to member governments under strict conditions; a treaty tightening national budget rules was signed in March 2012.","status":"fact"},{"who":"European Central Bank","when":"2011-12","what":"Offered banks unlimited three-year loans in December 2011 and February 2012, totalling about €1 trillion, easing bank funding strain, although many banks used the funds to buy their own governments’ bonds.","status":"fact"},{"who":"European Central Bank","when":"2012-09","what":"Announced Outright Monetary Transactions: potentially unlimited purchases of bonds of countries in a rescue programme. The commitment alone helped lower yields in Spain and Italy.","status":"fact"},{"who":"European Central Bank","when":"2015-01","what":"Announced large-scale purchases of government bonds, following a negative deposit rate from June 2014, to counter very low inflation and to lower borrowing costs across the euro area.","status":"fact"},{"who":"EU institutions","when":"2014-11","what":"Began banking union: the ECB took over direct supervision of the largest euro-area banks, aiming to weaken the link between national governments and their banking systems.","status":"fact"}],"stakeholders":[{"who":"Greek workers and households","effect":"Suffered deep falls in income, pensions and public services; unemployment rose above a quarter of the labour force in 2013, and many young graduates emigrated."},{"who":"Young people in Spain and Greece","effect":"Youth unemployment rose above 50% in both countries, damaging early careers and raising concerns about lasting losses of skills and earnings."},{"who":"Taxpayers in creditor countries","effect":"Their governments lent large sums through the rescue funds, exposing them to losses if programmes failed, which fed political resistance to further support."},{"who":"Private holders of Greek bonds","effect":"Accepted losses of more than half the face value in 2012; banks in Greece and Cyprus with large holdings suffered heavily as a result."},{"who":"German exporters","effect":"Benefited from a euro that was arguably weaker than a stand-alone Deutsche Mark would have been, especially as the crisis and later ECB easing weakened the euro."}],"short":"In the short run, rescue programmes prevented disorderly defaults, but the required fiscal consolidation took place during recession. Output fell sharply in Greece, Portugal, Spain and Ireland, and unemployment soared. Bond yields rose in Spain and Italy, threatening economies too large to rescue with the funds available, until the ECB’s 2012 pledge calmed markets. Banks in weak countries lost deposits and funding, and credit to firms tightened. Greece came close to leaving the euro in 2012 and again in 2015.","long":"In the long run, Ireland, Portugal and Spain returned to growth and to market borrowing, helped by recovering exports and ECB support. Greece suffered one of the deepest peacetime contractions recorded in an advanced economy, losing about a quarter of its output, and left its last programme only in 2018. The euro area emerged with new institutions: a permanent rescue fund, joint bank supervision and an ECB willing to act as a backstop. The case for a common budget remained contested.","transmission":"The crisis spread less through trade than through finance and expectations. Investors who saw Greece restructure asked whether Portugal, Spain or Italy might follow, so yields rose together. Banks across Europe held periphery government bonds, linking each government’s solvency to banks elsewhere. Weak banks cut lending, weakening growth and tax revenue further. Outside the euro area, the effects came mainly through slower European demand and financial-market volatility. Countries borrowing in their own currencies, such as the UK, saw yields fall instead.","winners":[{"t":"Germany and other core governments, whose borrowing costs fell as investors moved into what they saw as safe assets.","status":"fact"},{"t":"Euro-area exporters, which gained from a weaker euro after 2014.","status":"inference"},{"t":"Investors who bought periphery bonds at very high yields before the ECB’s 2012 pledge, as prices then recovered.","status":"inference"}],"losers":[{"t":"Greek households, who saw large falls in income, employment and public services over several years.","status":"fact"},{"t":"Young workers in Spain, Greece and Portugal, who faced very high unemployment at the start of their careers.","status":"fact"},{"t":"Private holders of Greek government bonds, who took losses in the 2012 restructuring.","status":"fact"}],"unintended":[{"t":"Fiscal consolidation during recession reduced output by more than many official forecasts expected, so debt-to-GDP ratios in some countries kept rising despite spending cuts.","status":"interpretation"},{"t":"Cheap long-term ECB loans were partly used by banks to buy their own governments’ bonds, deepening the link between banks and sovereigns.","status":"fact"},{"t":"Support grew for anti-austerity and euro-sceptic parties in both debtor and creditor countries, complicating later negotiations.","status":"fact"}],"interpretations":[{"view":"The fiscal-discipline view","p":"Associated with many policymakers in creditor countries, this view holds that the crisis came from governments breaking budget rules, so the remedy was consolidation and stricter enforcement. It fits Greece well. It fits Ireland and Spain poorly, since both had low public debt before 2008 and their problems began in banks.","status":"interpretation"},{"view":"The sudden-stop or balance-of-payments view","p":"Economists including Richard Baldwin and Francesco Giavazzi argue that the root problem was large capital flows from core to periphery that financed current account deficits. When those flows stopped abruptly, the debtors faced a crisis whatever their budget positions, much as in classic emerging-market crises.","status":"interpretation"},{"view":"The fragile-union view","p":"Paul De Grauwe argued that members of a monetary union borrow in a currency they cannot create, so markets can push them into default through a self-fulfilling loss of confidence. On this view, the ECB’s 2012 pledge worked because it removed the bad equilibrium.","status":"interpretation"},{"view":"The austerity debate","p":"IMF economists Olivier Blanchard and Daniel Leigh found in 2013 that forecasters had underestimated fiscal multipliers during the crisis, implying austerity was more damaging than expected. Others argue consolidation was unavoidable once markets closed, and point to the recoveries in Ireland and Portugal.","status":"controversy"}],"explain":["Optimum currency area theory predicts that a shared currency is costly when members face different shocks and lack labour mobility or fiscal transfers.","The AD–AS model shows how cutting government spending during recession shifts AD left, deepening the fall in output and employment.","The multiplier explains why cuts in government spending can reduce GDP by more than the cut itself, especially when interest rates cannot fall.","Real exchange rate analysis explains how faster wage growth at a fixed nominal rate eroded competitiveness in the periphery."],"miss":["Simple models struggle with self-fulfilling crises, where expectations of default raise yields enough to make default more likely.","Standard textbook models often leave out banks, yet the link between banks and their governments was central to how the crisis spread.","Before the crisis, many models treated capital flows within a currency union as benign, underplaying the risk of sudden stops.","Models say little about the politics of creditor and debtor countries, which shaped the timing and conditions of every rescue."],"differently":[{"t":"Restructuring Greek debt in 2010 rather than 2012 might have reduced the austerity required and the losses that later fell on official lenders. An IMF review in 2013 suggested restructuring should have been considered earlier; European governments disputed parts of that review.","status":"controversy"},{"t":"The ECB could have avoided its 2011 rate rises and acted as a backstop for government bonds earlier, as it did in 2012, possibly limiting contagion to Spain and Italy.","status":"interpretation"},{"t":"Slower fiscal consolidation, combined with stronger demand in surplus countries such as Germany, would have spread the burden of adjustment more evenly, though creditors worried this would weaken pressure for reform.","status":"controversy"}],"whatif":{"q":"Suppose Greece had left the euro in 2015 and reintroduced a national currency. What would most likely have followed in the short run?","options":["A sharp depreciation, banking stress and dearer imports, with uncertain gains in competitiveness later","A quick and painless return to strong growth","A stronger currency and lower inflation"],"best":0,"explain":"A new currency would probably have fallen sharply, raising import prices and the burden of any debts still owed in euros. Depositors would have rushed to withdraw euros, so banks would have needed stronger controls. Over time, a cheaper currency could have helped exports and tourism, but the outcome depends on credibility and policy, which is why economists disagree about whether exit would have been better."},"compare":[{"id":"asia-1997","similar":"Both crises followed large capital inflows that financed booms and current account deficits, then reversed suddenly, forcing deep recessions and IMF-backed programmes with strict conditions.","different":"Asian countries had their own currencies, which collapsed, boosting exports later; euro members could not devalue and had to adjust through falling wages and prices instead.","dominant":"In 1997, currency collapse and foreign-currency debt dominated; in the euro crisis, the lack of a devaluation option and the sovereign–bank loop dominated."},{"id":"gfc-2008","similar":"The euro crisis grew directly out of the financial crisis: bank losses and recession turned private debt problems into public ones, especially in Ireland and Spain.","different":"The 2008 crisis centred on US mortgage markets and global banks; the euro crisis centred on government debt and the institutional design of a monetary union.","dominant":"In 2008, a banking panic and credit collapse dominated; in 2010–12, doubts about sovereign solvency inside a currency union dominated."},{"id":"great-depression","similar":"Many historians compare the euro to the interwar gold standard: fixed exchange rates forced deficit countries to deflate, while surplus countries faced little pressure to adjust.","different":"In the 1930s countries could leave gold, and recovery tended to follow exit; in the euro crisis no country left, and new institutions were built instead.","dominant":"In the 1930s, monetary contraction under gold dominated; in the euro crisis, the absence of national monetary and exchange-rate tools dominated."}],"ib":{"subs":["4.4","4.5","3.6","3.5","3.3"],"kc":["Interdependence","Intervention","Equity","Change"],"note":"The event supports evaluation of monetary union, the costs of fiscal consolidation during recession, and the limits of monetary policy when a country shares a central bank, with data suitable for Paper 1 and Paper 2 responses."},"cambridge":{"topics":["economic integration and monetary union","fiscal policy and government debt","exchange rate systems","unemployment","deflation"],"note":"A strong illustration of the costs and benefits of a single currency and of the trade-offs in reducing a budget deficit."},"university":{"fields":["international macroeconomics","public finance","monetary economics","European economic integration"],"note":"A university course would use optimum currency area theory, models of sovereign default with multiple equilibria, and the analysis of lenders of last resort and fiscal multipliers at the zero lower bound."},"civil":{"themes":["fiscal policy","public debt management","financial stability","regional integration"],"note":"Indian states, like euro members, borrow without controlling monetary policy or the exchange rate, so the crisis is a useful analogy for debates on state debt and fiscal rules, though India’s fiscal federalism differs."},"economists":["keynes","friedman","stiglitz"],"causal":["unemployment","growth","ratehike"],"concepts":["Monetary union","National debt","Budget deficit","Fiscal policy","Contractionary policy","Quantitative easing","Current account","Deflation","Moral hazard","Yield","Cyclical unemployment","Fixed exchange rate","Central bank"],"cases":["MAC-019","GLO-019","MAC-020","MAC-044","MAC-032","MAC-051","GLO-018"],"policies":["Conditional rescue loans","Fiscal consolidation (austerity)","Structural reforms","Sovereign debt restructuring","Long-term refinancing operations","Outright Monetary Transactions","Negative interest rates","Quantitative easing","Banking union"],"questions":[{"q":"Explain why Greece could not use devaluation to restore competitiveness after 2010.","kind":"explain"},{"q":"Using an AD–AS diagram, analyse the likely short-run effects of fiscal consolidation on real GDP and unemployment in Greece.","kind":"analyse"},{"q":"Using the inflation chart, describe how Greek and German inflation differed between 2012 and 2016, and explain what this suggests about internal devaluation.","kind":"data"},{"q":"Evaluate the view that the euro area crisis was caused mainly by excessive government borrowing.","kind":"evaluate"},{"q":"Compare the adjustment of a euro member after a sudden stop with that of Thailand in 1997.","kind":"compare"}],"retrieval":[{"q":"What revelation in October 2009 triggered the Greek crisis?","a":"Greece’s new government announced a budget deficit far larger than previously reported, more than 12% of GDP."},{"q":"Which three institutions formed the troika?","a":"The European Commission, the European Central Bank and the International Monetary Fund."},{"q":"What did the ECB announce in September 2012?","a":"Outright Monetary Transactions: potentially unlimited purchases of bonds of countries in a rescue programme."},{"q":"What is internal devaluation?","a":"Restoring competitiveness by lowering domestic wages and prices relative to trading partners, instead of devaluing the currency."},{"q":"Why did Ireland need a rescue despite low public debt before 2008?","a":"Its government underwrote its banks’ liabilities in 2008, so their property-lending losses then transferred to the state."}],"reflection":"Should countries that share a currency also share a budget, and what would each side need to give up for that to work?","reading":[{"t":"Adam Tooze, Crashed: How a Decade of Financial Crises Changed the World, 2018","note":"Places the euro crisis within the wider story of the 2008 crisis and its aftermath."},{"t":"Ashoka Mody, EuroTragedy: A Drama in Nine Acts, 2018","note":"A critical history of the euro by a former IMF official involved in the crisis response."},{"t":"Joseph E. Stiglitz, The Euro: How a Common Currency Threatens the Future of Europe, 2016","note":"A strongly argued critique of the euro’s design and of austerity, best read alongside more sympathetic accounts."}],"numbers":[{"value":"more than 12% of GDP","claim":"Greek deficit announced in October 2009","basis":"Greek government revision, October 2009; later revised higher by Eurostat"},{"value":"3% and 60% of GDP","claim":"Maastricht reference values for deficit and debt","basis":"Maastricht Treaty protocol on the excessive deficit procedure"},{"value":"eleven","claim":"Founding members of the euro in 1999","basis":"Widely documented"},{"value":"€110 billion","claim":"First Greek programme, May 2010","basis":"Euro-area and IMF announcements"},{"value":"€85 billion","claim":"Irish EU–IMF programme, November 2010","basis":"EU–IMF announcement"},{"value":"€78 billion","claim":"Portuguese EU–IMF programme, May 2011","basis":"EU–IMF announcement"},{"value":"about €1 trillion","claim":"Combined take-up of the ECB’s two three-year LTROs","basis":"ECB allotments of December 2011 and February 2012"},{"value":"more than half the face value","claim":"Losses accepted by private holders of Greek bonds, 2012","basis":"Terms of the March 2012 private sector involvement"},{"value":"up to €100 billion","claim":"Support for Spanish banks, July 2012","basis":"Eurogroup agreement"},{"value":"above a quarter; about a quarter","claim":"Greek unemployment rate in 2013; fall in Greek real output from 2008 peak","basis":"ELSTAT and Eurostat data; widely documented"},{"value":"above 50%","claim":"Youth unemployment in Spain and Greece at the crisis peak","basis":"Eurostat data; widely documented"}]},{"id":"covid-2020","title":"The COVID-19 economic shock","years":"2020–2023","start":"2020-01","end":"2023","region":"Global","kind":"pandemic","standfirst":"In spring 2020, governments deliberately shut large parts of their economies to slow a virus, producing the sharpest fall in output in post-war records for many countries, followed by an unusually fast rebound. The policy response was larger and faster than in 2008, and economists still debate how far it contributed to the inflation of 2021–23.","question":"What kind of shock was the pandemic, a fall in demand, a fall in supply or both, and did the policy response cushion it at the cost of later inflation?","before":{"p":"In early 2020 the US economy was in its eleventh year of expansion. Unemployment had averaged 3.7% in 2019 and inflation 1.8%. Interest rates were low across advanced economies: the US 10-year Treasury yield averaged 2.14% in 2019, and the ECB’s deposit rate was already below zero, so central banks had little room to cut. Global supply chains were long and lean, designed to keep inventories small. Public debt in many countries was already high after the global financial crisis. No modern economy had planned to close workplaces, schools and borders all at once.","facts":[{"t":"US unemployment averaged 3.7% in 2019, its lowest annual average since 1969.","status":"fact"},{"t":"Chinese authorities placed Wuhan under lockdown on 23 January 2020.","status":"fact"},{"t":"The World Health Organization declared a public health emergency of international concern on 30 January 2020 and described the outbreak as a pandemic on 11 March 2020.","status":"fact"},{"t":"The US 10-year Treasury yield averaged 2.14% in 2019 and 0.89% in 2020.","status":"fact"}]},"trigger":{"p":"As the virus spread from China to Europe and North America in February and March 2020, governments imposed lockdowns and travel bans, and many people avoided contact voluntarily. Spending on travel, hospitality and personal services collapsed, many factories paused, and financial markets fell sharply: the S&P 500 averaged 3277.31 in February 2020 and 2652.39 in March. The shock was unusual because it came from public-health measures and fear of infection, not from a financial imbalance.","status":"fact"},"timeline":[{"d":"2020-01-23","t":"Wuhan placed under lockdown","detail":"China locks down a city of millions to contain the outbreak. Factory closures in China soon disrupt supplies of components to manufacturers around the world.","status":"fact"},{"d":"2020-03-11","t":"WHO describes a pandemic","detail":"The World Health Organization calls the outbreak a pandemic. Within days, many European countries and US states close schools, shops and offices.","status":"fact"},{"d":"2020-03-15","t":"Fed cuts rates to near zero","detail":"The Federal Reserve cuts its target range to 0–0.25% and restarts large-scale asset purchases; it soon adds lending facilities and wider dollar swap lines with other central banks.","status":"fact"},{"d":"2020-03-18","t":"ECB launches pandemic bond purchases","detail":"The ECB announces a €750 billion Pandemic Emergency Purchase Programme to keep borrowing costs low across euro-area governments and firms; it was later enlarged.","status":"fact"},{"d":"2020-03-20","t":"UK announces job retention scheme","detail":"The UK government offers to pay 80% of furloughed employees’ wages, up to £2,500 a month, so firms can keep staff on payroll. A national lockdown follows on 23 March.","status":"fact"},{"d":"2020-03-24","t":"India announces national lockdown","detail":"India announces a 21-day nationwide lockdown, later extended. Millions of informal and migrant workers lose earnings almost overnight, and many return to their home villages.","status":"fact"},{"d":"2020-03-27","t":"US CARES Act signed","detail":"A package of about $2.2 trillion provides direct payments to households, enlarged unemployment benefits and forgivable loans to small firms that keep workers on payroll.","status":"fact"},{"d":"2020-04-20","t":"US oil futures turn negative","detail":"With demand collapsing and storage nearly full, a US crude oil futures contract briefly trades below zero, a sign of how abruptly transport and industrial demand had stopped.","status":"fact"},{"d":"2020-07","t":"EU agrees NextGenerationEU","detail":"EU leaders agree a €750 billion recovery package financed by joint EU borrowing, a step towards shared fiscal capacity that had been resisted during the euro crisis.","status":"fact"},{"d":"2020-12","t":"First vaccines authorised","detail":"The UK authorises the Pfizer–BioNTech vaccine for emergency use on 2 December, and other countries soon follow. Vaccination makes a lasting reopening of contact-intensive services possible during 2021.","status":"fact"},{"d":"2021-03","t":"American Rescue Plan enacted","detail":"A further US package of about $1.9 trillion adds household payments and support to state governments. Some economists warn that it is large relative to the remaining output gap.","status":"fact"},{"d":"2022-03","t":"Fed begins raising rates","detail":"With US inflation at four-decade highs and energy prices up after Russia’s invasion of Ukraine in February, the Fed starts a rapid series of rate rises that continues into 2023.","status":"fact"}],"actors":[{"who":"Federal Reserve (Chair Jerome Powell)","role":"Cut rates to near zero, bought government and mortgage bonds on a huge scale, backstopped credit markets in 2020, then raised rates rapidly from 2022 as inflation rose."},{"who":"US Congress and the Trump and Biden administrations","role":"Passed successive relief packages in 2020 and 2021 that replaced lost income on an unprecedented scale through payments, unemployment benefits and business loans."},{"who":"European Central Bank and EU leaders","role":"The ECB bought bonds through its pandemic programme; EU leaders suspended fiscal rules and agreed joint borrowing to fund recovery spending."},{"who":"UK Treasury and Bank of England","role":"The Treasury funded wage subsidies through the furlough scheme; the Bank cut its policy rate to 0.1% and expanded its bond purchases."},{"who":"Government of India and the Reserve Bank of India","role":"Imposed one of the strictest lockdowns, announced a relief and credit package, and the RBI cut its policy rate and allowed borrowers to defer loan repayments."}],"changed":"Within weeks, output in many economies fell further than in any post-war recession, but unlike 2008 the banking system held up and governments replaced much of the lost income. Spending shifted from services to goods and from offices to homes, while household savings rose because there was less to buy. Remote work, online retail and digital payments grew quickly. Public debt rose steeply and central bank balance sheets expanded. When demand recovered faster than supply chains and energy markets could adjust, inflation in several advanced economies reached its highest rates in four decades.","predict":{"q":"In 2020, governments closed many businesses but also paid the wages of furloughed workers and sent payments to households. What would you expect to happen to US real GDP and unemployment in 2020, and then in 2021?","options":["A sharp fall in GDP then a fast rebound; unemployment up sharply then falling quickly","A long slump like the 1930s, with GDP falling for several years","Little change in either, because incomes were protected"],"answer":0,"explain":"US real GDP fell by 2.2% in 2020 and grew by 6.1% in 2021. Unemployment averaged 3.7% in 2019, 8.1% in 2020 and 5.3% in 2021. Within 2020 the swings were far larger: an annualised fall of 28.1% in the second quarter, then growth of 35.2% in the third, as lockdowns eased."},"mechanism":["Lockdowns and fear of infection → firms in contact-intensive sectors cannot produce and consumers cannot buy → SRAS and AD both shift left at once","Lost income in closed sectors → those workers cut spending on other goods → the multiplier spreads the demand shock beyond the sectors that were shut","Transfers, wage subsidies and loans → household income and firms’ cash flow are protected → AD shifts back right, and fewer firms fail or lay off workers permanently","Central bank rate cuts and asset purchases → lower borrowing costs and calmer financial markets → credit keeps flowing and asset prices recover","Reopening, accumulated savings and further stimulus → AD shifts right faster than supply recovers, with spending tilted towards goods → bottlenecks raise shipping and component costs","Energy and food price shock after Russia’s 2022 invasion of Ukraine → SRAS shifts left → cost-push inflation adds to demand-pull pressure","High inflation → central banks raise interest rates from 2021–22 → growth of AD slows → inflation falls back in 2023–24, a movement down the short-run Phillips curve with only a modest rise in unemployment"],"charts":[{"series":"us-gdp-q","from":"2019-01","to":"2021-10","title":"US real GDP growth by quarter (annualised), 2019–2021","look":"Quarterly growth is annualised, so a fall of 28.1% means output fell at that yearly pace for one quarter. Notice how the collapse and the rebound of 35.2% came in consecutive quarters.","marks":[{"at":"2020-04","label":"Lockdown quarter"},{"at":"2020-07","label":"Reopening rebound"}]},{"series":"us-unemp","from":"2007","to":"2024","title":"US unemployment rate, 2007–2024","look":"Compare the two recessions. After 2008, unemployment stayed above 8% for four years. After the pandemic jump to 8.1% in 2020, it was back to 3.6% by 2022, a much faster recovery.","marks":[{"at":"2009","label":"Financial crisis"},{"at":"2020","label":"Pandemic shock"}]},{"series":"us-cpi-infl","from":"2010","to":"2024","title":"US consumer-price inflation, 2010–2024","look":"Inflation rose from 1.2% in 2020 to 4.7% in 2021 and 8.0% in 2022, the highest for four decades, then eased to 4.1% in 2023 and 2.9% in 2024 as rates rose and supply recovered.","marks":[{"at":"2021","label":"Reopening and stimulus"},{"at":"2022","label":"Fed starts raising rates"}]},{"panel":"infl","entities":["USA","GBR","DEU","IND"],"from":"2015","to":"2024","title":"Consumer-price inflation: US, UK, Germany, India","look":"The 2022 surge was international: 8.0% in the US, 7.9% in the UK, 6.9% in Germany. A shared surge points to common causes such as energy prices and supply chains, not only national stimulus.","marks":[{"at":"2020","label":"Pandemic"},{"at":"2022","label":"Energy price shock"}]}],"diagrams":[{"dg":"adas","how":"For 2020, shift both SRAS and AD left. Real GDP falls sharply, while the price level changes little because the two shifts pull it in opposite directions. Then show fiscal and monetary support shifting AD partly back to the right."},{"dg":"costpush","how":"For 2021–22, shift SRAS left as energy, shipping and component costs rise, and shift AD right as economies reopen with extra savings and stimulus. Both raise the price level; the debate is about the relative size of each shift."}],"policy":[{"who":"Federal Reserve","when":"2020-03","what":"Cut its target range to 0–0.25%, began open-ended purchases of government and mortgage bonds, set up emergency lending facilities including support for corporate bond markets, and widened dollar swap lines with other central banks.","status":"fact"},{"who":"US Congress","when":"2020-03","what":"Passed the CARES Act, about $2.2 trillion, with direct payments, larger unemployment benefits and the Paycheck Protection Program; further packages followed in December 2020 and March 2021.","status":"fact"},{"who":"UK government and Bank of England","when":"2020-03","what":"The Coronavirus Job Retention Scheme paid 80% of furloughed workers’ wages up to £2,500 a month, running until September 2021; the Bank of England cut Bank Rate to 0.1%.","status":"fact"},{"who":"European Central Bank and EU","when":"2020-03","what":"The ECB launched its Pandemic Emergency Purchase Programme; the EU activated the escape clause in its fiscal rules and in July agreed NextGenerationEU, funded by joint borrowing.","status":"fact"},{"who":"Government of India and RBI","when":"2020-05","what":"Announced the Atmanirbhar Bharat package, largely made up of government-backed credit and liquidity support alongside food transfers, while the RBI cut its repo rate to 4% and allowed a moratorium on loan repayments.","status":"fact"},{"who":"Central banks in advanced economies","when":"2022","what":"Raised interest rates rapidly as inflation climbed: the Bank of England from December 2021, the Fed from March 2022 and the ECB from July 2022, in the fastest tightening for decades.","status":"fact"}],"stakeholders":[{"who":"Workers in hospitality, travel and personal services","effect":"Were the first to lose hours and jobs because their work required physical contact; many were low paid, young or on insecure contracts."},{"who":"Workers who could work from home","effect":"Mostly kept their jobs and incomes, while spending less on travel and leisure, so many built up savings during 2020–21."},{"who":"Owners of shares and property","effect":"Gained as interest rates fell and asset prices recovered quickly: the S&P 500 averaged 3695.31 in December 2020, above its February level."},{"who":"Informal and migrant workers in India","effect":"Lost earnings abruptly under the national lockdown and had little access to wage subsidies, relying mainly on food transfers and rural employment."},{"who":"Households facing the 2022 price surge","effect":"Saw real wages fall as prices of food and energy rose faster than pay, with the largest burden on lower-income households that spend more on essentials."}],"short":"In the short run, output fell at a pace not seen in post-war data, but the fall was brief. Income support kept household spending from collapsing and limited bankruptcies, so many firms reopened with their workforce intact. Unemployment in the United States jumped in spring 2020 and then fell quickly. Financial markets, after a sharp fall in March 2020, recovered within months because central banks acted as buyers and lenders of last resort. Countries with smaller fiscal space and large informal sectors had much less protection.","long":"In the long run, public debt rose substantially in most countries, narrowing room for future fiscal policy once interest rates rose. The inflation of 2021–23 ended the era of near-zero interest rates and tested central banks’ credibility. Some changes in work persisted, notably hybrid and remote working and greater use of digital services. Lost schooling may reduce the future productivity of some cohorts. Firms and governments began rethinking long supply chains, with more emphasis on resilience and stocks rather than minimum cost.","transmission":"The shock spread through several channels at once. The virus itself crossed borders, so lockdowns hit most countries within weeks of each other. Supply chains transmitted factory closures in one country to producers elsewhere. Collapsing travel hit tourism-dependent economies, and falling commodity prices hurt exporters. In March 2020 a scramble for dollars caused emerging-market currencies to fall until the Fed widened swap lines. Later, synchronised reopening and the 2022 energy shock pushed inflation up in many countries at the same time.","winners":[{"t":"Online retailers, technology and delivery firms, whose sales rose as spending moved online.","status":"inference"},{"t":"Holders of financial assets, as low interest rates and central bank purchases lifted share and bond prices after March 2020.","status":"fact"},{"t":"Borrowers with fixed-rate debt during the inflation of 2021–23, as rising prices reduced the real value of what they owed.","status":"inference"}],"losers":[{"t":"Low-paid workers in contact-intensive services, who lost jobs and hours first.","status":"fact"},{"t":"Children and students, whose schooling was interrupted for long periods in many countries.","status":"fact"},{"t":"Tourism-dependent and commodity-exporting developing economies, which lost income with limited room to borrow.","status":"fact"},{"t":"Savers and people on fixed incomes during 2021–23, whose purchasing power fell as inflation rose.","status":"inference"}],"unintended":[{"t":"Rapid recovery in asset prices while many low-paid workers lost income may have widened wealth inequality in several economies.","status":"inference"},{"t":"Large stimulus, combined with supply constraints and energy shocks, contributed to the 2021–23 inflation; how much each factor mattered is disputed.","status":"controversy"},{"t":"Loan schemes designed to be fast, such as the Paycheck Protection Program, reached some firms that did not need help and were open to fraud.","status":"fact"}],"interpretations":[{"view":"The “Keynesian supply shock” view","p":"Veronica Guerrieri, Guido Lorenzoni, Ludwig Straub and Iván Werning argued in 2020 that closing some sectors can reduce aggregate demand by more than the original supply loss, because workers in closed sectors cut spending elsewhere. On this view, income support was the right response to a supply shock.","status":"interpretation"},{"view":"The overheating warning","p":"In early 2021 Lawrence Summers and Olivier Blanchard warned that the American Rescue Plan was large relative to the remaining output gap and could raise inflation. Defenders argued that the risks of doing too little were greater, as after 2008. Later inflation lent support to the warning, but its exact contribution remains debated.","status":"controversy"},{"view":"The price-shock view","p":"Ben Bernanke and Olivier Blanchard, in a 2023 study, concluded that most of the early US inflation surge came from shocks to energy and food prices and from sectoral shortages, while tight labour markets became more important in keeping inflation high later.","status":"interpretation"},{"view":"The ‘transitory’ debate","p":"Critics argue that central banks were too slow to tighten in 2021 because they judged inflation temporary. Defenders reply that the supply shocks were genuinely unusual, that longer-term inflation expectations stayed fairly stable, and that inflation fell without a deep recession.","status":"controversy"}],"explain":["The AD–AS model shows how simultaneous leftward shifts of AD and SRAS produce a deep fall in real GDP with little change in the price level.","The multiplier and automatic stabilisers explain why replacing lost income limited the spread of the shock to sectors that stayed open.","Cost-push and demand-pull analysis together explain why the 2021–22 inflation appeared across many countries with different policies.","The Phillips curve helps explain why very tight labour markets in 2022 coincided with high inflation and rapid wage growth."],"miss":["Aggregate models treat the economy as one sector, yet the pandemic was highly uneven, with some sectors shut and others booming at the same time.","They have no built-in trade-off between economic activity and public health, which was the central policy choice in 2020.","Supply chains behaved non-linearly: small disruptions at bottlenecks such as ports and chips caused large price rises that simple models did not anticipate.","Standard models struggle with forced saving, where households save not by choice but because services are closed, then spend later."],"differently":[{"t":"Support could have been more closely targeted. US payments went to many households whose incomes had not fallen, while support for lower-income countries, including vaccine supply, was slower and smaller.","status":"interpretation"},{"t":"Central banks could have begun raising interest rates in 2021, when inflation first rose above target, which might have reduced peak inflation in 2022, although at the risk of slowing an incomplete recovery.","status":"controversy"},{"t":"Earlier investment in testing, contact tracing, public-health capacity and stockpiles of protective equipment might have allowed shorter or more targeted lockdowns, reducing the economic cost of controlling the virus, though how much is hard to judge.","status":"interpretation"}],"whatif":{"q":"Suppose governments had provided no income support or emergency loans in 2020. What would most likely have happened?","options":["A deeper recession with more bankruptcies and a slower recovery, but probably less inflation in 2021–22","A faster recovery, because markets would have adjusted on their own","Much the same outcome, because the virus decided everything"],"best":0,"explain":"Without support, lost incomes in closed sectors would have spread through the multiplier, and many viable firms would have failed, destroying jobs and relationships that take time to rebuild. Recovery would probably have been slower, as after 2008. Lower demand in 2021 would probably also have meant less inflation, so the counterfactual shows a trade-off rather than a free choice, and its scale is uncertain."},"compare":[{"id":"gfc-2008","similar":"Both were global recessions met by near-zero interest rates, quantitative easing and large fiscal packages, with central banks acting as lenders of last resort to calm financial markets.","different":"In 2008 the shock came from bank losses and debt, and recovery was slow; in 2020 banks held up, policy acted faster and recovery was much quicker.","dominant":"In 2008, a financial crisis and household debt repair dominated; in 2020, a non-financial health shock, cushioned by income replacement, dominated."},{"id":"great-depression","similar":"Both brought very sudden falls in output and employment across many countries at once, testing whether governments and central banks were willing to act quickly to support demand and incomes.","different":"In the 1930s policy was slow and often contractionary, and banks failed; in 2020 policy support was rapid and large, and the downturn lasted months, not years.","dominant":"In the Depression, monetary contraction and bank failures dominated; in 2020, the public-health shutdown dominated, and strong policy support limited lasting damage."},{"id":"stagflation-1970s","similar":"Both saw an energy price shock push up costs while central banks judged how hard to tighten, with debate about whether policy had been too loose.","different":"In the 1970s high inflation persisted for years as expectations rose and wages chased prices; in 2021–23 longer-term expectations stayed more stable and inflation fell back fairly quickly.","dominant":"In the 1970s, supply shocks plus unanchored expectations dominated; in 2021–23, a mix of reopening demand, supply bottlenecks and energy shocks dominated."}],"ib":{"subs":["3.1","3.2","3.3","3.5","3.6"],"kc":["Change","Intervention","Equity","Economic well-being"],"note":"The event shows simultaneous AD and SRAS shifts, fiscal and monetary policy at the limits of their tools, and a recent inflation episode, giving students current evidence for analysis and evaluation in Paper 1 and Paper 2."},"cambridge":{"topics":["aggregate demand and aggregate supply","fiscal policy","monetary policy","inflation","unemployment"],"note":"A recent case for comparing demand-side and supply-side shocks and for evaluating the effects and costs of large-scale stimulus."},"university":{"fields":["macroeconomics","monetary economics","public economics","health economics"],"note":"A university course would use multi-sector models in which supply shocks can cause demand shortfalls, and study the interaction of fiscal and monetary policy near the lower bound on interest rates."},"civil":{"themes":["fiscal policy","monetary policy and inflation","informal sector and social security","public health and the economy"],"note":"India’s strict lockdown fell heavily on informal and migrant workers, and its policy mix leaned on credit support and food transfers, which makes a useful comparison with wage-subsidy schemes elsewhere."},"economists":["keynes","friedman"],"causal":["stimulus","inflation","ratehike","unemployment"],"concepts":["Aggregate demand","Aggregate supply","Recession","Fiscal policy","Monetary policy","Quantitative easing","Automatic stabiliser","Budget deficit","National debt","Cost-push inflation","Demand-pull inflation","Cyclical unemployment","Transfer payment","Keynesian multiplier","Expansionary policy","Informal economy"],"cases":["MAC-015","MAC-024","MAC-043","MAC-016","MAC-041","MAC-012","MAC-021","MAC-002","GLO-042","MIC-036","MAC-039"],"policies":["Lockdowns and social distancing rules","Wage subsidies (furlough schemes)","Direct transfers to households","Government-backed business loans","Interest-rate cuts","Quantitative easing","Emergency lending facilities","Joint EU borrowing","Interest-rate rises (2022–23)"],"questions":[{"q":"Explain why the pandemic is often described as both a demand shock and a supply shock.","kind":"explain"},{"q":"Using an AD–AS diagram, analyse how wage-subsidy schemes affected real GDP and unemployment in 2020.","kind":"analyse"},{"q":"Using the US inflation and unemployment charts, describe the changes between 2019 and 2023 and suggest reasons for them.","kind":"data"},{"q":"Evaluate the view that expansionary fiscal policy was the main cause of high inflation in 2021–23.","kind":"evaluate"},{"q":"Compare the speed of recovery after the 2008 financial crisis with the recovery after the 2020 pandemic shock.","kind":"compare"}],"retrieval":[{"q":"To what range did the Federal Reserve cut its target rate in March 2020?","a":"0–0.25%."},{"q":"What share of furloughed workers’ wages did the UK job retention scheme pay?","a":"80%, up to £2,500 a month."},{"q":"What was NextGenerationEU?","a":"A €750 billion EU recovery package, agreed in July 2020, financed by joint EU borrowing."},{"q":"What were US consumer-price inflation rates in 2021 and 2022?","a":"4.7% in 2021 and 8.0% in 2022."},{"q":"Why did spending shift from services to goods in 2020?","a":"Contact-intensive services were closed or avoided, so households spent more on goods for use at home."}],"reflection":"Was the inflation of 2021–23 a price worth paying for the speed of the recovery, and who should decide that trade-off?","reading":[{"t":"Adam Tooze, Shutdown: How Covid Shook the World’s Economy, 2021","note":"A narrative history of the 2020 shock and the policy response across major economies."},{"t":"Ben S. Bernanke, 21st Century Monetary Policy, 2022","note":"A former Fed chair explains the tools used in 2008 and 2020, including asset purchases and lending facilities."},{"t":"International Monetary Fund, World Economic Outlook, April 2020","note":"The IMF’s early assessment of what it called the Great Lockdown, useful for seeing how forecasters judged the shock at the time."}],"numbers":[{"value":"eleventh year","claim":"Length of the US expansion by early 2020","basis":"NBER business-cycle dates: expansion from June 2009 to February 2020"},{"value":"0–0.25%","claim":"Fed target range from 15 March 2020","basis":"Federal Reserve statement, 15 March 2020"},{"value":"€750 billion","claim":"Initial size of the ECB’s Pandemic Emergency Purchase Programme","basis":"ECB announcement, 18 March 2020"},{"value":"80%, up to £2,500 a month","claim":"UK furlough scheme support","basis":"UK government announcement, 20 March 2020"},{"value":"21 days","claim":"Initial length of India’s national lockdown","basis":"Government of India announcement, 24 March 2020"},{"value":"about $2.2 trillion","claim":"Size of the CARES Act","basis":"Congressional Budget Office estimates; widely documented"},{"value":"about $1.9 trillion","claim":"Size of the American Rescue Plan","basis":"Enacted March 2021; widely documented"},{"value":"€750 billion","claim":"Size of NextGenerationEU","basis":"European Council conclusions, July 2020"},{"value":"0.1%","claim":"Bank of England Bank Rate from March 2020","basis":"Bank of England decision, 19 March 2020"},{"value":"4%","claim":"RBI repo rate from May 2020","basis":"RBI policy decision, May 2020"},{"value":"above 8% for four years","claim":"US unemployment 2009–2012 (annual averages)","basis":"Catalogue series us-unemp: 9.3, 9.6, 8.9, 8.1"}]}],"hash":"3323763b3627dae6"};
